                [JsonProperty(RU ? "Список префабов объектов, которые фермер может использовать" : "List of prefab entities that the farmer can use")]
                public List<string> ListPrefabs = new();

                public EntityFarmSetup()
                {
                }

                public EntityFarmSetup(bool enabled)
                {
                    this.enabled = enabled;
                }


                public bool HasEntity(BaseEntity entity)
                {
                    return Enabled() && entity && (ListPrefabs.Contains(entity.PrefabName) || ListPrefabs.Contains(entity.ShortPrefabName));
                }
                public bool Enabled() => enabled && ListPrefabs?.Count > 0;
            }
