        public class ItemInfo
        {
            [JsonIgnore] private const int order = 100;

            [JsonProperty(RU ? "Предмет" : "Item", Order = order + 10)]
            public ItemSetup item;

            [JsonProperty(RU ? "Свое название предмета (если не нужно оставьте пустым)" : "Custom item name (if not needed leave empty)", Order = order + 20)]
            public string name;

            [JsonProperty(RU ? "Количество" : "Amount", Order = order + 30)]
            public int amount;

            public bool TryGetItem(out Item _item)
            {
                _item = item.CreateItem(amount, name);
                return _item != null;
            }
            public bool AddItemToContainer(ItemContainer container)
            {
                if (container != null && TryGetItem(out var _item))
                {
                    if (_item.MoveToContainer(container)) return true;
                    else _item.Remove();
                }
                return false;
            }
        }
        public struct ItemSetup
        {
            [JsonProperty(RU ? "ShortName или ID предмета" : "Item shortname or ID")]
            private string shortNameOrId;

            [JsonProperty(RU ? "Скин предмета" : "Item skin")]
            public ulong SkinID;

            [JsonIgnore] private ItemDefinition _def;

            public ItemSetup(string shortNameOrId, ulong skin)
            {
                this.shortNameOrId = shortNameOrId;
                this.SkinID = skin;
                _def = null;
            }

            public Item CreateItem(int amount, string name = "")
            {
                if (string.IsNullOrEmpty(shortNameOrId)) return null;
                if (amount < 1) amount = 1;
                amount = amount == 0 ? 1 : Mathf.Abs(amount);
                Item result = null;
                if (int.TryParse(shortNameOrId, out int id)) result = ItemManager.CreateByItemID(id, amount, SkinID);
                if (result == null) result = ItemManager.CreateByName(shortNameOrId, amount, SkinID);
                if (result != null && !string.IsNullOrEmpty(name)) result.name = name;
                if (result == null) Debug.LogWarning(RU ? "Не создан предмет[{0}]" : "Item [{0}] not created", shortNameOrId);
                return result;
            }
            public ItemDefinition GetItemDefinition()
            {
                if (_def != null) return _def;
                if (string.IsNullOrEmpty(shortNameOrId)) return null;
                ItemDefinition result = null;
                if (int.TryParse(shortNameOrId, out int id)) result = ItemManager.FindItemDefinition(id);
                if (result == null) result = ItemManager.FindDefinitionByPartialName(shortNameOrId);
                return _def = result;
            }

            internal Item CreateItem()
            {
                return ItemManager.Create(GetItemDefinition(), 1, SkinID);
            }

        }
        public struct LangKeyValue
        {
            [JsonProperty(RU ? "Ключ локализации" : "Localization key")]
            public string Key;

            [JsonProperty(RU ? "Значение локализации" : "Localization value")]
            public string En;

            public LangKeyValue(string key, string en)
            {
                Key = key;
                En = en;
            }

            public void AddLang(Dictionary<string, string> langDictionary)
            {
                if (!string.IsNullOrEmpty(Key))
                {
                    if (!langDictionary.TryAdd(Key, !string.IsNullOrEmpty(En) ? En : Key))
                    {
                        Debug.LogWarning(RU ? "Ключ {0} уже существует" : "Key {0} already exists", Key);
                    }
                }
            }
        }
