        public class ItemUI
        {
            [JsonProperty(RU ? "Настройка предмета" : "Item setup", Order = 10)]
            public ItemSetup Item;

            public ItemUI()
            {
            }
            public ItemUI(string shortNameOrId, ulong skin)
            {
                Item = new(shortNameOrId, skin);
            }

            public ItemDefinition GetItemDefinition() => Item.GetItemDefinition();

            public bool EqualsItem(Item item2)
            {
                return EqualsItem(item2.info, item2.skin);
            }
            public bool EqualsItem(ItemDefinition def, ulong skin)
            {
                return GetItemDefinition() != null && def != null && def == GetItemDefinition() && skin == Item.SkinID;
            }
            public Item CreateItem()
            {
                return Item.CreateItem();
            }

        }
