        protected override void LoadDefaultConfig() => config = Configuration.GetDefault();
        protected override void LoadConfig()
        {
            base.LoadConfig();
            if (config == null)
            {
#if DefaultConfig
                LoadDefaultConfig();
#else
                    try
                    {
                        bool isLastRu = RU;
                        if(Interface.Oxide.DataFileSystem.ExistsDatafile($"{Name}/{FolderNameConfig}/lastLangRU"))
                        {
                            isLastRu = Interface.Oxide.DataFileSystem.ReadObject<bool>($"{Name}/{FolderNameConfig}/lastLangRU");
                        }
                        config = Config.ReadObject<Configuration>();
                        if (config == null || isLastRu != RU)
                        {
                            LoadDataConfig();
                        }

                    }
                    catch (Exception ex)
                    {
                        Debug.LogError("{0}", ex?.Message);
                        LoadDataConfig();
                    }
#endif
            }

            SaveConfig();
        }
        public void LoadDataConfig()
        {
            try
            {
                if (Interface.Oxide.DataFileSystem.ExistsDatafile($"{Name}/{FolderNameConfig}/config"))
                {
                    config = JsonConvert.DeserializeObject<Configuration>(Interface.Oxide.DataFileSystem.ReadObject<string>($"{Name}/{FolderNameConfig}/config"), settingsSerializer);
                    if (config != null)
                    {
                        Debug.LogWarning(RU ? "Данный конфигурации восстановлены из резервной копии" : "The configuration has been restored from backup");
                        return;
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.LogError("{0}", ex?.Message);
            }
            LoadDefaultConfig();
        }
        public void SaveDataConfig()
        {
            Interface.Oxide.DataFileSystem.WriteObject($"{Name}/{FolderNameConfig}/config", JsonConvert.SerializeObject(config, Formatting.Indented, settingsSerializer));
            Interface.Oxide.DataFileSystem.WriteObject($"{Name}/{FolderNameConfig}/lastLangRU", RU);
        }
        protected override void SaveConfig()
        {
            Config.WriteObject(config);
            SaveDataConfig();
        }
