        #region DataFarms
        private string folderName => "DataFarms";
        private Dictionary<ulong, DataFarm> dataFarms = new Dictionary<ulong, DataFarm>();
        public bool InitData(BuildingPrivlidge cup, SleepingBag bag, DataFarm dataFarm)
        {
            if (!config.FarmerBots.TryGetValue(bag.skinID, out FarmerSetup botSetup))
            {
                return false;
            }
            return CreateFarm(cup, bag, botSetup, null, dataFarm);
        }
        protected void LoadData()
        {
            int deletedFilesCounter = 0;
            try
            {
                var files = Interface.Oxide.DataFileSystem.GetFiles($"{Name}/{folderName}", "*.json");
                if (files != null && files.Length > 0)
                {
                    var d = DateTime.UtcNow.AddHours(2);
                    foreach (var file in files)
                    {
                        var nameFile = System.IO.Path.GetFileName(file).Replace(".json", "");
                        string namePath = GetDataPathName(nameFile);
                        if (LoadDataFarm(namePath, out var dataFarm))
                        {
                            if (!isWipe)
                            {
                                if (ulong.TryParse(nameFile, out ulong id))
                                {
                                    if (BaseNetworkable.serverEntities.Find(new(id)) is BuildingPrivlidge cup)
                                    {
                                        if (BaseNetworkable.serverEntities.Find(new(dataFarm.IdBag)) is SleepingBag bag)
                                        {
                                            dataFarms.Add(id, dataFarm);
                                            if (InitData(cup, bag, dataFarm))
                                            {
                                                #if DebugLog
                                                    Debug.Log(RU ? $"Ферма владельца [{dataFarm.OwnerId}] восстановлена..." : $"The farm of owner [{dataFarm.OwnerId}] has been restored...");
                                                #endif
                                                continue;
                                            }
                                            else
                                            {
                                                dataFarms.Remove(id);
                                                #if DebugLog
                                                    Debug.Log(RU ? "Не инициализирована ферма..." : "Farm data is not initialized...");
                                                #endif
                                            }
                                        }
                                        else
                                        {
                                            #if DebugLog
                                                Debug.Log(RU ? $"Не найден спальный мешок фермера по ид[{dataFarm.IdBag}]" : $"Not found farmer's sleeping bag by id [{dataFarm.IdBag}]");
                                            #endif
                                        }
                                    }
                                    else
                                    {
                                        #if DebugLog
                                            Debug.Log(RU ? $"Не найден шкаф фермы по ид[{id}]" : $"Not found farm cupboard by id [{id}]");
                                        #endif
                                    }
                                }
                            }
                            else
                            {
                                #if DebugLog
                                    Debug.Log(RU ? "Обнаружен вайп..." : "Wipe is detected...");
                                #endif
                            }
                        }
                        deletedFilesCounter++;
                        DeleteDataFarm(namePath);
                    }
                    #if DebugLog
                        Debug.Log(RU ? $"Дата ферм загружена(активных ферм[{dataFarms.Count}], удаленных записей ферм[{deletedFilesCounter}])." : $"Farms data is loaded (active farms [{dataFarms.Count}], deleted files [{deletedFilesCounter}]).");
                    #endif
                }
                else Debug.LogWarning(RU ? "Не найдены файлы ферм." : $"Not found farms data.");
            }
            catch (Exception ex)
            {
                Debug.LogWarning(RU ? $"Не найдена папка с файлами ферм. [{ex?.Message}]" : $"The folder with farms data is not found.[{ex?.Message}]");
            }
        }
        protected bool LoadDataFarm(string namePath, out DataFarm dataFarm)
        {
            dataFarm = null;
            if (Interface.Oxide.DataFileSystem.ExistsDatafile(namePath))
            {
                dataFarm = Interface.Oxide.DataFileSystem.ReadObject<DataFarm>(namePath);
            }
            return dataFarm != null;
        }
        protected void DeleteDataFarm(string namePath)
        {
            Interface.Oxide.DataFileSystem.DeleteDataFile(namePath);
            #if DebugLog
                Debug.Log(RU ? $"Удален дата файл [{namePath}]" : $"Deleted data file [{namePath}]");
            #endif
        }
        protected void SaveDataFarm(string namePath, DataFarm dataFarm) => Interface.Oxide.DataFileSystem.WriteObject(namePath, dataFarm);
        protected void SaveDataFarms()
        {
            PluginFarmerComponent.OnSaveDataFarms();
            foreach (var item in dataFarms)
            {
                SaveDataFarm(GetDataPathName(item.Key.ToString()), item.Value);
            }
        }
        public string GetDataPathName(string name) => $"{Name}/{folderName}/{name}";
