            public class PlantedData : BaseDataEntity
            {
                public bool CanClones = false;
                [JsonProperty("SeedsDisabled")] private List<int> seedsDisabled = new();
                public PlantedData()
                {
                }

                public PlantedData(UIDataEntity entityUI) : base(entityUI)
                {
                }

                public bool CanSeedUsed(ItemDefinition seedDef) => !seedsDisabled.Contains(seedDef.itemid) || seedsDisabled.Count == 0;
                public void AddSeed(int itemID)
                {
                    if (!seedsDisabled.Contains(itemID)) seedsDisabled.Add(itemID);
                    else RemoveSeed(itemID);

                }
                public void RemoveSeed(int itemID) => seedsDisabled.Remove(itemID);
                public bool CanSeedAllUsed() => seedsDisabled.Count == 0;
                public ItemDefinition GetSeedDef(IEnumerable<StorageComponent> storages)
                {
                    if (storages != null)
                    {
                        foreach (var storage in storages)
                        {
                            if (storage.IsValid == true)
                            {
                                if (storage.Inventory.itemList.Find(x => x?.IsValid() == true && instance.seeds.ContainsKey(x.info) && CanSeedUsed(x.info)) is Item item) return item.info;
                            }
                        }
                    }
                    return null;
                }
                public object Copy() => seedsDisabled.ToArray();
                public void Paste(object obj)
                {
                    if (obj is int[] paste)
                    {
                        seedsDisabled.Clear();
                        seedsDisabled.AddRange(paste);
                    }
                }
                public bool HasBuffer(object obj)
                {
                    if (obj is int[] paste)
                    {
                        if (paste.Length != seedsDisabled.Count) return false;
                        if (paste.Length == 0 && seedsDisabled.Count == 0) return true;
                        foreach (var id in paste) if (!seedsDisabled.Contains(id)) return false;
                        return true;
                    }
                    return false;
                }
            }
