            {
                [JsonProperty(nameof(StatsFarmer))] private StatsFarmer statsFarmer;
                [JsonProperty(nameof(StatsPlaned))] private StatsPlaned statsPlaned;
                [JsonProperty(nameof(StatsComposter))] private StatsComposter statsComposter;
                [JsonProperty(nameof(StatsChickenCoop))] private StatsChickenCoop statsChickenCoop;
                [JsonProperty(nameof(StatsBeehives))] private StatsBeehives statsBeehives;
                [JsonProperty(nameof(StatsResourcesCollected))] private StatsResourcesCollected statsPickupCollected;
                [JsonProperty(nameof(StatsMiningResource))] private StatsMiningResource statsMiningResource;

                [JsonIgnore] public List<IStatsGroup> statsGroups = new List<IStatsGroup>();
                [JsonIgnore] public bool CanUpdateUI = false;
                [JsonIgnore] public BasePlayer playerUI = null;
                [JsonIgnore] protected Func<string, string> langMethod;
                [JsonIgnore] protected const string layer = "stats.farm.";

                public StatsGeneral()
                {
                }

                [JsonIgnore] public StatsFarmer GetStatsFarmer => statsFarmer;
                public void Init(FarmerSetup config)
                {
                    if (statsFarmer == null) statsFarmer = new StatsFarmer();
                    statsGroups.Add(statsFarmer);
                    if (statsPlaned == null) if(config.Planters.Enabled()) statsPlaned = new StatsPlaned();
                    if(statsPlaned != null) statsGroups.Add(statsPlaned);
                    if (statsComposter == null) if (config.Fertilizer.Enabled()) statsComposter = new StatsComposter();
                    if (statsComposter != null) statsGroups.Add(statsComposter);
                    if (statsChickenCoop == null) if (config.Chickens.Enabled()) statsChickenCoop = new StatsChickenCoop();
                    if (statsChickenCoop != null) statsGroups.Add(statsChickenCoop);
                    if (statsBeehives == null) if (config.Beehives.Enabled()) statsBeehives = new StatsBeehives();
                    if (statsBeehives != null) statsGroups.Add(statsBeehives);
                    if (statsPickupCollected == null) if (config.Controller.CanPickupCollectibleItems) statsPickupCollected = new StatsResourcesCollected();
                    if (statsPickupCollected != null) statsGroups.Add(statsPickupCollected);
                    if (statsMiningResource == null) if (config.Controller.CanMining) statsMiningResource = new StatsMiningResource();
                    if (statsMiningResource != null) statsGroups.Add(statsMiningResource);
#if DebugLog
                    Debug.Log($"StatsGeneral Init: {statsGroups.Count}");
#endif
                }

                public void Reset() => statsGroups.ForEach(x =>
                {
                    x.Reset();
                    if (CanUpdateUI) x.UpdateUI(playerUI);
                });
                public bool Add(StatsType type, params object[] args)
                {
                    IStatsGroup statsGroup = statsGroups.Find(x => x.StatsType == type);
                    if (statsGroup == null) return false;
                    statsGroup.Add(CanUpdateUI, playerUI, args);
                    return true;
                }
                public void AddScrollUI(List<CuiElement> list, string parent, Func<string, string> langMethod)
                {
                    this.langMethod = langMethod;
                    var config = instance.UI_StatsConfig.ScrollPanel;
                    config.AddScrollPanelElement(
                        list, parent,
                        parent + ".scroll.panel",
                        parent + ".scroll.panel",
                        statsGroups.Count
                    );
                    config.AddContents(
                        list, parent + ".scroll.panel",
                        parent + ".scroll.panel.contents",
                        parent + ".scroll.panel.contents.element",
                        statsGroups.Count, AddElement
                    );
                }
                private void AddElement(List<CuiElement> list, int index, string parent)
                {
                    instance.UI_StatsConfig.Content.AddImageElement(
                        list, parent,
                        layer + index,
                        layer + index
                    );
                    statsGroups[index].AddElement(list, layer + index, langMethod);
                }

                public class StatsFarmer : StatsBase, IStatsGroup
                {
                    public Dictionary<int, int> ItemsUsed = new Dictionary<int, int>();
                    public float TimerLife = 0;
                    public float DeadCounter = 0;
                    public float DistanceTraveled = 0;
                    public StatsType StatsType => StatsType.Farmer;
                    protected override string layerTitle => ".stats_farmer.title";
                    protected override TextPanelUIConfig textConfig => instance.UI_StatsConfig.Content.StatsFarmer.Title;
                    protected override string title => "UI_TitleStatsFarmer";
                    protected override string layerBackground => ".stats_farmer.background";
                    protected override ImageUIConfig backgroundConfig => instance.UI_StatsConfig.Content.StatsFarmer;

                    public bool Add(bool canUpdate, BasePlayer player, params object[] args)
                    {
                        if (canUpdate) containerUpdate.Clear();
                        if (args.Length >= 1 && args[0] is FarmerType type)
                        {
                            switch (type)
                            {
                                case FarmerType.Life:
                                    {
                                        if (args.Length == 2 && args[1] is TimeSince num)
                                        {
                                            TimerLife += num;
                                            return true;
                                        }
                                        return false;
                                    }
                                case FarmerType.Distance:
                                    {
                                        if (args.Length == 2 && args[1] is float num)
                                        {
                                            DistanceTraveled += num;
                                            return true;
                                        }
                                        return false;
                                    }
                                case FarmerType.Dead:
                                    {
                                        DeadCounter++;
                                        return true;
                                    }
                                case FarmerType.UseItems:
                                    {
                                        if (args.Length == 3 && args[1] is int num && args[2] is int num2)
                                        {
                                            if (ItemsUsed.ContainsKey(num))
                                            {
                                                ItemsUsed[num] += num2;
                                                if (canUpdate)
                                                {
                                                    int index = ItemsUsed.IndexOff(num);
                                                    string parent = layerBackground + ".usedItems.panel.scroll.panel.contents.element" + index;
                                                    instance.UI_StatsConfig.Content.StatsPlanted.StatsItemsSeed.AmountItem.AddTextElement(
                                                        containerUpdate, parent,
                                                        parent + ".useItem.amount" + index + "",
                                                        parent + ".useItem.amount" + index + "",
                                                        "x" + ItemsUsed[num]
                                                    );
                                                    CuiHelper.AddUi(player, containerUpdate);
                                                }
                                            }
                                            else
                                            {
                                                ItemsUsed.Add(num, num2);
                                                if (canUpdate)
                                                {
                                                    SetScrollSeeds(containerUpdate);
                                                    CuiHelper.AddUi(player, containerUpdate);
                                                }
                                            }
                                            return true;
                                        }
                                        return false;
                                    }
                                    
                            }
                        }
                        return false;
                    }
                    public override void AddElement(List<CuiElement> list, string parent, Func<string, string> langMethod)
                    {
                        base.AddElement(list, parent, langMethod);

                        instance.UI_StatsConfig.Content.StatsFarmer.StatsInfoFarmer.AddTextPanelElement(
                            list, layerBackground,
                            layerBackground + ".stats.info.farmer",
                            layerBackground + ".stats.info.farmer.text",
                            layerBackground + ".stats.info.farmer",
                            ""
                        );
                        SetContent(list);
                    }
                    private void SetContent(List<CuiElement> list)
                    {
                        instance.UI_StatsConfig.Content.StatsFarmer.StatsItems.AddImageElement(
                            list, layerBackground,
                            layerBackground + ".usedItems.panel",
                            layerBackground + ".usedItems.panel"
                        );
                        instance.UI_StatsConfig.Content.StatsFarmer.StatsItems.TitlePanel.AddTextPanelElement(
                            list, layerBackground + ".usedItems.panel",
                            layerBackground + ".usedItems.panel.title",
                            layerBackground + ".usedItems.panel.title.text",
                            layerBackground + ".usedItems.panel.title",
                            langMethod("UI_TitleUsedItems")
                        );
                        instance.UI_StatsConfig.Content.StatsFarmer.StatsItems.ScrollPanel.AddScrollBackgroundElement(
                            list, layerBackground + ".usedItems.panel",
                            layerBackground + ".usedItems.panel.scroll.background",
                            layerBackground + ".usedItems.panel.scroll.background"
                        );
                        SetScrollSeeds(list);
                    }
                    private void SetScrollSeeds(List<CuiElement> list)
                    {
                        instance.UI_StatsConfig.Content.StatsFarmer.StatsItems.ScrollPanel.AddScrollPanelElement(
                            list, layerBackground + ".usedItems.panel.scroll.background",
                            layerBackground + ".usedItems.panel.scroll.panel",
                            layerBackground + ".usedItems.panel.scroll.panel",
                            ItemsUsed.Count
                        );
                        instance.UI_StatsConfig.Content.StatsFarmer.StatsItems.ScrollPanel.AddContents(
                            list, layerBackground + ".usedItems.panel.scroll.panel",
                            layerBackground + ".usedItems.panel.scroll.panel.contents",
                            layerBackground + ".usedItems.panel.scroll.panel.contents.element",
                            ItemsUsed.Count, AddSeedElement
                        );
                    }
                    private void AddSeedElement(List<CuiElement> list, int index, string parent)
                    {
                        var item = ItemsUsed.ElementAt(index);
                        list.Add(new CuiElement
                        {
                            Parent = parent,
                            Name = parent + ".useItem.background" + index,
                            DestroyUi = parent + ".useItem.background" + index,
                            Components =
                            {
                                FullScreenTransform,
                                instance.UI_StatsConfig.Content.StatsFarmer.StatsItems.BackgroundItem.CreateCuiImageComponent()
                            }
                        });
                        list.Add(new CuiElement
                        {
                            Parent = parent + ".useItem.background" + index,
                            Name = parent + ".useItem" + index,
                            DestroyUi = parent + ".useItem" + index,
                            Components =
                            {
                                FullScreenTransform,
                                new CuiImageComponent
                                {
                                    Color = "1 1 1 1",
                                    ItemId = item.Key,
                                    SkinId = 0,
                                }
                            }
                        });
                        instance.UI_StatsConfig.Content.StatsFarmer.StatsItems.AmountItem.AddTextElement(
                            list, parent + ".useItem.background" + index,
                            parent + ".useItem.amount" + index + "",
                            parent + ".useItem.amount" + index + "",
                            "x" + item.Value
                        );
                    }
                    public void Reset()
                    {
                        TimerLife = 0;
                        DeadCounter = 0;
                        DistanceTraveled = 0;
                        ItemsUsed.Clear();
                    }
                    public void UpdateUI(BasePlayer player)
                    {
                    }

                    public enum FarmerType
                    {
                        Life, Dead, Distance, UseItems
                    }

                    internal void Update_UI(BasePlayer player, string text)
                    {
                        containerUpdate.Clear();
                        instance.UI_StatsConfig.Content.StatsFarmer.StatsInfoFarmer.Text.AddTextElement(
                            containerUpdate, layerBackground + ".stats.info.farmer",
                            layerBackground + ".stats.info.farmer.text",
                            layerBackground + ".stats.info.farmer.text",
                            text
                        );
                        CuiHelper.AddUi(player, containerUpdate);
                    }

                }
