                    public bool Add(bool canUpdate, BasePlayer player, params object[] args)
                    {
                        if(canUpdate) containerUpdate.Clear();
                        if (args.Length >= 2 && args[0] is PlantedType type && args[1] is int num)
                        {
                            switch (type)
                            {
                                case PlantedType.Seeds:
                                    if (args.Length == 3 && args[2] is int num2)
                                    {
                                        if (SeedsPlanted.ContainsKey(num))
                                        {
                                            SeedsPlanted[num] += num2;
                                            if (canUpdate)
                                            {
                                                int index = SeedsPlanted.IndexOff(num);
                                                string parent = layerBackground + ".seeds.panel.scroll.panel.contents.element" + index;
                                                instance.UI_StatsConfig.Content.StatsPlanted.StatsItemsSeed.AmountItem.AddTextElement(
                                                    containerUpdate, parent,
                                                    parent + ".seed.amount" + index + "",
                                                    parent + ".seed.amount" + index + "",
                                                    "x" + SeedsPlanted[num]
                                                );
                                                CuiHelper.AddUi(player, containerUpdate);
                                            }
                                        }
                                        else
                                        {
                                            SeedsPlanted.Add(num, num2);
                                            if (canUpdate)
                                            {
                                                SetScrollSeeds(containerUpdate);
                                                CuiHelper.AddUi(player, containerUpdate);
                                            }
                                        }
                                        return true;
                                    }
                                    return false;
                                case PlantedType.Harvested:
                                    if (args.Length == 3 && args[2] is int num3)
                                    {
                                        if (Harvested.ContainsKey(num))
                                        {
                                            Harvested[num] += num3;
                                            if (canUpdate)
                                            {
                                                int index = Harvested.IndexOff(num);
                                                string parent = layerBackground + ".harvest.panel.scroll.panel.contents.element" + index;
                                                instance.UI_StatsConfig.Content.StatsPlanted.StatsItemsHarvest.AmountItem.AddTextElement(
                                                    containerUpdate, parent,
                                                    parent + ".harvest.amount" + index + "",
                                                    parent + ".harvest.amount" + index + "",
                                                    "x" + Harvested[num]
                                                );
                                                CuiHelper.AddUi(player, containerUpdate);
                                            }
                                        }
                                        else
                                        {
                                            Harvested.Add(num, num3);
                                            if (canUpdate)
                                            {
                                                SetScrollHarvest(containerUpdate);
                                                CuiHelper.AddUi(player, containerUpdate);
                                            }
                                        }
                                        return true;
                                    }
                                    return false;
                                case PlantedType.Fertilizer:
                                    FertilizerUsed += num;
                                    if (canUpdate)
                                    {
                                        instance.UI_StatsConfig.Content.StatsPlanted.StatsFertilizer.Item.Amount.AddTextElement(
                                            containerUpdate, layerBackground + ".fertilizer.panel.item",
                                            layerBackground + ".fertilizer.panel.item.amount",
                                            layerBackground + ".fertilizer.panel.item.amount",
                                            "x" + FertilizerUsed
                                        );
                                        CuiHelper.AddUi(player, containerUpdate);
                                    }
                                    return true;
                                case PlantedType.Water:
                                    WaterUsed += num;
                                    if (canUpdate)
                                    {
                                        instance.UI_StatsConfig.Content.StatsPlanted.StatsWaters.Item.Amount.AddTextElement(
                                            containerUpdate, layerBackground + ".waters.panel.item",
                                            layerBackground + ".waters.panel.item.amount",
                                            layerBackground + ".waters.panel.item.amount",
                                            "x" + WaterUsed
                                        );
                                        CuiHelper.AddUi(player, containerUpdate);
                                    }
                                    return true;
                            }
                        }
                        return false;
                    }
