                public class StatsComposter : StatsBase, IStatsGroup
                {
                    public Dictionary<int, int> ItemsComposted = new Dictionary<int, int>();
                    public int FertilizerCreated = 0;
                    public StatsType StatsType => StatsType.Composter;
                    protected override string layerTitle => ".stats_composter.title";
                    protected override TextPanelUIConfig textConfig => instance.UI_StatsConfig.Content.StatsComposter.Title;
                    protected override string title => "UI_TitleStatsComposter";
                    protected override string layerBackground => ".stats_composter.background";
                    protected override ImageUIConfig backgroundConfig => instance.UI_StatsConfig.Content.StatsComposter;

                    public bool Add(bool canUpdate, BasePlayer player, params object[] args)
                    {
                        if (args.Length == 2 && args[0] is int id && ItemManager.FindItemDefinition(id) != null && args[1] is int count)
                        {
                            if(canUpdate) containerUpdate.Clear();
                            if (ItemsComposted.ContainsKey(id))
                            {
                                ItemsComposted[id] += count;
                                if (canUpdate)
                                {
                                    int index = ItemsComposted.IndexOff(id);
                                    string parent = layerBackground + ".ItemsCompost.panel.scroll.panel.contents.element" + index;
                                    instance.UI_StatsConfig.Content.StatsComposter.StatsItemsCompost.AmountItem.AddTextElement(
                                        containerUpdate, parent,
                                        parent + ".ItemsCompost.amount" + index + "",
                                        parent + ".ItemsCompost.amount" + index + "",
                                        "x" + ItemsComposted[id]
                                    );
                                    CuiHelper.AddUi(player, containerUpdate);
                                }
                            }
                            else
                            {
                                ItemsComposted.Add(id, count);
                                if (canUpdate)
                                {
                                    SetScrollItemsCompost(containerUpdate);
                                    CuiHelper.AddUi(player, containerUpdate);
                                }
                            }
                            return true;
                        }
                        else if (args.Length == 1 && args[0] is int num)
                        {
                            FertilizerCreated += num;
                            if (canUpdate)
