                public class StatsChickenCoop : StatsBase, IStatsGroup
                {
                    public Dictionary<int, int> ChickensFoodAdded = new Dictionary<int, int>();
                    public int WaterAdded = 0;
                    public int ChickensAdded = 0;
                    public int EggsCollected = 0;
                    public StatsType StatsType => StatsType.ChickenCoop;
                    protected override string layerTitle => ".stats_chickencoop.title";
                    protected override TextPanelUIConfig textConfig =>  instance.UI_StatsConfig.Content.StatsChickenCoop.Title;
                    protected override string title => "UI_TitleStatsChickenCoop";
                    protected override string layerBackground => ".stats_chickencoop.background";
                    protected override ImageUIConfig backgroundConfig => instance.UI_StatsConfig.Content.StatsChickenCoop;

                    public bool Add(bool canUpdate, BasePlayer player, params object[] args)
                    {
                        if (args.Length >= 2 && args[0] is ChickenCoopType type)
                        {
                            if(canUpdate) containerUpdate.Clear();
                            switch (type)
                            {
                                case ChickenCoopType.EggsAdd:
                                    if (args.Length == 2 && args[1] is int num)
                                    {
                                        ChickensAdded += num;
                                        if (canUpdate)
                                        {
                                            instance.UI_StatsConfig.Content.StatsChickenCoop.StatsEggs.Item.Amount.AddTextElement(
                                                containerUpdate, layerBackground + ".StatsEggs.panel.item",
                                                layerBackground + ".StatsEggs.panel.item.amount",
                                                layerBackground + ".StatsEggs.panel.item.amount",
                                                "x" + ChickensAdded
                                            );
                                        }
                                        break;
                                    }
                                    return false;
                                case ChickenCoopType.WaterAdd:
                                    if (args.Length == 2 && args[1] is int num2)
                                    {
                                        WaterAdded += num2;
                                        if (canUpdate)
                                        {
                                            instance.UI_StatsConfig.Content.StatsChickenCoop.StatsWaters.Item.Amount.AddTextElement(
                                                containerUpdate, layerBackground + ".StatsWaters.panel.item",
                                                layerBackground + ".StatsWaters.panel.item.amount",
                                                layerBackground + ".StatsWaters.panel.item.amount",
                                                "x" + WaterAdded
                                            );
                                        }
                                        break;
                                    }
                                    return false;
                                case ChickenCoopType.EggsCollected:
                                    if (args.Length == 2 && args[1] is int num4)
                                    {
                                        EggsCollected += num4;
                                        if (canUpdate)
                                        {
                                            instance.UI_StatsConfig.Content.StatsChickenCoop.StatsEggsCollected.Item.Amount.AddTextElement(
                                                containerUpdate, layerBackground + ".StatsEggsCollected.panel.item",
                                                layerBackground + ".StatsEggsCollected.panel.item.amount",
                                                layerBackground + ".StatsEggsCollected.panel.item.amount",
                                                "x" + EggsCollected
                                            );
                                        }
                                        break;
                                    }
                                    return false;
                                case ChickenCoopType.FoodsAdded:
                                    if (args.Length == 3 && args[1] is int id && ItemManager.FindItemDefinition(id) is ItemDefinition def && instance.chickensFood.Contains(def) && args[2] is int num3)
                                    {
                                        if (ChickensFoodAdded.ContainsKey(id))
                                        {
                                            ChickensFoodAdded[id] += num3;
                                            if (canUpdate)
                                            {
                                                int index = ChickensFoodAdded.IndexOff(id);
                                                string parent = layerBackground + ".FeedChicken.panel.scroll.panel.contents.element" + index;
                                                instance.UI_StatsConfig.Content.StatsChickenCoop.StatsItemsFeed.AmountItem.AddTextElement(
                                                    containerUpdate, parent + ".FeedChicken.background" + index,
                                                    parent + ".FeedChicken.amount" + index + "",
                                                    parent + ".FeedChicken.amount" + index + "",
                                                    "x" + ChickensFoodAdded[id]
                                                );
                                                break;
                                            }
                                        }
                                        else
                                        {
                                            ChickensFoodAdded.Add(id, num3);
                                            if (canUpdate) SetScrollFeedChicken(containerUpdate);
                                            break;
                                        }
                                        return false;
                                    }
                                    return false;
                                default: return false;
                            }
                            if(canUpdate) CuiHelper.AddUi(player, containerUpdate);
                            return true;
                        }
                        return false;
                    }

                    public void Reset()
                    {
                        ChickensFoodAdded.Clear();
                        WaterAdded = 0;
                        ChickensAdded = 0;
                        EggsCollected = 0;
                    }

