        #region InitHooks
        private void Init()
        {
            instance = this;
            LoadRustLocalization();
            BrainFarmer.BaseJob.InitPlugin();
            BotIdGenerator.InitPlugin();
            PluginFarmerComponent.InitPlugin();
            PluginEntityFarmComponent.InitPlugin();
            PluginFarmManagerComponent.InitPlugin();
            Unsubscribe("OnEntitySpawned");
            Unsubscribe("OnItemUse");
            LoadUIConfig();
        }
        private void OnServerInitialized()
        {
            foreach (var perm in config.FarmerBots.Values)
            {
                if (!string.IsNullOrEmpty(perm.CreateFarmer.Permission) && !permission.PermissionExists(perm.CreateFarmer.Permission)) permission.RegisterPermission(perm.CreateFarmer.Permission, this);
            }
            foreach (var def in ItemManager.itemList)
            {
                if (def.shortname.StartsWith("seed."))
                {
                    if (def.TryGetComponent<ItemModDeployable>(out var deployable) && deployable.entityPrefab.GetEntity().TryGetComponent<GrowableEntity>(out var growable))
                    {
                        seeds.Add(def, growable.SourceItemDef);
                    }
                }
                if (def.TryGetComponent<ItemModConsumable>(out var consumable))
                {
                    if (consumable.chickenCoopFood) chickensFood.Add(def);
                    if (CanFoodToFarmer(consumable)) farmerFood.Add(def);
                }
                if (def.HasComponent<ItemModFoodSpoiling>()) foodsSpoiling.Add(def);
                if (def.HasComponent<ItemModCompostable>()) composterItems.Add(def);
            }
            foreach (var category in Enum.GetValues(typeof(ItemCategory)))
            {
                if ((ItemCategory)category == ItemCategory.All || (ItemCategory)category == ItemCategory.Search || (ItemCategory)category == ItemCategory.Favourite || (ItemCategory)category == ItemCategory.Common) continue;
                categoriesAll.Add((ItemCategory)category);
            }
#if DebugLog
            Debug.Log("\nSeeds: " + seeds.Count + "\nChickensFood: " + chickensFood.Count + "\nFarmerFood: " + farmerFood.Count + "\nFoodsSpoiling: " + foodsSpoiling.Count + "\nComposterItems: " + composterItems.Count);
            Debug.Log("\nRust's localization packages loaded: " + localization.Count);
#endif

            LoadData();
            Subscribe("OnEntitySpawned");
            Subscribe("OnItemUse");
        }
        private void Unload()
        {
            SaveDataFarms();
            PluginFarmManagerComponent.UnloadPlugin();
            PluginEntityFarmComponent.UnloadPlugin();
            PluginFarmerComponent.UnloadPlugin();
            BotIdGenerator.UnloadPlugin();
            BrainFarmer.BaseJob.UnloadPlugin();
            instance = null;
        }
