        #region Methods
        public static bool IsBuildingPrivlidge(Vector3 pos, BuildingPrivlidge cup)
        {
            if (cup?.IsValid() != true) return false;
            OBB obb = new(pos, Vector3.one, Quaternion.identity);
            BuildingBlock other = null;
            BuildingPrivlidge buildingPrivlidge = null;
            List<BuildingBlock> obj2 = Pool.Get<List<BuildingBlock>>();
            Vis.Entities(obb.position, 16f + obb.extents.magnitude, obj2, 2097152);
            for (int i = 0; i < obj2.Count; i++)
            {
                BuildingBlock buildingBlock = obj2[i];
                if (!buildingBlock.IsOlderThan(other) || obb.Distance(buildingBlock.WorldSpaceBounds()) > 16f)
                {
                    continue;
                }

                BuildingManager.Building building = buildingBlock.GetBuilding();
                if (building != null)
                {
                    BuildingPrivlidge dominatingBuildingPrivilege = building.GetDominatingBuildingPrivilege();
                    if (dominatingBuildingPrivilege != null)
                    {
                        other = buildingBlock;
                        buildingPrivlidge = dominatingBuildingPrivilege;
                    }
                }
            }

            Pool.FreeUnmanaged(ref obj2);
            return buildingPrivlidge == cup;

        }
        protected void LoadRustLocalization()
        {
            List<string> languages = Pool.Get<List<string>>();
            languages.AddRange(lang.GetLanguages(this));
            foreach (var langue in GetLocalization())
            {
                if (!localization.ContainsKey(langue.Key))
                {
                    if (languages.Exists(x => x.ToLower() == langue.Key)) localization.Add(langue.Key, langue.Value);
                }
                else foreach (var token in langue.Value) localization[langue.Key].TryAdd(token.Key, token.Value);
            }
            Pool.FreeUnmanaged(ref languages);
        }
        public IEnumerable<KeyValuePair<string, Dictionary<string, string>>> GetLocalization()
        {
            foreach (var item in AssetBundle.GetAllLoadedAssetBundles())
            {
                if (item?.name == "shared/content.bundle")
                {
                    var names = FileSystem.FindAll("assets/localization/");
                    if (names != null)
                    {
                        foreach (var name in names)
                        {
                            string[] parts = name.Split(new[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
                            string language = "";
                            if (parts.Length >= 3) language = parts[2];
                            if (!string.IsNullOrEmpty(language) && item.LoadAsset<TextAsset>(name) is TextAsset textAsset)
                            {
                                yield return new KeyValuePair<string, Dictionary<string, string>>(language, JsonConvert.DeserializeObject<Dictionary<string, string>>(textAsset.text));
                            }
                        }
                    }
                    yield break;
                }
            }
        }
        public bool CanFoodToFarmer(ItemModConsumable consumable)
        {
            bool can = false;
            if (consumable?.effects != null)
            {
                foreach (var effect in consumable.effects)
                {
                    if (effect.type == MetabolismAttribute.Type.Bleeding && effect.amount > 0) return false;
                    if (effect.type == MetabolismAttribute.Type.Radiation && effect.amount > 0) return false;
                    if (effect.type == MetabolismAttribute.Type.Poison && effect.amount > 0) return false;
                    if (effect.type == MetabolismAttribute.Type.Hydration && effect.amount < 0) return false;
                    if (effect.type == MetabolismAttribute.Type.Calories && effect.amount > 0) can = true;
                }
            }
            return can;
        }
        public void CreateFarm(SleepingBag entity)
        {
            if (entity?.IsValid() == true && config.FarmerBots.TryGetValue(entity.skinID, out FarmerSetup botSetup) && BasePlayer.FindByID(entity.OwnerID) is BasePlayer player && player.IsConnected)
            {
                if (entity.GetBuildingPrivilege() is BuildingPrivlidge cup)
                {
                    CreateFarm(cup, entity, botSetup, player);
                }
                else ChatMessage(player, "CreateFarmer_NotBuildingPrivlidge");
            }
        }
        public bool CreateFarm(BuildingPrivlidge cup, SleepingBag bag, FarmerSetup botSetup, BasePlayer player = null, DataFarm dataFarm = null)
        {
            if (!PluginFarmManagerComponent.Contains(cup))
            {
                bool isNewFarm = dataFarm == null;
                if (isNewFarm)
                {
                    dataFarm = new DataFarm(botSetup, bag.net.ID.Value, player.userID, player.displayName, BotIdGenerator.GenerateBotId(player.UserIDString, instance.config.GetDigits()));
                    dataFarms[cup.net.ID.Value] = dataFarm;
                }
                else BotIdGenerator.AddID(dataFarm.FarmerId);
                string userId = dataFarm.OwnerId.ToString();
                dataFarm.Stats.Init(botSetup);
                if (string.IsNullOrEmpty(botSetup.CreateFarmer.Permission) || permission.UserHasPermission(userId, botSetup.CreateFarmer.Permission))
                {
                    var manager = cup.gameObject.AddComponent<FarmManager>();
                    SleepingComponent _bag = bag.gameObject.AddComponent<SleepingComponent>();

                    manager.Settings = botSetup;
                    _bag.Init(manager);
                    manager.SpawnFarmer(false, isNewFarm);
                    ChatMessage(player, "CreateFarmer_InitializationFarmStart");
                    return true;
                }
                else ChatMessage(player, "CreateFarmer_NotDeployedPermission");
            }
            else ChatMessage(player, "CreateFarmer_HasFarmerThisFarm");

            return false;
        }
        public Item CreateItemSleepingBag(BasePlayer owner, string itemName, ulong skinID, int amount = 1)
        {
            Item sleepingBag = ItemManager.CreateByName("sleepingbag", amount, skinID);
            if (sleepingBag != null)
            {
                if (!string.IsNullOrEmpty(itemName)) sleepingBag.name = itemName;
                sleepingBag.SetItemOwnership(owner, "Owner");
            }
            return sleepingBag;
        }
