        #region Commands
        [Command(CommandAdminGiveSleepingBag), Permission(AdminPermission)]
        private void Cmd_AdminGiveSleepingBag(Core.Libraries.Covalence.IPlayer pl, string cmd, string[] args)
        {
            int length = args?.Length ?? 0;
            if (pl?.Object is BasePlayer admin || pl?.IsServer == true)
            {
                if (length >= 1)
                {
                    if (BasePlayer.FindAwakeOrSleeping(args[0]) is BasePlayer findPlayer)
                    {
                        if (args.Length >= 2 && ulong.TryParse(args[1], out ulong skin) && config.FarmerBots.TryGetValue(skin, out var botSetup))
                        {
                            int amount = 1;
                            if (args.Length >= 3 && !int.TryParse(args[2], out amount)) amount = 1;
                            if (amount <= 0) amount = 1;
                            Item sleepingBag = CreateItemSleepingBag(findPlayer, GetLangText(findPlayer.UserIDString, botSetup.CreateFarmer.NameFarmer.Key).Replace("%OWNER_NAME%", findPlayer.displayName), skin, amount);
                            if (sleepingBag != null)
                            {
                                findPlayer.GiveItem(sleepingBag);
                                ChatMessage(findPlayer, "CreateFarmer_GiveFarmerBag");
                                #if DebugLog
                                    Debug.Log(RU ? $"Спальный мешок фермера успешно выдана игроку: {findPlayer.displayName}" : $"The farmer's sleeping bag was successfully issued to the player: {findPlayer.displayName}");
                                #endif
                            }
                            else
                            {
                                Debug.LogWarning(RU ? $"Спальный мешок фермера не создан, проверьте вводимые данные" : $"The farmer's sleeping bag was not created, check the entered data");
                            }
                        }

                    }
                    else
                    {
                        Debug.LogWarning(RU ? $"Игрок не найден или не загружен" : $"Player not found or not loaded");
                    }
                }
                else
                {
                    Debug.LogWarning(RU ? $"Неверный формат команды, проверьте вводимые данные" : $"Incorrect command format, check the entered data");
                }
            }
        }

        [Command(CommandPlayerGiveSleepingBag)]
        private void Cmd_PlayerGiveSleepingBag(Core.Libraries.Covalence.IPlayer pl, string cmd, string[] args)
        {
            int length = args?.Length ?? 0;
            if (pl?.Object is BasePlayer player)
            {
                List<(ulong, FarmerSetup)> listBots = Pool.Get<List<(ulong, FarmerSetup)>>();
                string arg = "";
                if (length > 0) arg = args[0].ToLower();
                bool isCommand = !string.IsNullOrEmpty(arg);
                foreach (var item in config.FarmerBots)
                {
                    if (!item.Value.CanPlayerUseCommand(player)) continue;
                    if (isCommand && item.Value.CreateFarmer.Command.ToLower() != arg) continue;
                    listBots.Add((item.Key, item.Value));
                }
                if (listBots.Count > 0)
                {
                    if (listBots.Count == 1) player.Invoke(() => server.Command(CommandAdminGiveSleepingBag, player.UserIDString, listBots[0].Item1), 0.1f);
                    else
                    {
                        string text = "";
                        listBots.ForEach(x => text += "\n" + x.Item2.CreateFarmer.Command);
                        ChatMessage(player, "CreateFarmer_ListFarmersToUseCommand", text);
                    }
                }
                else
                {
                    ChatMessage(player, "CreateFarmer_NotFoundFarmersToUseCommand");
                }
            }
        }
