                    sorted.capacity = sorted.itemList.Count;
                    return !sorted.IsEmpty();
                }
            }


            #region UnityCallbacks
            protected override void Awake()
            {
                base.Awake();
                sorted = Pool.Get<ItemContainer>();
                sorted.ServerInitialize(null, 2);
                Data = instance.dataFarms[netId];
                OwnerIdString = Data.OwnerId.ToString();
                // ZoneFarm = new Rect(new Vector2(owner.transform.position.x - (Settings.Controller.ZoneFarm.x / 2), owner.transform.position.z - (Settings.Controller.ZoneFarm.y / 2)), Settings.Controller.ZoneFarm);
                Navigation = gameObject.AddComponent<NavigationFarm>();
                if (Data.UISetup.Farm.CanSendLogToChat) SubscribeLogs(ChatMessageOwnerPlayer);
                if (Data.UISetup.Farm.CanSendLogToConsole) SubscribeLogs(ConsoleMessageOwnerPlayer);
                SendLogFarmer.AddListener(AddLog);
                InvokeRepeating(StatusFarmerUpdate, UpdateStatus, UpdateStatus);
                Invoke(CreateUI, 0.5f);
#if DrawTest
                InvokeRepeating(DrawFarm, 1f, 1f);
#endif
            }
            protected override void OnDestroy()
            {
                base.OnDestroy();
                SendStatusFarmer.RemoveAllListeners();
                SendLogFarmer.RemoveAllListeners();
                bool removeData = IsValid != true;
                if (Bag?.IsValid == true) Bag.KillImmediate();
                else removeData = true;

                if (removeData)
                {
                    BotIdGenerator.RemoveID(Data.FarmerId);
                    Farmer?.SetLootToDrop();
                    ClearSortedContainer();
                    Farmer?.GetNpc()?.AdminKill();
                    if (IsValid == true)
                    {
                        owner.authorizedPlayers.RemoveWhere((ProtoBuf.PlayerNameID x) => x.userid == Data.FarmerId);
                        DestroyImmediate(Navigation);
                    }
                    RemoveData();
                }
                else
                {
                    Farmer.SendStatsTimerLife();
                    Data.LastTimerLife = Farmer?.GetTimerLife??0;
                    Data.Stats.GetStatsFarmer.TimerLife -= Data.LastTimerLife;
                    Farmer.KillImmediate();
                    DestroyImmediate(Navigation);
                }
                Pool.Free(ref sorted);

                buttonOpenUI?.CloseUI();
                UIManager?.CloseUI();
            }
            #endregion

            #region Methods
            public bool IsZoneFarmEntity(BaseEntity entity) => entity?.IsValid() == true && PersonalFarmerEx.PersonalFarmerEx.ContainsVector3(ZoneFarm, entity.transform.position) || entity.GetBuildingPrivilege() == owner;
            private void ClearSortedContainer()
            {
                if (sorted.itemList.Count > 0)
                {
                    foreach (var storage in GetFarmAccessEntity<StorageComponent>(Navigation.Storages.ToArray(), x => !x.Inventory.IsFull()))
                    {
                        int num = storage.Inventory.capacity - storage.Inventory.itemList.Count;
                        for (int i = 0; i < num; i++)
                        {
                            Item item = sorted.itemList[i];
                            if (storage.Inventory.Insert(item)) sorted.itemList.Remove(item);
                        }
                        if (sorted.itemList.Count == 0) break;
                    }
                }
                else return;
                if (sorted.itemList.Count > 0)
                {
                    int num = sorted.itemList.Count > 48 ? 48 : sorted.itemList.Count;
                    Vector3 pos = Farmer?.GetNpc()?.IsValid() == true ? Farmer.GetNpc().transform.position : Bag?.IsValid == true ? Bag.transform.position : transform.TransformPoint(Vector3.forward + Vector3.up * 0.2f);
                    var backpack = GameManager.server.CreateEntity("assets/prefabs/misc/item drop/item_drop_backpack.prefab", pos, Quaternion.identity) as DroppedItemContainer;

                    backpack.inventory = new ItemContainer();
                    backpack.inventory.ServerInitialize(null, num);
                    backpack.inventory.GiveUID();
                    sorted.MoveAllItems(backpack.inventory);
                    for (int i = 0; i < num; i++)
                    {
                        Item item = sorted.itemList[i];
                        if (backpack.inventory.Insert(item)) sorted.itemList.Remove(item);
                    }
                    backpack.inventory.SetFlag(ItemContainer.Flag.NoItemInput, true);
                    backpack.ResetRemovalTime();
                    backpack.EnableSaving(false);
                    backpack.Spawn();
                }
                else return;
                if (sorted.itemList.Count > 0)
                {
                    Vector3 pos = Farmer?.GetNpc()?.IsValid() == true ? Farmer.GetNpc().transform.position : Bag?.IsValid == true ? Bag.transform.position : transform.TransformPoint(Vector3.forward + Vector3.up * 0.2f);
                    int num = sorted.itemList.Count;
                    for (int i = 0; i < num; i++)
                    {
                        Item item = sorted.itemList[i];
                        item.Drop(pos, Vector3.up * 5f);
                    }
                }
            }
            public override bool ContainsFarmPoint(Vector3 point) => PersonalFarmerEx.PersonalFarmerEx.ContainsVector3(ZoneFarm, point);
            public override void AddEntity(BaseEntity entity)
            {
                if ((entity is BuildingBlock or SimpleBuildingBlock) && entity.GetBuildingPrivilege() == owner)
                {
                    IsNewInitializationRequired = true;
                    SendLog("LogFarmer_NewInitializationRequired");
                    return;
                }
                if (IsInitFarm && entity?.IsValid() == true) Navigation.AddFarmEntity(entity);
            }
            public BasePlayer GetOwnerPlayer() => Farmer?.GetOwnerPlayer;
            public void SendLog(string key, params object[] args)
            {
                if (string.IsNullOrEmpty(key)) return;
                string log = GetLangText(key, args);
                if (string.IsNullOrEmpty(log)) return;
                if(lastAddLog < 60f && Data.logs.Count > 0 && Data.logs[0].EndsWith(log)) return;

                SendLogFarmer?.Invoke(log);
            }
            public void SubscribeLogs(UnityAction<string> callback)
            {
                UnSubscribeLogs(callback);
                SendLogFarmer.AddListener(callback);
            }
            public void UnSubscribeLogs(UnityAction<string> callback) => SendLogFarmer.RemoveListener(callback);
            public void SubscribeStatusFarmer(UnityAction<BasePlayer> callback)
            {
                UnSubscribeStatusFarmer(callback);
                SendStatusFarmer.AddListener(callback);
            }
            public void UnSubscribeStatusFarmer(UnityAction<BasePlayer> callback) => SendStatusFarmer.RemoveListener(callback);
            public void ChatMessageOwnerPlayer(string message)
            {
                if (ownerPlayerOnline?.IsConnected == true)
                {
                    ownerPlayerOnline.ChatMessage("[FARMER]: " + message);
                }
            }
            public void ConsoleMessageOwnerPlayer(string message)
            {
                if (ownerPlayerOnline?.IsConnected == true)
                {
                    ownerPlayerOnline.ConsoleMessage("[FARMER]: " + message);
                }
            }
            public string GetLangText(string key, params object[] args) => instance?.GetLangText(OwnerIdString, key, args);
            public string GetLangText(Translate.Phrase phrase) => instance?.GetLangText(OwnerIdString, phrase);
            private void RemoveData()
            {
                instance.dataFarms.Remove(netId);
                instance.DeleteDataFarm(instance.GetDataPathName(netId.ToString()));
            }
            public void OnKillBag()
            {
                if (owner?.IsValid() == true)
                {
                    DestroyImmediate(this);
                }
            }
            public void InitializationFarm()
            {
                ZoneFarm = new Rect(new Vector2(owner.transform.position.x - (Settings.Controller.ZoneFarm.x / 2), owner.transform.position.z - (Settings.Controller.ZoneFarm.y / 2)), Settings.Controller.ZoneFarm);
                Navigation.CreateRouter();
                Farmer.Brain.SetStatus(BrainFarmer.StatusFarmer.Initialization);
            }
