            public void MoveTo(Vector3 target, UnityAction<bool> onFinished) => NextTick(() =>
            {
                try
                {
                    Farmer?.SetDestination(target, onFinished);
                }
                catch (Exception ex)
                {
                    Debug.LogError(RU ? $"Ошибка при перемещении фермера: {ex}" : $"Error moving farmer: {ex}");
                }
            });
            private void StatusFarmerUpdate()
            {
                try
                {
                    if (!ownerPlayerOnline) ownerPlayerOnline = GetOwnerPlayer();
                    if (ownerPlayerOnline?.IsConnected == true && (ownerPlayerOnline.GetBuildingPrivilege() == owner || PersonalFarmerEx.PersonalFarmerEx.ContainsVector3(ZoneFarm, ownerPlayerOnline.ServerPosition)))
                    {
                        bool isAdmin = ownerPlayerOnline.IsAdmin;
                        if (!isAdmin) ownerPlayerOnline.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, true);
                        SendStatusFarmer?.Invoke(ownerPlayerOnline);
                        if (!isAdmin) ownerPlayerOnline.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, false);
                    }
                    else
                    {
                        if (isOpenUI) CloseUI();
                    }
                }
                catch (Exception ex)
                {
                    Debug.LogError(RU ? $"Ошибка при обновлении статуса фермера: {ex}" : $"Error updating farmer status: {ex}");
                }
            }
            public void RespawnFarmer()
            {
                if(IsInitFarm) Navigation.StopAllCoroutines();
                Invoke(() => SpawnFarmer(true, false), 3f);
            }
            public void SpawnFarmer(bool isRespawn, bool isNewFarm)
            {
                var farmer = GameManager.server.CreateEntity(PrefabBot, Bag.ServerPosition, Bag.ServerRotation) as NPCPlayer;
                if (farmer)
                {
                    farmer.OwnerID = Data.OwnerId;
                    farmer.OwnerID = Data.OwnerId;
                    farmer.userID.Set(Data.FarmerId);
                    farmer.UserIDString = farmer.userID.Get().ToString();
                    farmer.Spawn();

                    farmer.InitializeHealth(Settings.CreateFarmer.MaxHealth, Settings.CreateFarmer.MaxHealth);
                    farmer.inventory.Strip();
                    farmer.displayName = GetLangText(Settings.CreateFarmer.NameFarmer.Key).Replace("%OWNER_NAME%", Data.OwnerName);
                    farmer.inventory.containerBelt.capacity = 1;
                    if (isNewFarm)
                    {
                        foreach (var itemInfo in Settings.CreateFarmer.Clothes.items)
                        {
                            if (itemInfo.TryGetItem(out Item item))
                            {
                                if (!item.MoveToContainer(farmer.inventory.containerWear)) item.Remove();
                            }
                        }
                        Data.AddItemsFarmer(farmer);
                    }
                    else
                    {
                        Data.RestoredInventory(farmer);
                        if(!isRespawn) Data.RestoredSorted(sorted);
                    }
                    SleepingBag bag = Bag.GetEntity<SleepingBag>();

                    if (!isRespawn)
                    {
                        bag.SetDeployedBy(farmer);
                        SleepingBag.OnBagChangedOwnership(bag, bag.OwnerID);
                    }

                    farmer.inventory.containerWear.SetFlag(ItemContainer.Flag.IsLocked, !Settings.CreateFarmer.Clothes.CanUnlock);

                    Farmer = farmer.gameObject.AddComponent<FarmerController>();
                    Farmer.Init(this);
                    if (!isRespawn) Farmer.SetTimerLife(Data.LastTimerLife);
                    instance.SaveDataFarm(instance.GetDataPathName(netId.ToString()), Data);
                    
                    if(!Navigation.IsInitMap) InitializationFarm();
                }
            }
            public bool CanComposter(Item item)
            {
                bool compost = false;
                if (item != null && Data.UISetup.Fertilizers.ComposterItems.TryGetValue(item.info.itemid, out var expiration))
                {
                    compost = true;
                    if (item.info.TryGetComponent<ItemModFoodSpoiling>(out var mod) && expiration)
                    {
                        compost = item.instanceData.dataFloat / (3600 * mod.TotalSpoilTimeHours) < Data.UISetup.Farm.PercentSpoiling;
                    }
                }
                return compost;
            }
            public bool CanFoodToChickens(Item item)
            {
                bool compost = false;
                if (item != null && Data.UISetup.Chickens.FoodItems.TryGetValue(item.info.itemid, out var expiration))
                {
                    compost = true;
                    if (item.info.TryGetComponent<ItemModFoodSpoiling>(out var mod) && expiration)
                    {
                        compost = item.instanceData.dataFloat / (3600 * mod.TotalSpoilTimeHours) < Data.UISetup.Farm.PercentSpoiling;
                    }
                }
                return compost;
            }
            public void SortedContainerOrderBy()
            {
                var sortedItems = sorted.itemList.OrderBy(item => item.info.shortname);

                for (int i = 0; i < sortedItems.Count; i++)
                {
                    sortedItems[i].position = i;
                }
            }
            public void StartSortedStorages()
            {
                List<Item> items = Pool.Get<List<Item>>();
                foreach (var container in GetFarmAccessEntity<StorageComponent>(Navigation.Storages.ToArray(), x => !x.Inventory.IsEmpty()))
                {
                    sorted.capacity += container.Inventory.capacity;
                    items.Clear();
                    items.AddRange(container.Inventory.itemList);
                    for (int i = 0; i < items.Count; i++)
                    {
                        items[i].MoveToContainer(sorted);
                    }
                }
                Pool.FreeUnmanaged(ref items);
            }
            public void SaveSorted()
            {
                Data.AddItemsSorted(sorted);
            }
            #endregion

            #region Coroutines
            public void NextTick(UnityAction action) => StartCoroutine(NextTickCoroutine(action));
            IEnumerator NextTickCoroutine(UnityAction action)
            {
                yield return CoroutineEx.waitForFixedUpdate;
                action?.Invoke();
            }
            #endregion
            public override void KillImmediate()
            {
                DestroyImmediate(this);
            }

            public static IEnumerable<T> GetFarmAccessEntity<T>(IFarmComponent[] list) where T : IFarmComponent
            {
                foreach (var obj in list)
                {
                    if (obj != null && obj.IsValid && obj.CanAccessFarmer && obj is T result)
                    {
                        yield return result;
                    }
                }
            }
            public static IEnumerable<T> GetFarmAccessEntity<T>(IFarmComponent[] list, Func<T, bool> func) where T : IFarmComponent
            {
                foreach (var obj in list)
                {
                    if (obj != null && obj.IsValid && obj.CanAccessFarmer && obj is T result && (func == null || func(result)))
                    {
                        yield return result;
                    }
                }
            }
            public static IEnumerable<StorageComponent> GetFarmAccessEntity(List<StorageComponent> list)
            {
                foreach (var obj in list)
                {
                    if (obj != null && obj.IsValid && obj.CanAccessFarmer)
                    {
                        yield return obj;
                    }
                }
            }
        }
        public partial class NavigationFarm : FacepunchBehaviour
        {
            private const float timerYieldReturn = 0.01f;
