                farm.IsNewInitializationRequired = false;
                StopAllCoroutines();
                StartCoroutine(InitFarmObjectsCoroutine2());
            }
            public void SearchPath(Vector3 start, Vector3 end, bool canCheckDepth, UnityAction<Vector3[], Router.Response> pathResponse)
            {
                generalFinderPath.FindPath(canCheckDepth, start, end, pathResponse);
