            /// <summary>
            /// Searches for the closest point in the farm navigation mesh
            /// </summary>
            /// <param name="point">the point to search relative to</param>
            /// <returns>Returns the closest point</returns>
            public Vector3 GetNearestPoint(Vector3 point)
            {
                float minDistance = float.MaxValue;
                Vector3 nearestPoint = Vector3.zero;
                foreach (var pointRoute in farmPoints.Keys)
                {
                    float distance = Vector3.Distance(pointRoute, point);
                    if (distance < minDistance)
                    {
                        minDistance = distance;
                        nearestPoint = pointRoute;
                    }
                }
                return nearestPoint;
            }
            public void AddFarmEntity(BaseEntity entity)
            {
                if (entity is BuildingBlock) return;
                bool IsZoneCup = entity.GetBuildingPrivilege() == farm.GetCup();
                bool IsZoneFarm = IsZoneCup || PersonalFarmerEx.PersonalFarmerEx.ContainsVector3(farm.ZoneFarm, entity.transform.position);
                if(!IsZoneFarm) return;
                if (entity is DroppedItem)
                {
                    if (farm.Settings.Controller.CanPickupDroppedItems)
                    {
                        DropItemComponent component = entity.gameObject.AddComponent<DropItemComponent>();
                        component.Init(farm);
                        DropItems.Add(component);
                    }
                }
                else if (entity is NaturalBeehive)
                {

                }
                else if (entity is CollectibleEntity)
                {
                    if (farm.Settings.Controller.CanPickupCollectibleItems)
                    {
                        CollectibleEntityComponent component = entity.gameObject.AddComponent<CollectibleEntityComponent>();
                        component.Init(farm);
                        CollectibleEntities.Add(component);
                    }
                }
                else if (entity is OreResourceEntity)
                {
                    if (farm.Settings.Controller.CanMining)
                    {
                        OreResourceEntityComponent component = entity.gameObject.AddComponent<OreResourceEntityComponent>();
                        component.Init(farm);
                        ResourceEntities.Add(component);
                    }
                }
                else if (IsZoneCup)
                {
                    if (entity is PlanterBox)
                    {
                        if (farm.Settings.Planters.HasEntity(entity))
                        {
                            PlanterComponent planterComponent = entity.gameObject.AddComponent<PlanterComponent>();
                            planterComponent.Init(farm);
                            Planters.Add(planterComponent);
                        }
                    }
                    else if (entity is Composter)
                    {
                        if (farm.Settings.Fertilizer.HasEntity(entity))
                        {
                            FertilizerComponent fertilizerComponent = entity.gameObject.AddComponent<FertilizerComponent>();
                            fertilizerComponent.Init(farm);
                            Fertilizers.Add(fertilizerComponent);
                        }
                    }
                    else if (entity is ChickenCoop)
                    {
                        if (farm.Settings.Chickens.HasEntity(entity))
                        {
                            ChickenCoopComponent component = entity.gameObject.AddComponent<ChickenCoopComponent>();
                            component.Init(farm);
                            Chickens.Add(component);
                        }
                    }
                    else if (entity is Beehive)
                    {
                        if (farm.Settings.Beehives.HasEntity(entity))
                        {
                            BeehivesComponent component = entity.gameObject.AddComponent<BeehivesComponent>();
                            component.Init(farm);
                            Beehives.Add(component);
                        }
                    }
                    else if (entity is LiquidContainer)
                    {
                        if (farm.Settings.Waters.HasEntity(entity))
                        {
                            WaterContainersComponent component = entity.gameObject.AddComponent<WaterContainersComponent>();
                            component.Init(farm);
                            Waters.Add(component);
                        }
                    }
                    else if (entity is IItemContainerEntity container)
                    {
                        if (farm.Settings.Storage.HasEntity(entity))
                        {
                            StorageComponent storageComponent = entity.gameObject.AddComponent<StorageComponent>();
                            storageComponent.Init(farm);
                            Storages.Add(storageComponent);
                        }
                    }
                }
            }
            
            #endregion

            #region Coroutines
            private IEnumerator InitFarmObjectsCoroutine2()
            {
                yield return CoroutineEx.waitForSeconds(0.01f);

                farm.SendLog("InitFarm_FindFarmObjects");

                farmPoints.GetClear();
                // exitPoints.Clear();
                Storages.Clear();
                Planters.Clear();
                Fertilizers.Clear();
                Chickens.Clear();
                Beehives.Clear();
                Waters.Clear();
                DropItems.Clear();
                ResourceEntities.Clear();
                CollectibleEntities.Clear();

                LayerMask layerMask = LayerMask.GetMask("Deployed", "Prevent Building", "Water", "Harvestable", "Default", "Physics Debris");
                LayerMask layerBuild = LayerMask.GetMask("Construction");

                Vector3 pos = farm.ServerPosition;
                Vector2 size = farm.ZoneFarm.size / 2f;
                float radius = Mathf.Max(size.x, size.y);
                List<Vector3> open = Pool.Get<List<Vector3>>();
                List<Vector3> close = Pool.Get<List<Vector3>>();
                List<BaseEntity> searchBlocks = Pool.Get<List<BaseEntity>>();
                List<BaseEntity> searchEntities = Pool.Get<List<BaseEntity>>();
                Dictionary<ulong, BaseEntity> blocksFarm = Pool.Get<Dictionary<ulong, BaseEntity>>();
                Dictionary<ulong, BaseEntity> entitiesFarm = Pool.Get<Dictionary<ulong, BaseEntity>>();
                open.Add(pos);

#if DebugLog
                Debug.Log(RU ? $"Инициализация постройки" : $"Building initialization");
#endif

                while (open.Count > 0)
                {
                    yield return CoroutineEx.waitForSeconds(0.01f);

                    Vector3 currentPoint = open[0];
                    close.Add(currentPoint);
                    open.RemoveAt(0);

                    searchBlocks.Clear();
                    searchEntities.Clear();
                    Vis.Entities(currentPoint, 5f, searchBlocks, layerBuild);
                    yield return CoroutineEx.waitForSeconds(0.01f);
                    Vis.Entities(currentPoint, radius, searchEntities, layerMask);
                    yield return CoroutineEx.waitForSeconds(0.01f);

                    int count = searchBlocks.Count;
                    for (int i = 0; i < count; i++)
                    {
                        var block = searchBlocks[i];
                        if (block?.IsValid() == true)
                        {
                            Vector3 bPos = block.ServerPosition;
                            if (close.Contains(bPos)) continue;
                            if (!farm.IsZoneFarmEntity(block))
                            {
                                close.Add(bPos);
                                continue;
                            }
                            if (!blocksFarm.ContainsKey(block.net.ID.Value))
                            {
                                if (block is BuildingBlock or Door or SimpleBuildingBlock)
                                {
                                    blocksFarm.TryAdd(block.net.ID.Value, block);
                                    if (block is BuildingBlock) open.Add(bPos);
                                }
                                else close.Add(bPos);
                            }
                        }
                        
                    }

                    yield return CoroutineEx.waitForSeconds(0.01f);

                    count = searchEntities.Count;
                    int iterationCount = 0;
                    for (int i = 0; i < count; i++)
                    {
                        var entity = searchEntities[i];
                        if (entity?.IsValid() == true && !entitiesFarm.ContainsKey(entity.net.ID.Value))
                        {
                            entitiesFarm.TryAdd(entity.net.ID.Value, entity);
                        }
                        if (++iterationCount % 100 == 0)
                        {
                            yield return CoroutineEx.waitForSeconds(0.01f);
                        }
                    }
                }

#if DebugLog
                Debug.Log(RU ? $"Найдено блоков: {blocksFarm.Count}/ Найдено объектов: {entitiesFarm.Count}" : $"Found blocks: {blocksFarm.Count}/ Found objects: {entitiesFarm.Count}");
#endif
                Pool.FreeUnmanaged(ref searchBlocks);
                Pool.FreeUnmanaged(ref searchEntities);
                Pool.FreeUnmanaged(ref open);
                Pool.FreeUnmanaged(ref close);

                yield return CoroutineEx.waitForSeconds(0.01f);

#if DebugLog
                Debug.Log(RU ? $"Инициализация навигационной карты" : $"Navigation map initialization");
#endif
                foreach (var block in blocksFarm.Values)
                {
                    if (block?.IsValid() != true) continue;
                    Vector3 point = block.ServerPosition + H;
                    float step_4 = block.bounds.size.z / 4f;
                    float step_2 = block.bounds.size.z / 2f;
                    try
                    {
                        switch (block.ShortPrefabName)
                        {
                            case "foundation.triangle":
                            case "floor.triangle.frame":
                            case "floor.triangle":
                                {
                                    float sideLength = block.bounds.size.x;
                                    // Debug.LogTest($"size: {block.bounds.size}");
                                    float halfSide = sideLength / 2f;
                                    float height = Mathf.Sqrt(sideLength) / 2 * sideLength;
                                    // Локальные координаты углов
                                    Vector3[] corners = new Vector3[3]
                                    {
                                        new Vector3(-halfSide, 0, 0),      // Левый угол основания
                                        new Vector3(halfSide, 0, 0),       // Правый угол основания
                                        new Vector3(0, 0, block.bounds.size.z),     // вершина
                                    };
                                    Vector3 center = ((corners[0] + corners[1] + corners[2]) / 3) + H;
                                    Vector3[] direction = new Vector3[3]
                                    {
                                        (corners[0] - center).normalized,
                                        (corners[1] - center).normalized,
                                        (corners[2] - center).normalized
                                    };
