                    }

                    CoroutineEx.waitForSeconds(0.01f);
                }

#if DebugLog
                Debug.Log(RU ? $"Найдено навигационных точек: {farmPoints.Count}" : $"Found navigation points: {farmPoints.Count}");
#endif
                Pool.FreeUnmanaged(ref blocksFarm);

                foreach (var entity in entitiesFarm.Values)
                {
                    AddFarmEntity(entity);
                    yield return CoroutineEx.waitForSeconds(0.01f);
                }
                Pool.FreeUnmanaged(ref entitiesFarm);

                yield return FindRiverPoint();

                farm.SendLog("InitFarm_InitRoutePoints");

                int iteration = 0;
                foreach (var point in farmPoints.Values)
                {
                    if (!point.CanAddLinks) continue;
                    if (++iteration % 5 == 0) yield return CoroutineEx.waitForFixedUpdate;
                    
                    foreach (var neighbor in GetFarmNeighborsPoints(point.Position, 3.1f, true, 0.05f, LayerMask.GetMask("Construction", "Transparent"), true))//2.1f оптимальная дистанция
                    {
                        point.AddLink(neighbor);
                    }
                }

                yield return CoroutineEx.waitForSeconds(0.01f);

                List<Vector3> points = Pool.Get<List<Vector3>>();
                points.AddRange(farmPoints.Keys);
                int removesNodes = 0;
                foreach (var point in points)
                {
                    var node = farmPoints[point];
                    if (!node.InConnected)
                    {
                        removesNodes++;
                        farmPoints.Remove(point);
                        Pool.Free(ref node);
                    }
                }
                Pool.FreeUnmanaged(ref points);
#if DebugLog
                    Debug.Log(RU ? "Удалено не подключенных узлов фермы: " + removesNodes : "Removed unconnected nodes of farm: " + removesNodes);
#endif

                farm.SendLog("InitFarm_Complete", farmPoints.Count, Storages.Count, Planters.Count, Fertilizers.Count, Chickens.Count, Beehives.Count, Waters.Count, RiverPoint != Vector3.zero ? "Yes" : "No");
                farm.SendLog("InitFarm_Tools", farm.Settings.Controller.CanWatering ? farm.GetLangText(farm.Settings.Controller.WateringItem.GetItemDefinition().displayName) : "Error_NotWateringItem", farm.Settings.Controller.CanMining ? farm.GetLangText(farm.Settings.Controller.MiningItem.GetItemDefinition().displayName) : "CanNotMiningItem", farm.Settings.Controller.CanMedicine ? farm.GetLangText(farm.Settings.Controller.MedicineItem.GetItemDefinition().displayName) : "CanNotMedicineItem");
                IsInitMap = true;
                Invoke(() => SendMessage("OnInitNavigation"), 0.1f);
                yield break;
            }
            private IEnumerator FindRiverPoint()
            {
                yield return CoroutineEx.waitForSeconds(0.01f);
                farm.SendLog("InitFarm_FindWaterPoint");

                Vector3 point = Vector3.zero;
                var cup = farm.GetCup();
                float distance = cup.Distance(point);
                int layerMask = LayerMask.GetMask("Construction");
                int iterationCount = 0;
                foreach (var river in TerrainMeta.Path.Rivers.ToArray())
                {
                    foreach (var _point in river.Path.Points)
                    {
                        if (PersonalFarmerEx.PersonalFarmerEx.ContainsVector3(farm.ZoneFarm, _point) && cup.Distance(_point) < distance && !Physics.Raycast(point + Vector3.up * 200, Vector3.down, 200, layerMask))
                        {
                            point = _point;
                            distance = cup.Distance(point);
                        }
                    }
                    if (++iterationCount % 5 == 0)// Освобождение потока каждые 5 итераций
                    {
                        yield return CoroutineEx.waitForFixedUpdate;
                    }
                }
                if (point != Vector3.zero)
                {
                    RiverPoint = point;
                    yield return FindNeighborRiverPoint(RiverPoint, farm.ZoneFarm, 1f, layerMask);
                }
            }
            public IEnumerator FindNeighborRiverPoint(Vector3 startPosition, Rect restrictionArea, float stepSize, int layerMask)
            {
                Vector3 cup = farm.ServerPosition;
                Queue<Vector2> queue = new Queue<Vector2>();
                HashSet<Vector2> visited = new HashSet<Vector2>();
                HashSet<Vector2> closet = new HashSet<Vector2>();
                
                Vector2 point = new(startPosition.x, startPosition.z);
                float distance = Vector3.Distance(startPosition, cup);
                int iterationCount = 0;
                queue.Enqueue(point);
                visited.Add(point);
                Vector2[] directions =
                {
                    new Vector2(stepSize, 0),
                    new Vector2(-stepSize, 0),
                    new Vector2(0, stepSize),
                    new Vector2(0, -stepSize),
                    new Vector2(stepSize, stepSize),
                    new Vector2(stepSize, -stepSize),
                    new Vector2(-stepSize, stepSize),
                    new Vector2(-stepSize, -stepSize)
                };

                while (queue.Count > 0)
                {
                    point = queue.Dequeue();
                    RiverPoint = new(point.x, 0, point.y);
                    RiverPoint.y = TerrainMeta.HeightMap.GetHeight(RiverPoint);

                    // Проверяем условие глубины
                    if (!IsDepth(RiverPoint, true, true, 0.5f))
                    {
                        #if DebugLog
                            Debug.Log(RU ? $"Подходящая точка реки найдена: {RiverPoint} iterationCount={iterationCount}" : $"River point found: {RiverPoint} iterationCount={iterationCount}");
                        #endif
                        yield break;
                    }
                    else closet.Add(point);

                    foreach (var dir in directions)
                    {
                        Vector3 neighborXY = point + dir;
                        Vector3 neighbor = new(neighborXY.x, 0, neighborXY.y);
                        neighbor.y = TerrainMeta.HeightMap.GetHeight(neighbor);
                        if (closet.Contains(neighborXY)) continue;

                        if (restrictionArea.Contains(neighborXY) && !Physics.Linecast(RiverPoint, neighbor, layerMask) && !Physics.Raycast(neighbor + Vector3.up * 200, Vector3.down, 300, layerMask) && Vector3.Distance(neighbor, cup) is float dist && dist < distance)
                        {
                            if (!visited.Contains(neighborXY))
                            {
                                visited.Add(neighborXY);
                                queue.Enqueue(neighborXY);
                            }
                        }
                        else closet.Add(neighborXY);
                    }

                    if (++iterationCount % 5 == 0)// Освобождение потока каждые 5 итераций
                    {
                        yield return CoroutineEx.waitForFixedUpdate;
                    }
                }
                RiverPoint = Vector3.zero;
                #if DebugLog
                    Debug.Log(RU ? "Подходящая точка реки не найдена." : "River point not found.");
                #endif
            }
            public bool IsDepth(Vector3 position, bool waves = true, bool volumes = true, float depth = FarmerController.depth)
            {
                return WaterLevel.GetWaterDepth(position, waves, volumes) > depth;
            }
            public IEnumerator GetNeighborsPoints(Vector3 position, float distance, List<FarmPointNode> neighbors, bool canObstacle = true, bool canReversCheck = false)
            {
                yield return new WaitForEndOfFrame();
                neighbors.Clear();
                int layer = LayerMask.GetMask("Construction", "Transparent");
                foreach (var point in farmPoints.Keys)
                {
                    if (point == position) continue;
                    if (Mathf.Abs((point - position).magnitude) is float dist && dist <= distance && dist > 0.2f)
                    {
                        if (canObstacle)
                        {
                            if(!IsObstacleFarm(position, point, 0.1f, layer, false)) neighbors.Add(farmPoints[point]);
                            // // if (!(Physics.Raycast(new Ray(position, point - position), out var hitInfo, distance, LayerMask.GetMask("Construction")) && hitInfo.GetEntity() is BaseEntity entity && IsObstacle(entity)) || !(Physics.Raycast(new Ray(point, position - point), out hitInfo, distance, LayerMask.GetMask("Construction")) && hitInfo.GetEntity() is BaseEntity entity2 && IsObstacle(entity2)))
                            // if (!(Physics.SphereCast(new Ray(position, point - position), 0.1f, out var hitInfo, distance, layer) && hitInfo.GetEntity() is BaseEntity entity && IsObstacle(entity)) || !(Physics.SphereCast(new Ray(point, position - point), 0.1f, out hitInfo, distance, layer) && hitInfo.GetEntity() is BaseEntity entity2 && IsObstacle(entity2)))
                            // {
                            //     neighbors.Add(farmPoints[point]);
                            // }
                        }
                        else neighbors.Add(farmPoints[point]);
                    }
                }
                yield break;
            }
            private bool IsObstacleFarm(Vector3 start, Vector3 end, float radius, int layer, bool canReversCheck)
            {
                // bool isObstacle;
                Vector3 direction = end - start;
                float distance = direction.magnitude;
                if (Physics.SphereCast(new Ray(start, direction), radius, out var hitInfo, distance, layer) && hitInfo.GetEntity() is BaseEntity entity)
                {
                    if (IsObstacleEntity(entity)) return true;
                    // else isObstacle = false;
                }
                // else isObstacle = false;
                if (canReversCheck)
                {
                    direction = start - end;
                    if (Physics.SphereCast(new Ray(end, direction), radius, out hitInfo, distance, layer) && hitInfo.GetEntity() is BaseEntity entity2)
                    {
                        if (IsObstacleEntity(entity2)) return true;
                        // else isObstacle = false;
                    }
                    // else isObstacle = false;
                }
                return false;
            }
            private bool IsObstacleEntity(BaseEntity entity)
            {
                if (!entity || entity is Door) return false;
                switch (entity.ShortPrefabName)
                {
                    default: return true;
                }
            }
            public bool GetNearestFarmPoint(Vector3 position, out FarmPointNode neighbor, float maxDistance = 0f, bool canObstacle = true)
            {
                neighbor = null;
                int layer = LayerMask.GetMask("Construction", "Transparent");
                float d = maxDistance <= 0f ? float.MaxValue : maxDistance;
                foreach (var point in farmPoints.Keys)
                {
                    if (!farmPoints[point].HasLinks()) continue;
                    float distance = Vector3.Distance(point, position);
                    if (distance < d)
                    {
                        if (canObstacle)
                        {
                            if (!IsObstacleFarm(position + new Vector3(0, 0.4f, 0f), point + new Vector3(0, 0.4f, 0f), 0.1f, layer, false))
                            {
                                d = distance;
                                neighbor = farmPoints[point];
                            }
                        }
                        else
                        {
                            d = distance;
                            neighbor = farmPoints[point];
                        }
                    }
                }
                return neighbor != null;
            }
            public IEnumerable<FarmPointNode> GetGroundPoints(Vector3 position, List<FarmPointNode> sortedNodes)
            {
                sortedNodes.Clear();
                sortedNodes.AddRange(farmPoints.GetGroundNodes());
                sortedNodes.Sort((a, b) => Vector3.Distance(a.Position, position).CompareTo(Vector3.Distance(b.Position, position)));
                foreach (var p in sortedNodes)
                {
                    yield return p;
                }
            }
            public IEnumerable<FarmPointNode> GetFarmNeighborsPoints(Vector3 position, float distanceMax, bool canObstacle = true, float radiusCheck = 0.1f, int layer = -1, bool canReversCheck = true)
            {
                foreach (var p in farmPoints.Values)
                {
                    if (!p.CanAddLinks) continue;
                    if (Vector3.Distance(p.Position, position) > distanceMax) continue;
                    else
                    {
                        if (canObstacle)
                        {
                            if (!IsObstacleFarm(position + new Vector3(0, 0.4f, 0f), p.Position + new Vector3(0, 0.4f, 0f), radiusCheck, layer, canReversCheck)) yield return p;
                        }
                        else yield return p;
                    }
                }
            }
            public void CreateRouter()
            {
                generalFinderPath = new NavigationFarm.GeneralFinderPath(this, true, 10);
            }
            #endregion

            public class FarmNodes : Dictionary<Vector3, FarmPointNode>, Pool.IPooled
            {
                private List<FarmPointNode> groundNodes;
                public void EnterPool()
                {
                    Pool.FreeUnmanaged(ref groundNodes);
                    foreach (var node in Values)
                    {
                        if (node != null)
                        {
                            var _node = node;
                            Pool.Free(ref _node);
                        }
                    }
                    Clear();
                }
                public FarmPointNode AddFarmPointNode(BaseEntity block, Vector3 point, bool isHatch = false, Vector3? center = null, bool isExternal = false)
                {
                    if (ContainsKey(point)) throw new Exception(RU ? "Узел уже существует" : "Node already exists");
                    FarmPointNode node = Pool.Get<FarmPointNode>();
                    node.IsHatch = isHatch;
                    node.IsExternal = isExternal;
                    node.Init(block.net.ID.Value, point, center);
                    Add(point, node);
                    if (node.HasFlags(FarmPointNode.Flag.HasGround, FarmPointNode.Flag.IsExternal))
                    {
                        Vector3 pointGround = node.GetGroundPoint() + node.GetCenterDirection() * 1f;
                        pointGround.y = TerrainMeta.HeightMap.GetHeight(pointGround);
                        if(groundNodes.Exists(x => x.Position == pointGround)) return node;
                        FarmPointNode nodeGround = Pool.Get<FarmPointNode>().Init(0, pointGround, null);
                        nodeGround.IsGroundNode = true;
                        groundNodes.Add(nodeGround);
                        Add(pointGround, nodeGround);
                    }
                    return node;
                }
                public void LeavePool()
                {
                    groundNodes = Pool.Get<List<FarmPointNode>>();
                }

                public void GetClear()
                {
                    groundNodes.Clear();
                    foreach (var node in Values)
                    {
                        if (node != null)
                        {
                            var _node = node;
                            Pool.Free(ref _node);
                        }
                    }
                    Clear();
                }

                public IEnumerable<FarmPointNode> GetGroundNodes()
                {
                    return groundNodes;
                }

                internal IEnumerable<FarmPointNode> GetNodes(Sphere position)
                {
                    foreach (var node in Values)
                    {
                        bool value = position.Contains(node.Position);
                        if (value)
                        {
                            // Debug.LogTest($"GetNodes: [{node.Position}]");
                            yield return node;
                        }
                    }
                }
            }
            public class GeneralFinderPath : GeneralRouter
            {
                private BasePlayer drawPlayer => farm?.GetOwnerPlayer();
                protected NavigationFarm navigation;
                protected FarmManager farm => navigation?.farm;
                protected FarmerController farmer => farm?.Farmer;
                protected BuildingPrivlidge cup => farm.GetCup();
                protected LayerMask layerMaskDetectedHeight = LayerMask.GetMask("Terrain", "World");
                protected LayerMask layerMaskDetectedWalkableFarm = LayerMask.GetMask("Deployed");
                protected LayerMask layerMaskDetectedWalkableGround = LayerMask.GetMask("Construction", "Tree");
                protected override bool canYieldReturn { get; set; } = true;
                protected override int limitCyclesCreateRoute { get; set; } = 10;

                public GeneralFinderPath(NavigationFarm navigation, bool canYieldReturn, int limitCyclesCreateRoute)
                {
                    parent = navigation;
                    this.navigation = navigation;
                    this.canYieldReturn = canYieldReturn;
                    this.limitCyclesCreateRoute = limitCyclesCreateRoute;
                    currentLimitMap = farm.ZoneFarm;
                }

                private float offsetY => 0.4f;
                private float radius => 0.1f;
                protected float angle => 60f;

                public override void CalculateHightGround(ref Vector3 position)
                {
                    position.y = TerrainMeta.HeightMap.GetHeight(position);
                    if (Physics.Raycast(position + Vector3.up * 300, Vector3.down, out var hitInfo, 300, layerMaskDetectedHeight)) position.y = hitInfo.point.y;
                }

                public override bool IsWalkable(Vector3 current, Vector3 neighbor, bool canObstacle, bool isFarmRoute, bool canCheckZone)
                {
                    if (!farmer) return false;
                    if (isFarmRoute) return IsWalkableFarm(current, neighbor, canObstacle);
                    else return IsWalkableGround(current, neighbor, canObstacle, canCheckZone);
                }

                protected override bool IsWalkableFarm(Vector3 current, Vector3 neighbor, bool canObstacle)
                {
                    if (!base.IsWalkableFarm(current, neighbor, canObstacle)) return false;
                    if (canObstacle)
                    {
                        current.y += offsetY;
                        neighbor.y += offsetY;
                        if (Physics.SphereCast(new Ray(neighbor, neighbor - current), radius, out var hitInfo, Vector3.Distance(current, neighbor), layerMaskDetectedWalkableFarm) && hitInfo.GetEntity()?.ShortPrefabName != "wall.window") return false;
                    }
                    return true;
                }

                protected override bool IsWalkableGround(Vector3 current, Vector3 neighbor, bool canObstacle, bool canCheckZone)
                {
                    if (!base.IsWalkableGround(current, neighbor, canObstacle, canCheckZone)) return false;
                    current.y += offsetY;
                    neighbor.y += offsetY;
                    Vector3 direction = neighbor - current;
                    float _angle = VerticalAngleBetween(direction.normalized);
                    if (_angle > angle || _angle < -angle)
                    {
                        return false;
                    }
                    if (canObstacle)
                    {
                        if (Physics.SphereCast(new Ray(current, direction), radius, direction.magnitude, layerMaskDetectedWalkableGround)) return false;
                    }
                    return true;
                }
                private float VerticalAngleBetween(Vector3 v1)
                {
                    float vertical1 = v1.y;
                    Vector3 horizontal1 = new Vector3(v1.x, 0, v1.z);
                    float angle1 = Vector3.SignedAngle(v1, horizontal1, Vector3.up);

                    return angle1;
                }
                protected override Node CreateFarmNode(Vector3 neighbor, float g, float h, Vector3 parent)
                {
                    Node node = null;
                    if (navigation.farmPoints.TryGetValue(neighbor, out var farmPoint))
                    {
                        node = Pool.Get<Node>().InitFarmNode(farmPoint, g, h, parent);
                    }
                    return node;
                }
                protected override IEnumerable<FarmPointNode> GetGroundPoints(Vector3 position, List<FarmPointNode> sortedNodes) => navigation.GetGroundPoints(position, sortedNodes);
                protected override bool GetNearestFarmPoint(Vector3 position, out FarmPointNode nearestNode, float maxDistance, bool canObstacle) => navigation.GetNearestFarmPoint(position, out nearestNode, maxDistance, canObstacle);
                protected override bool IsBuildingPrivlidge(Vector3 position) => PersonalFarmer.IsBuildingPrivlidge(position, cup);
                protected override bool IsDepth(Vector3 position) => farmer?.IsDepth(position) == true;

                protected override void DrawNode(Node node, float time, float radius, Color color)
                {
                    if (drawPlayer is BasePlayer player) player?.SendConsoleCommand("ddraw.sphere", time, color, node.PositionNode, radius);
                }

                public override bool CheckStartPoint(Vector3 position, bool isFarmRoute)
                {
                    if (!farmer) return false;
                    if (isFarmRoute) return CheckStarFarmPoint(position);
                    else return CheckStarGroundPoint(position);
                }
                public override bool CheckEndPoint(Vector3 position, bool isFarmRoute)
                {
                    if (!farmer) return false;
                    if (isFarmRoute) return CheckEndFarmPoint(position);
                    else return CheckEndGroundPoint(position);
                }
                protected override bool CheckStarFarmPoint(Vector3 position) => true;
                protected override bool CheckStarGroundPoint(Vector3 position) => farmer && base.CheckStarGroundPoint(position);
                protected override bool CheckEndFarmPoint(Vector3 position) => true;
                protected override bool CheckEndGroundPoint(Vector3 position) => farmer && base.CheckEndGroundPoint(position);
            }
            public class FarmPointNode : Pool.IPooled
            {
                public ulong IdBlock { get; private set; }
                public Vector3 Position;
                private Links links;
                private Flag flags = Flag.None;
                private Vector3 groundPoint;
                private Vector3? direction;
                public bool CanAddLinks { get => HasFlag(Flag.CanAddLinks); set => SetFlag(Flag.CanAddLinks, value); }
                public bool IsHatch { get => HasFlag(Flag.IsHatch); set => SetFlag(Flag.IsHatch, value); }
                public bool IsGroundNode { get => HasFlag(Flag.IsGroundNode); set => SetFlag(Flag.IsGroundNode, value); }
                public bool IsConnected { get => HasFlag(Flag.IsConnected) || HasLinks(); set => SetFlag(Flag.IsConnected, value); }
                public bool InConnected { get => HasFlag(Flag.IsConnected); }
                public bool IsExternal { get => HasFlag(Flag.IsExternal); set => SetFlag(Flag.IsExternal, value); }

                public FarmPointNode()
                {
                }

                public FarmPointNode Init(ulong idBlock, Vector3 point, Vector3? center = null)
                {
                    IdBlock = idBlock;
                    Position = point;
                    SetFlag(Flag.CanAddLinks, true);
                    if (center != null)
                    {
                        direction = (point - (Vector3)center).normalized;
                        SetFlag(Flag.IsExternal, true);
                    }
                    if (Physics.Raycast(Position + new Vector3(0f, 0.4f, 0f), Vector3.down, out var hitInfo, 100, LayerMask.GetMask("Terrain", "World", "Construction")))
                    {
                        if (!hitInfo.GetEntity())
                        {
                            SetFlag(Flag.HasGround, true);
                            groundPoint = hitInfo.point;
                            if (IsHatch)
                            {
                                if (hitInfo.distance > 5f) SetFlag(Flag.IsHighly, true);
                                if (hitInfo.distance > 8f) SetFlag(Flag.IsVeryHighly, true);
                            }
                            else
                            {
                                if (hitInfo.distance > 2f) SetFlag(Flag.IsHighly, true);
                                if (hitInfo.distance > 5f) SetFlag(Flag.IsVeryHighly, true);
                            }
                        }
                        else
                        {
                            SetFlag(Flag.HasGround, false);
                            if (hitInfo.distance > 2f) SetFlag(Flag.IsHighly, true);
                            if (hitInfo.distance > 5f) SetFlag(Flag.IsVeryHighly, true);
                        }
                        float h = TerrainMeta.HeightMap.GetHeight(point);
                        if (h > Position.y) Position.y = h;
                    }

                    return this;
                }
                public Vector3 GetGroundPoint() => groundPoint;
                public bool IsExitPoint() => HasFlags(Flag.IsExitPoint, Flag.HasGround) && HasLinks();
                public bool HasLinks() => links.Has();
                public bool HasLink(Vector3 target) => links.ContainsLink(target);
                public void AddLink(FarmPointNode target)
                {
                    if(CanAddLink(target, out float distance)) links.TryAddLink(target, distance);
                }
                public void InsertLink(FarmPointNode target)
                {
                    links.TryAddLink(target, 0);
                }
                public void AddLinks(List<FarmPointNode> _neighbors)
                {
                    foreach (var item in _neighbors) AddLink(item);
                }
                public void InitGroundPoint() => Position = groundPoint;
                public void GetLinks(List<Vector3> neighbors)
                {
                    links.GetLinks(neighbors);
                }
                public Links GetLinks() => links;
                public bool CanAddLink(FarmPointNode target, out float distance)
                {
                    distance = 0;
                    if (target == null) return false;
                    if (links.ContainsLink(target.Position)) return false;
                    distance = Distance(target);

                    if (IsGroundNode && target.IsGroundNode) return true;
                    if (!target.HasFlag(Flag.CanAddLinks)) return false;
                    if(target.HasFlag(Flag.IsVeryHighly)) return false;

                    if (IdBlock == target.IdBlock)
                    {
                        if (HasFlag(Flag.IsHighly)) return false;
                        if (HasFlag(Flag.IsExternal))
                        {
                            if (target.HasFlag(Flag.IsExternal) && distance > 1) return false;
                            if (HasFlag(Flag.IsHighly)) return false;
                        }
                        if (distance > 1.5f) return false;
                        return true;
                    }

                    if (Position.y == target.Position.y)
                    {
                        if (HasFlag(Flag.IsHighly)) return false;
                        if (target.HasFlag(Flag.IsExternal))
                        {
                            if (HasFlag(Flag.IsExternal)) return false;
                        }
                        if (distance > 1.6f) return false;
                    }
                    else
                    {
                        if (Position.y > target.Position.y)
                        {
                            if (target.HasFlag(Flag.IsExternal))
                            {
                                if (!HasFlag(Flag.HasGround) && target.HasFlag(Flag.HasGround)) return false;
                            }
                            if (target.HasFlag(Flag.IsHighly)) return false;
                        }
                        if (!HasFlag(Flag.IsHighly) && target.HasFlag(Flag.IsHighly)) return false;
                    }
                    if (HasFlag(Flag.IsExternal) && target.HasFlag(Flag.IsExternal)) return false;

                    return true;
                }
                public Vector3 GetCenterDirection() => direction ?? Vector3.zero;
                public Vector3 Direction(FarmPointNode target) => Direction(target.Position);
                public Vector3 Direction(Vector3 target) => (target - Position).normalized;
                public float Distance(FarmPointNode target) => Distance(target.Position);
                public float Distance(Vector3 target) => Vector3.Distance(Position, target);

                public void EnterPool()
                {
                    IdBlock = 0;
                    flags = Flag.None;
                    Position = Vector3.zero;
                    Pool.Free(ref links);
                    groundPoint = Vector3.zero;
                    direction = null;
                }
                public void LeavePool()
                {
                    links = Pool.Get<Links>();
                }

                private void SetFlag(Flag flag, bool add)
                {
                    if (add)
                    {
                        if (HasFlag(flag)) return;
                        flags |= flag;
                    }
                    else
                    {
                        if (!HasFlag(flag)) return;
                        flags &= ~flag;
                    }
                }
                public bool HasFlag(Flag flag) => (flags & flag) == flag;
                public bool HasFlags(params Flag[] flags)
                {
                    foreach (var item in flags)
                    {
                        if (!HasFlag(item)) return false;
                    }
                    return true;
                }
                public enum Flag
                {
                    None = 0, IsExternal = 1, IsHighly = 2, IsVeryHighly = 4, IsHatch = 8, HasGround = 16, IsExitPoint = 32, CanAddLinks = 64, IsGroundNode = 128, IsConnected = 256
                }
                public struct Link
                {
                    public float Distance;
                    public FarmPointNode Node;
                }
                public class Links : List<Link>, Pool.IPooled
                {
                    public void EnterPool()
                    {
                        Clear();
                    }
                    public void LeavePool()
                    {
                    }

                    public bool TryAddLink(FarmPointNode target, float distance)
                    {
                        if (target == null) return false;
                        if (ContainsLink(target.Position)) return false;
                        Add(new Link() { Distance = distance, Node = target });
                        target.IsConnected = true;
                        return true;
                    }

                    public bool ContainsLink(FarmPointNode target)
                    {
                        if (target == null) return false;
                        else
                        {
                            foreach (var item in this)
                            {
                                if (item.Node == target) return true;
                            }
                            return false;
                        }
                    }

                    public bool ContainsLink(Vector3 target)
                    {
                        foreach (var item in this)
                        {
                            if (item.Node.Position == target) return true;
                        }
                        return false;
                    }

                    public bool Has() => Count > 0;

                    public void GetLinks(List<Vector3> neighbors)
                    {
                        foreach (var item in this)
                        {
                            neighbors.Add(item.Node.Position);
                        }
                    }
                }

            }

            internal bool TryGetFarmNode(Vector3 position, out FarmPointNode node)
            {
                farmPoints.TryGetValue(position, out node);
                return node != null;
            }
        }
        public class BrainFarmer : FacepunchBehaviour
        {
            protected const float timeWait = 0.3f;
            private const float timerJob = 180f;
            private FrankensteinPet owner;
            private FarmManager farm;
            private FarmerController farmer => farm?.Farmer;
            private bool isInitFarmer => farm?.Farmer?.IsInit == true;
            private StatusFarmer status = StatusFarmer.Idle;
            private float tickUpdate => farm?.Settings?.Controller?.TickUpdateBrain ?? -1f;
            private TimeSince timerCurrentStatus = 0;
            private TimeSince timerIdle = 0;
            private List<IFarmerJob> queueJob;
            private IFarmerJob currentJob;
            public bool HasJob => queueJob?.Count > 0;
            private bool isForceSleepMode => farm?.Data.UISetup.Farmer.ForceSleepMode == true;

            #region UnityCallbacks
            private void Awake()
            {
                owner = gameObject.GetComponent<FrankensteinPet>();
                queueJob = Pool.Get<List<IFarmerJob>>();
            }
            private void Update()
            {
                if (tickUpdate == 0) TickBrain();
            }
            private void OnDestroy()
            {
                UnSubscribeStatusVisible();
                Pool.FreeUnmanaged(ref queueJob);
            }
            #endregion

            #region Methods
            public void ResetTimerStatus() => timerCurrentStatus = 0;
            public void Init(FarmManager _farm)
            {
                farm = _farm;
                if (farm.Data.UISetup.Farmer.CanVisibleFarmerState) SubscribeStatusVisible();
                if (tickUpdate > 0f) InvokeRepeating(TickBrain, tickUpdate, tickUpdate);
                farmer.StartCoroutine(SearchJob_ZoneFarm());
                farmer.StartCoroutine(SearchJob_Planted());
                farmer.StartCoroutine(SearchJob_Chickens());
                farmer.StartCoroutine(SearchJob_OtherFarmWork());
            }
            public void SubscribeStatusVisible() => farm?.SubscribeStatusFarmer(DrawInfo);
            public void UnSubscribeStatusVisible() => farm?.UnSubscribeStatusFarmer(DrawInfo);
            private void TickBrain()
            {
                if (farm?.IsInitFarm == true && isInitFarmer)
                {
                    if (!farm.IsSorted)
                    {
                        if (farm.Data.UISetup.Farmer.ForceSleepMode)
                        {
                            if (status != StatusFarmer.Sleeping) SetStatus(StatusFarmer.Sleeping);
                            return;
                        }
                        if (status == StatusFarmer.Idle)
                        {
                            if (timerIdle > 60f)
                            {
                                SetStatus(StatusFarmer.Sleeping);
                            }
                            else
                            {
                                SearchWork();
                            }
                        }
                        else
                        {
                            if (status == StatusFarmer.Sleeping)
                            {
                                SearchWork();
                            }
                            else
                            {
                                CheckCurrentJob();
                            }
                        }
                    }
                    else
                    {
                        if (status != StatusFarmer.Sorted)
                        {
                            SetStatus(StatusFarmer.Sorted);
                        }
                        else CheckCurrentJob();
                    }
                }
                else if(farm.IsNewInitializationRequired && status != StatusFarmer.NotInitialization) status = StatusFarmer.NotInitialization;
            }
            private void SearchWork()
            {
                if (farm.Data.UISetup.Farmer.ForceSleepMode) return;
                if (!farm.GetCup().IsAuthed(farmer.GetNpc()) && status != StatusFarmer.Authorization)
                {
                    SetStatus(StatusFarmer.Authorization);
                    return;
                }
                if (farm.DeadDrop?.IsValid() == true && status != StatusFarmer.PickupDropDeath)
                {
                    SetStatus(StatusFarmer.PickupDropDeath);
                    return;
                }
                if (HasJob)
                {
                    SetStatus(StatusFarmer.Job);
                }
            }
            private void CheckCurrentJob()
            {
                if (farm.Data.UISetup.Farmer.ForceSleepMode) return;
                if (status == StatusFarmer.Job || status == StatusFarmer.ClearInventory || status == StatusFarmer.Eat || status == StatusFarmer.Drink || status == StatusFarmer.Medication)
                {
                    if (currentJob?.IsValid() == true && timerCurrentStatus <= timerJob)
                    {
                        if (currentJob.IsCompleted)
                        {
                            bool canClear = !(currentJob is JobClearInventory);
                            StopCurrentJob();
                            if (canClear && MoveItemBeltToMain() && !farmer.Inventory.containerMain.IsEmpty()) InsertJob<JobClearInventory>();
                            SetStatus(StatusFarmer.Idle);
                            return;
                        }
                        else
                        {
                            currentJob.Update();
                        }
                    }
                    else
                    {
                        if (timerCurrentStatus > timerJob) Debug.LogWarning($"TimerCurrentStatus[{timerCurrentStatus}] > timerJob[{timerJob}]");
                        StopCurrentJob();
                        SetStatus(StatusFarmer.Idle);
                    }
                }
                if(status == StatusFarmer.Sorted && !farm.IsSorted) SetStatus(StatusFarmer.Idle);
            }
            private void DrawInfo(BasePlayer player)
            {
                player?.SendConsoleCommand("ddraw.text", farm.UpdateStatus, Color.yellow, owner.ServerPosition + owner.transform.up * 2f, GetStatus(player.UserIDString));
            }
            public string GetStatus(string userID)
            {
                string text = owner.displayName;
                text += "\n" + instance?.GetLangText(userID, "FarmerCondition_Health", owner.Health().ToString("0"), owner.MaxHealth().ToString("0"), farmer.PercentHealth.ToString("0%"));
                text += "    " + instance?.GetLangText(userID, "FarmerCondition_Calories", farmer.PercentCalories.ToString("0%"), farmer.PercentHydration.ToString("0%"));
                text += "\n" + "Status: " + GetStatusString(userID);
                #if DrawTest
                    text += "\n" + $"Test: Velocity[{owner?.NavAgent.velocity}]";
                    text += "\n" + $"Test: current Job[{currentJob?.Get?.GetType().Name}]\nqueueJob[{queueJob.Count}]";
                #endif
                return text;
            }
            private string GetStatusString(string userID)
            {
                string text = instance?.GetLangText(userID, status.ToString(), $"{(float)timerCurrentStatus:0}") ?? "";
                if (status == StatusFarmer.Job && currentJob != null) text += "\n" + currentJob.GetStatus();
                return text;
            }
            private void StopCurrentJob()
            {
                if (currentJob != null)
                {
                    currentJob.Stop();
                    BaseJob.SetPool(currentJob.Get);
                    currentJob = null;
                }
            }
            public void SetStatus(StatusFarmer _status)
            {
                if (!farmer) return;
                timerCurrentStatus = 0;
                StopCurrentJob();
                if (!farmer.Pause) farmer.Pause = true;
                switch (_status)
                {
                    case StatusFarmer.Idle:
                        {
                            timerIdle = 0;
                            status = StatusFarmer.Idle;
                            farm.MoveTo(farm.Bag.ServerPosition, (x) => { });
                            break;
                        }
                    case StatusFarmer.Initialization:
                        {
                            status = StatusFarmer.Initialization;
                            farm.Navigation.Initialization();
                            farm.SendLog("LogFarmer_InitializationFarm");
                            break;
                        }
                    case StatusFarmer.PickupDropDeath:
                        {
                            status = StatusFarmer.PickupDropDeath;
                            farm.SendLog("LogFarmer_PickupDropDeathMove");
                            farm.MoveTo(farm.DeadDrop.transform.position, OnFinishPickupDropDeath);
                            break;
                        }
                    case StatusFarmer.Sleeping:
                        {
                            status = StatusFarmer.Sleeping;
                            farm.SendLog("LogFarmer_SleepingMove");
                            farm.MoveTo(farm.Bag.ServerPosition, OnFinishSleeping);
                            break;
                        }
                    case StatusFarmer.Authorization:
                        {
                            status = StatusFarmer.Authorization;
                            farm.SendLog("LogFarmer_AuthorizationMove");
                            farm.MoveTo(farm.ServerPosition, OnFinishToAuthorization);
                            break;
                        }
                    case StatusFarmer.Eat:
                        {
                            status = StatusFarmer.Eat;
                            AddCurrentJob<JobMetabolism>(status);
                            break;
                        }
                    case StatusFarmer.Drink:
                        {
                            status = StatusFarmer.Drink;
                            AddCurrentJob<JobMetabolism>(status);
                            break;
                        }
                    case StatusFarmer.Medication:
                        {
                            status = StatusFarmer.Medication;
                            AddCurrentJob<JobMetabolism>(status);
                            break;
                        }
                    case StatusFarmer.Job:
                        {
                            if (MoveItemBeltToMain() && !farmer.Inventory.containerMain.IsFull())
                            {
                                status = StatusFarmer.Job;
                                currentJob = queueJob[0];
                                queueJob.RemoveAt(0);
                                currentJob.Start();
                            }
                            else
                            {
                                goto case StatusFarmer.ClearInventory;
                            }
                            break;
                        }
                    case StatusFarmer.ClearInventory:
                        {
                            status = StatusFarmer.ClearInventory;
                            AddCurrentJob<JobClearInventory>();
                            break;
                        }
                    case StatusFarmer.Sorted:
                        {
                            status = StatusFarmer.Sorted;

                            AddCurrentJob<JobSortedStorages>();
                            break;
                        }
                }
            }
            public ItemDefinition FindSeedToPlanter(PlanterComponent planter)
            {
                return planter.IsEnabledUsedClone ? null : planter.GetSeedDef();
            }
            public bool ContainsClone(ItemContainer container)
            {
                if (container == null) return false;
                foreach (Item item in container.itemList)
                {
                    if (item != null && item.info.shortname == "clone") return true;
                }
                return false;
            }
            public void AddJob<T>(params object[] args) where T : BaseJob, IFarmerJob, new()
            {
                var job = BaseJob.GetPool<T>(farm, args);
                queueJob.Add(job);
            }
            public void InsertJob<T>(params object[] args) where T : BaseJob, IFarmerJob, new()
            {
                var job = BaseJob.GetPool<T>(farm, args);
                queueJob.Insert(0, job);
            }
            private void AddCurrentJob<T>(params object[] args) where T : BaseJob, IFarmerJob, new()
            {
                StopCurrentJob();
                var job = BaseJob.GetPool<T>(farm, args);
                currentJob = job;
                currentJob.Start();
            }
            public bool MoveItemBeltToMain()
            {
                Item item = farmer.Inventory.containerBelt.GetSlot(0);
                if (item != null)
                {
                    bool result = item.MoveToContainer(farmer.Inventory.containerMain);
                    ActivatedBeltItem();
                    return result;
                }
                return true;
            }
            public void ActivatedBeltItem()
            {
                var npc = farmer?.GetNpc();
                if(npc == null) return;
                Item slot = farmer.Inventory.containerBelt.GetSlot(0);
                ItemId itemID = slot == null ? default : slot.uid;
                if (npc.svActiveItemID == itemID) return;

                Item activeItem = npc.GetActiveItem();
                npc.svActiveItemID = default;
                if (activeItem != null)
                {
                    HeldEntity heldEntity = activeItem.GetHeldEntity() as HeldEntity;
                    if (heldEntity != null)
                    {
                        heldEntity.SetHeld(bHeld: false);
                    }
                }

                npc.svActiveItemID = itemID;
                npc.SendNetworkUpdate();
                Item activeItem2 = npc.GetActiveItem();
                if (activeItem2 != null)
                {
                    HeldEntity heldEntity2 = activeItem2.GetHeldEntity() as HeldEntity;
                    if (heldEntity2 != null)
                    {
                        heldEntity2.SetHeld(bHeld: true);
                    }

                    if (npc.InGesture)
                    {
                        npc.Server_CancelGesture();
                    }
                }

                npc.inventory.UpdatedVisibleHolsteredItems();
            }
            public void AttackMelee(HeldEntity held, BaseEntity target)
            {
                if (held is BaseMelee melee && !melee.HasAttackCooldown() && target?.IsValid() == true)
                {
                    melee.StartAttackCooldown(melee.repeatDelay * 2f);
                    NPCPlayer bot = farmer.GetNpc();
                    bot.SignalBroadcast(BaseEntity.Signal.Attack, string.Empty);
                    float num = 0.0f;
                    foreach (Rust.DamageTypeEntry damageType in melee.damageTypes) num += damageType.amount;
                    HitInfo hitInfo = Pool.Get<HitInfo>();
                    hitInfo.Init(bot, target, Rust.DamageType.Slash, num * melee.npcDamageScale, bot.ServerPosition);
                    hitInfo.Weapon = melee;
                    hitInfo.CanGather = true;
                    hitInfo.HitMaterial = StringPool.Get(target.gameObject.GetComponent<Collider>() is Collider collider && collider.sharedMaterial != null ? collider.sharedMaterial.GetName() : "generic");
                    Effect.server.ImpactEffect(hitInfo);
                    target.OnAttacked(hitInfo);
                }
            }
            #endregion

            #region CallbacksFinishPath
            private void OnFinishToAuthorization(bool finish)
            {
                if (!finish) farm.SendLog("Message_NotFoundRouteToCup");
                else
                {
                    var cup = farm.GetCup();
                    if (!cup.IsAuthed(farmer.GetNpc()))
                    {
                        cup.authorizedPlayers.Add(new ProtoBuf.PlayerNameID
                        {
                            ShouldPool = false,
                            userid = farmer.GetNpc().userID,
                            username = farmer.GetNpc().displayName
                        });
                    }
                    SetStatus(StatusFarmer.Idle);
                }
            }
            private void OnFinishPickupDropDeath(bool finish)
            {
                if (!finish)
                {
                    farm.SendLog("Message_NotFoundRouteToDeath");
                    SetStatus(StatusFarmer.Idle);
                }
                else
                {
                    if (farm.DeadDrop?.IsValid() == true)
                    {
                        var npc = farmer.GetNpc();
                        foreach (var item in farm.DeadDrop.inventory.itemList.ToArray())
                        {
                            if (item != null)
                            {
                                if (item.info.category == ItemCategory.Attire)
                                {
                                    if (item.MoveToContainer(npc.inventory.containerWear)) continue;
                                }
                                else if (item.info.category == ItemCategory.Tool)
                                {
                                    if (item.MoveToContainer(npc.inventory.containerBelt)) continue;
                                }
                                if (!item.MoveToContainer(npc.inventory.containerMain)) item.Drop(npc.GetDropPosition(), npc.GetDropVelocity());
                            }
                        }
                        if (farm.DeadDrop.inventory.IsEmpty()) farm.DeadDrop.Kill();
                    }
                    
                    SetStatus(StatusFarmer.Idle);
                }
            }
            private void OnFinishSleeping(bool finish)
            {
                if (!finish)
                {
                    farm.SendLog("Message_NotFoundRouteToBag");
                    SetStatus(StatusFarmer.Idle);
                }
                else
                {
                    farmer.Sleeping(true);
                }
            }
            #endregion

            #region Coroutines
            private IEnumerator SearchJob_ZoneFarm()
            {
                while (true)
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (farm.IsInitFarm)
                    {
                        if (!isForceSleepMode && status != StatusFarmer.Sorted && farm.Settings.Controller.CanPickupDroppedItems && farm.Data.UISetup.Farmer.CanPickupDroppedItems && farm.Navigation.DropItems.Count > 0 && !(currentJob is JobPickupDroppedItem) && !queueJob.Exists(x => x is JobPickupDroppedItem))
                        {
                            AddJob<JobPickupDroppedItem>();
                        }
                        yield return CoroutineEx.waitForSeconds(timeWait);

                        if (!isForceSleepMode && status != StatusFarmer.Sorted && farm.Settings.Controller.CanPickupCollectibleItems && farm.Data.UISetup.Farmer.CanPickupCollectibleItems && farm.Navigation.CollectibleEntities.Count > 0 && !(currentJob is JobPickupCollectedEntity) && !queueJob.Exists(x => x is JobPickupCollectedEntity))
                        {
                            AddJob<JobPickupCollectedEntity>();
                        }
                        yield return CoroutineEx.waitForSeconds(timeWait);

                        if (!isForceSleepMode && status != StatusFarmer.Sorted && farm.Settings.Controller.CanMining && farm.Data.UISetup.Farmer.CanMining && farm.Navigation.ResourceEntities.Count > 0 && !(currentJob is JobMiningResources) && !queueJob.Exists(x => x is JobMiningResources))
                        {
                            AddJob<JobMiningResources>();
                        }
                        yield return CoroutineEx.waitForSeconds(timeWait);
                    }
                }
            }
            private IEnumerator SearchJob_Planted()
            {
                while (true)
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (farm.IsInitFarm)
                    {
                        if (!isForceSleepMode && status != StatusFarmer.Sorted && farm?.Navigation?.Planters?.Count > 0 && farm.Data.UISetup.Planters.EnableProductions)
                        {
                            foreach (var planter in FarmManager.GetFarmAccessEntity<PlanterComponent>(farm.Navigation.Planters.ToArray()))
                            {
                                if (!isForceSleepMode && status != StatusFarmer.Sorted && planter != null && farm.Data.UISetup.Planters.CanPlantSeeds && !planter.IsFullPlanted && !(currentJob is JobPlant) && !queueJob.Exists(x => x is JobPlant)) yield return CheckPlanter(planter);
                                yield return CoroutineEx.waitForSeconds(timeWait);

                                if (!isForceSleepMode && status != StatusFarmer.Sorted && planter != null && planter.CanWatering() && !(currentJob is JobWatering) && !queueJob.Exists(x => x is JobWatering)) yield return CheckPlanterToWatering(planter);
                                yield return CoroutineEx.waitForSeconds(timeWait);

                                if (!isForceSleepMode && status != StatusFarmer.Sorted && planter != null && planter.CanHarvesting() && !(currentJob is JobHarvesting) && !queueJob.Exists(x => x is JobHarvesting)) yield return CheckPlanterToHarvesting(planter);
                                yield return CoroutineEx.waitForSeconds(timeWait);

                                if (!isForceSleepMode && status != StatusFarmer.Sorted && planter != null && farm.Data.UISetup.Planters.CanFertilizers && planter.CanAddFertilizers() && !(currentJob is JobFertilizerToPlanted) && !queueJob.Exists(x => x is JobFertilizerToPlanted)) yield return CheckPlanterFertilizers(planter);
                                yield return CoroutineEx.waitForSeconds(timeWait);

                                if (!isForceSleepMode && status != StatusFarmer.Sorted && planter != null && farm.Data.UISetup.Planters.CanClones && planter.HasTakeClones() && !(currentJob is JobTakeClonesToPlanted) && !queueJob.Exists(x => x is JobTakeClonesToPlanted)) yield return CheckPlanterTakeClones(planter);
                                yield return CoroutineEx.waitForSeconds(timeWait);
                            }
                        }
                        yield return CoroutineEx.waitForSeconds(timeWait);
                    }
                }
            }
            private IEnumerator SearchJob_Chickens()
            {
                while (true)
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (farm.IsInitFarm)
                    {
                        if (!isForceSleepMode && status != StatusFarmer.Sorted && farm?.Navigation?.Chickens?.Count > 0 && farm.Data.UISetup.Chickens.EnableProductions)
                        {
                            foreach (var chicken in FarmManager.GetFarmAccessEntity<ChickenCoopComponent>(farm.Navigation.Chickens.ToArray()))
                            {
                                if (!isForceSleepMode && status != StatusFarmer.Sorted && chicken != null && chicken.IsChickenLove(80f) && !(currentJob is JobChickenLove) && !queueJob.Exists(x => x is JobChickenLove)) yield return CheckChickenLove(chicken);
                                yield return CoroutineEx.waitForSeconds(timeWait);
                                if (!isForceSleepMode && status != StatusFarmer.Sorted && chicken != null && chicken.CanWatering() && !(currentJob is JobChickenWater) && !queueJob.Exists(x => x is JobChickenWater)) yield return CheckChickenWater(chicken);
                                yield return CoroutineEx.waitForSeconds(timeWait);
                                if (!isForceSleepMode && status != StatusFarmer.Sorted && chicken != null && chicken.CanFood() && !(currentJob is JobChickenFood) && !queueJob.Exists(x => x is JobChickenFood)) yield return CheckFoodChicken(chicken);
                                yield return CoroutineEx.waitForSeconds(timeWait);
                                if (!isForceSleepMode && status != StatusFarmer.Sorted && chicken != null && chicken.HasEgg && !(currentJob is JobPickEgg) && !queueJob.Exists(x => x is JobPickEgg)) yield return CheckPickEgg(chicken);
                                yield return CoroutineEx.waitForSeconds(timeWait);
                                if (!isForceSleepMode && status != StatusFarmer.Sorted && farm.Data.UISetup.Chickens.EnableRaiseChickens && chicken != null && chicken.CanHatching && !(currentJob is JobEggHatching) && !queueJob.Exists(x => x is JobEggHatching)) yield return CheckEggHatching(chicken);
                                yield return CoroutineEx.waitForSeconds(timeWait);
                            }
                        }
                        yield return CoroutineEx.waitForSeconds(timeWait);
                    }
                }
            }
            private IEnumerator SearchJob_OtherFarmWork()
            {
                while (true)
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (farm.IsInitFarm)
                    {
                        if (!isForceSleepMode
                            && status != StatusFarmer.Sorted
                            && status != StatusFarmer.Authorization
                            && farm?.Navigation?.Fertilizers?.Count > 0
                            && farm.Data.UISetup.Fertilizers.EnableProductions)
                        {
                            foreach (var fertilizer in FarmManager.GetFarmAccessEntity<FertilizerComponent>(farm.Navigation.Fertilizers.ToArray()))
                            {
                                if (!isForceSleepMode && status != StatusFarmer.Sorted && fertilizer != null && !(currentJob is JobComposter) && !queueJob.Exists(x => x is JobComposter)) yield return CheckComposter(fertilizer);
                                yield return CoroutineEx.waitForSeconds(timeWait);
                            }
                        }
                        yield return CoroutineEx.waitForSeconds(timeWait);

                        if (!isForceSleepMode
                            && status != StatusFarmer.Sorted
                            && status != StatusFarmer.Authorization
                            && farm?.Navigation?.Beehives?.Count > 0
                            && farm.Data.UISetup.Beehives.EnableProductions)
                        {
                            foreach (var beeHives in FarmManager.GetFarmAccessEntity<BeehivesComponent>(farm.Navigation.Beehives.ToArray()))
                            {
                                if (!isForceSleepMode && status != StatusFarmer.Sorted && farm.Data.UISetup.Beehives.EnableAddNucleus && beeHives != null && !(currentJob is JobBeehiveNucleus) && !queueJob.Exists(x => x is JobBeehiveNucleus)) yield return CheckBeehiveNucleus(beeHives);
                                yield return CoroutineEx.waitForSeconds(timeWait);
                                if (!isForceSleepMode && status != StatusFarmer.Sorted && beeHives != null && !(currentJob is JobHoneyComb) && !queueJob.Exists(x => x is JobHoneyComb)) yield return CheckHoneyComb(beeHives);
                                yield return CoroutineEx.waitForSeconds(timeWait);
                            }
                        }
                        yield return CoroutineEx.waitForSeconds(timeWait);
                        if (!isForceSleepMode
                            && status != StatusFarmer.Sorted
                            && status != StatusFarmer.PickupDropDeath
                            && status != StatusFarmer.ClearInventory
                            && status != StatusFarmer.Authorization
                            && farmer.GetNpc() is NPCPlayer npc
                            && !(currentJob is JobMetabolism)
                            && !queueJob.Exists(x => x is JobMetabolism))
                        {
                            yield return CheckMetabolism(npc);
                        }
                    }
                }
            }
            private IEnumerator CheckPlanter(PlanterComponent planter)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);

                ItemDefinition seedDef = FindSeedToPlanter(planter);
                if (seedDef != null) AddJob<JobPlant>(planter, seedDef);

                yield return CoroutineEx.waitForSeconds(timeWait);
            }
            private IEnumerator CheckFoodChicken(ChickenCoopComponent chickenCoop)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);
                if (farmer.Inventory.HasItemsToFoodChickens(farm) || farm.Navigation.Storages.Exists(x => x?.IsValid == true && x.CanAccessFarmer && x.HasItemsToFoodChickens()))
                {
                    AddJob<JobChickenFood>(chickenCoop);
                }
                else farm.SendLog("LogFarmer_NotFoundChickenFood");

                yield return CoroutineEx.waitForSeconds(timeWait);
            }
            private IEnumerator CheckPlanterToWatering(PlanterComponent planter)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);

                if (!farm.Settings.Controller.CanWatering)
                {
                    Debug.LogError(RU ? "Не настроен предмет для полива" : "Watering item not configured");
                    yield break;
                }

                if (farm.Navigation.RiverPoint != Vector3.zero)
                {
                    AddJob<JobWatering>(planter);
                }
                else
                {
                    foreach (var water in FarmManager.GetFarmAccessEntity<WaterContainersComponent>(farm.Navigation.Waters.ToArray()))
                    {
                        if (water.Inventory.HasAny(WaterTypes.WaterItemDef))
                        {
                            AddJob<JobWatering>(planter);
                            yield break;
                        }
                    }
                }
                
            }
            private IEnumerator CheckPlanterToHarvesting(PlanterComponent planter)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);
                AddJob<JobHarvesting>(planter);
            }
            private IEnumerator CheckPlanterFertilizers(PlanterComponent planter)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);
                if(farm.Navigation.Storages.Exists(x => x.Inventory.itemList.Exists(y => y.info.itemid == idFertilizer))) AddJob<JobFertilizerToPlanted>(planter);
            }
            private IEnumerator CheckPlanterTakeClones(PlanterComponent planter)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);
                if(planter.HasTakeClones()) AddJob<JobTakeClonesToPlanted>(planter);
            }
            private IEnumerator CheckChickenLove(ChickenCoopComponent chicken)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);
                AddJob<JobChickenLove>(chicken);
            }
            private IEnumerator CheckChickenWater(ChickenCoopComponent chicken)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);
                AddJob<JobChickenWater>(chicken);
            }
            private IEnumerator CheckPickEgg(ChickenCoopComponent chicken)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);
                AddJob<JobPickEgg>(chicken);
            }
            private IEnumerator CheckEggHatching(ChickenCoopComponent chicken)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);
                if(farm.Navigation.Storages.Exists(x => x.Inventory.HasItem(chicken.GetItemDefEgg()))) AddJob<JobEggHatching>(chicken);
            }
            private IEnumerator CheckComposter(FertilizerComponent fertilizer)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);

                if (fertilizer?.IsValid == true)
                {
                    if (!fertilizer.IsFull() && (fertilizer.HasFertilizer() || farm.Navigation.Storages.Exists(x => x?.IsValid == true && x.CanAccessFarmer && x.HasItemsComposter(fertilizer))))
                    {
                        AddJob<JobComposter>(fertilizer);
                    }
                }
            }
            private IEnumerator CheckBeehiveNucleus(BeehivesComponent beehives)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);

                if (beehives?.IsValid == true)
                {
                    if (!beehives.HasNucleus && farm.Navigation.Storages.Exists(x => x?.IsValid == true && x.CanAccessFarmer && x.Inventory.HasAny(beehives.NucleusDef)))
                    {
                        AddJob<JobBeehiveNucleus>(beehives);
                    }
                    else if (!beehives.HasNucleus) farm.SendLog("LogFarmer_NotFoundNucleus");
                }
            }
            private IEnumerator CheckHoneyComb(BeehivesComponent beehives)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);

                if (beehives?.IsValid == true)
                {
                    if (beehives.HasHoneyComb)
                    {
                        AddJob<JobHoneyComb>(beehives);
                    }
                }
            }
            private IEnumerator CheckMetabolism(NPCPlayer npc)
            {
                yield return CoroutineEx.waitForSeconds(timeWait);
                if (farmer)
                {
                    if (farmer.CanDrink())
                    {
                        SetStatus(StatusFarmer.Drink);
                    }
                    else if (farmer.CanEat())
                    {
                        if(farm.Navigation.Storages.Exists(x => x.CanAccessFarmer && x.HasFoodFarmer())) SetStatus(StatusFarmer.Eat);
                    }
                    else if (farmer.CanMedication())
                    {
                        if(farm.Settings.Controller.MedicineItem.CanCreate || farm.Navigation.Storages.Exists(x => x.CanAccessFarmer && x.HasMedicationFarmer())) SetStatus(StatusFarmer.Medication);
                    }
                }
            }
            #endregion

            #region JobClasses
            public interface IFarmerJob
            {
                BaseJob Get { get; }
                FarmManager Farm { get; }
                bool IsCompleted { get; }
                void Start();
                void Update();
                void Stop();
                bool IsValid();
                string GetStatus();
                void NextStage();
            }
            /// <summary>
            /// Поиск и высаживание семян на плантацию.
            /// </summary>
            public class JobPlant : BaseJob, IFarmerJob
            {
                PlanterComponent planter;
                ItemDefinition seed;
                int amountSeed = 0;

                #region MethodsPool
                public override void EnterPool()
                {
                    base.EnterPool();
                    planter = null;
                    seed = null;
                }

                #endregion

                #region Methods
                public override void Init(FarmManager _farm, params object[] args)
                {
                    base.Init(_farm, args);
                    planter = args[0] as PlanterComponent;
                    seed = args[1] as ItemDefinition;
                    planter.IsBusy = true;
                }
                public override void NextStage()
                {
                    base.NextStage();
                    switch (stage)
                    {
                        case 1:
                            {
                                status = "JobStatus_FindSeed";
                                argsStatus = new object[0];
                                StartCoroutineJob(FindSeeds());
                                break;
                            }
                        case 2:
                            {
                                status = "JobStatus_PlantedSeeds";
                                argsStatus = new object[0];
                                StartCoroutineJob(PlantedSeeds());
                                break;
                            }
                        default:
                            {
                                IsCompleted = true;
                                break;
                            }
                    }
                }

                #endregion

                #region MethodsInterface
                public override void Start()
                {
                    base.Start();
                    Farm.SendLog("LogFarmer_Planted", seed.displayName.english);
                }

                public override void Stop()
                {
                    if (IsValid()) planter.IsBusy = false;
                    base.Stop();
                }
                public override bool IsValid()
                {
                    return planter?.IsValid == true;
                }
                #endregion

                #region Coroutines
                IEnumerator FindSeeds()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (Farm.Farmer.Inventory.GetAmount(seed) < planter.CountFreeSlot)
                    {
                        foreach (var _storage in FarmManager.GetFarmAccessEntity<StorageComponent>(Farm.Navigation.Storages.ToArray()))
                        {
                            if (IsValid())
                            {
                                if (_storage.Inventory.HasItem(seed))
                                {
                                    yield return Move(_storage);

                                    if (IsValid())
                                    {
                                        if (moveMode == MoveMode.Finish && target?.IsValid == true && target.Inventory?.itemList?.FindAll(x => x.info == seed) is List<Item> items)
                                        {
                                            foreach (var item in items)
                                            {
                                                int count = planter.CountFreeSlot - Farm.Farmer.Inventory.GetAmount(seed);
                                                if (count <= 0) break;
                                                if (item.amount <= count)
                                                {
                                                    if (!item.MoveToContainer(Farm.Farmer.Inventory.containerMain))
                                                    {
                                                        brain?.SetStatus(StatusFarmer.ClearInventory);
                                                        StopCoroutineJob(true, false);
                                                    }
                                                }
                                                else
                                                {
                                                    Item item2 = ItemManager.Create(seed, count);
                                                    if (item2.MoveToContainer(Farm.Farmer.Inventory.containerMain)) item.UseItem(count);
                                                    else
                                                    {
                                                        item2.Remove();
                                                        brain?.SetStatus(StatusFarmer.ClearInventory);
                                                        StopCoroutineJob(true, false);
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    else
                                    {
                                        StopCoroutineJob(true, false);
                                    }
                                }
                            }
                            else
                            {
                                StopCoroutineJob(true, false);
                            }
                        }
                    }

                    yield return CoroutineEx.waitForSeconds(timeWait);

                    bool hasAmount = Farm.Farmer.Inventory.GetAmount(seed) > 0;

                    StopCoroutineJob(!hasAmount, hasAmount);
                }
                IEnumerator PlantedSeeds()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (IsValid())
                    {
                        yield return Move(planter);

                        if (IsValid() && moveMode == MoveMode.Finish)
                        {
                            while (Farm.Farmer.Inventory.HasItem(seed) && planter.CountFreeSlot > 0)
                            {
                                Item itemSeed = null;
                                if (Farm.Farmer.Inventory.containerBelt.GetSlot(0) is Item item)
                                {
                                    if (item.info != seed)
                                    {
                                        if (!brain.MoveItemBeltToMain())
                                        {
                                            brain?.SetStatus(StatusFarmer.ClearInventory);
                                            StopCoroutineJob(true, false);
                                        }
                                        else
                                        {
                                            if (Farm.Farmer.Inventory.containerMain.FindItemByItemID(seed.itemid) is Item item2)
                                            {
                                                if (!item2.MoveToContainer(Farm.Farmer.Inventory.containerBelt)) StopCoroutineJob(true, false);
                                                else itemSeed = item2;
                                            }
                                            else StopCoroutineJob(true, false);
                                        }
                                    }
                                    else itemSeed = item;
                                }
                                else
                                {
                                    if (Farm.Farmer.Inventory.containerMain.FindItemByItemID(seed.itemid) is Item item2)
                                    {
                                        if (!item2.MoveToContainer(Farm.Farmer.Inventory.containerBelt)) StopCoroutineJob(true, false);
                                        else itemSeed = item2;
                                    }
                                    else StopCoroutineJob(true, false);
                                }
                                brain.ActivatedBeltItem();
                                yield return CoroutineEx.waitForSeconds(timeWait);

                                planter.PlantGrowable(itemSeed);
                                yield return CoroutineEx.waitForSeconds(timeWait);
                            }
                        }
                        else StopCoroutineJob(true, false);
                    }
                    else StopCoroutineJob(true, false);

                    StopCoroutineJob(false, true);
                }
                #endregion
            }
