            /// <summary>
            /// Adding fertilizer to planted crops.
            /// </summary>
            public class JobFertilizerToPlanted : BaseJob, IFarmerJob
            {
                PlanterComponent planter;
                ItemDefinition fertilizerItemDef;
                List<Item> fertilizers = Pool.Get<List<Item>>();

                #region MethodsPool
                public override void EnterPool()
                {
                    base.EnterPool();
                    planter = null;
                    fertilizerItemDef = null;
                    Pool.FreeUnmanaged(ref fertilizers);
                }
                #endregion

                #region Methods
                public override void Init(FarmManager _farm, params object[] args)
                {
                    base.Init(_farm, args);
                    planter = args[0] as PlanterComponent;
                    planter.IsBusy = true;
                    fertilizerItemDef = ItemManager.FindItemDefinition(idFertilizer);
                    fertilizers = Pool.Get<List<Item>>();
                }
                public override void NextStage()
                {
                    base.NextStage();
                    switch (stage)
                    {
                        case 1:
                            {
                                status = "JobStatus_FertilizerToPlanted";
                                argsStatus = new object[0];
                                StartCoroutineJob(FertilizerToPlanted());
                                break;
                            }
                        default:
                            {
                                IsCompleted = true;
                                break;
                            }
                    }
                }
                #endregion

                #region MethodsInterface
                public override void Start()
                {
                    base.Start();
                    Farm.SendLog("LogFarmer_FertilizerToPlanted");
                }
                public override bool IsValid()
                {
                    return planter?.IsValid == true;
                }
                public override void Stop()
                {
                    if (IsValid()) planter.IsBusy = false;
                    base.Stop();
                }
                #endregion

                #region Coroutines
                private IEnumerator FertilizerToPlanted()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (IsValid())
                    {
                        int num = planter.CountGrowAble() - planter.CountFertilizers - farmer.Inventory.containerMain.GetAmount(idFertilizer, true);
                        if (num > 0)
                        {
                            if (farmer.Inventory.containerMain.GetAmount(idFertilizer, true) is int count)
                            {
                                num -= count;
                                if (num > 0)
                                {
                                    foreach (var storage in FarmManager.GetFarmAccessEntity<StorageComponent>(Farm.Navigation.Storages.ToArray(), x => x.Inventory.HasAny(fertilizerItemDef)))
                                    {
                                        yield return Move(storage);
                                        if (IsValid() && moveMode == MoveMode.Finish)
                                        {
                                            if (storage?.IsValid == true)
                                            {
                                                fertilizers.Clear();
                                                int num2 = storage.Inventory.Take(fertilizers, idFertilizer, num);
                                                foreach (var item in fertilizers)
                                                {
                                                    if (!item.MoveToContainer(farmer.Inventory.containerMain) && !item.MoveToContainer(planter.Inventory))
                                                    {
                                                        var npc = farmer.GetNpc();
                                                        item.Drop(npc.GetDropPosition(), npc.GetDropVelocity());
                                                    }
                                                    num -= item.amount;
                                                }
                                                if (num <= 0) break;
                                            }
                                        }
                                    }
                                }

                                yield return CoroutineEx.waitForSeconds(timeWait);

                                if (IsValid())
                                {
                                    if (farmer.Inventory.containerMain.GetAmount(idFertilizer, true) > 0)
                                    {
                                        yield return Move(planter);
                                        if (IsValid() && moveMode == MoveMode.Finish)
                                        {
                                            planter.SetFertilizers(farmer.Inventory.containerMain);
                                        }
                                    }
                                }
                            }
                        }
                    }

                    yield return CoroutineEx.waitForSeconds(timeWait);
                    StopCoroutineJob(true, false);
                }
                #endregion
            }
