            /// <summary>
            /// Adding food to the chicken coop.
            /// </summary>
            public class JobChickenFood : BaseJob, IFarmerJob
            {
                ChickenCoopComponent chickenCoop;
                ItemDefinition food;

                #region MethodsPool
                public override void EnterPool()
                {
                    base.EnterPool();
                    chickenCoop = null;
                    food = null;
                }
                #endregion

                public override void Start()
                {
                    base.Start();
                    Farm.SendLog("LogFarmer_ChickenFood");
                }
                public override void Init(FarmManager _farm, params object[] args)
                {
                    base.Init(_farm, args);
                    chickenCoop = args[0] as ChickenCoopComponent;
                    chickenCoop.IsBusy = true;
                }
                public override bool IsValid() => chickenCoop?.IsValid == true;

                public override void Stop()
                {
                    if (IsValid()) chickenCoop.IsBusy = false;
                    base.Stop();
                }
                public override void NextStage()
                {
                    base.NextStage();
                    switch (stage)
                    {
                        case 1:
                            {
                                status = "JobStatus_FindFoodChickens";
                                argsStatus = new object[0];
                                StartCoroutineJob(FindFood());
                                break;
                            }
                        case 2:
                            {
                                status = "JobStatus_FoodChickens";
                                argsStatus = new object[0];
                                StartCoroutineJob(FoodChickens());
                                break;
                            }
                        default:
                            {
                                IsCompleted = true;
                                break;
                            }
                    }
                }

                #region Coroutines
                IEnumerator FindFood()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    Farm.Farmer.Inventory.TryGetItemToFoodChickens(Farm, out food);
                    if (food == null || Farm.Farmer.Inventory.GetAmount(food) < food.stackable)
                    {
                        foreach (var _storage in FarmManager.GetFarmAccessEntity<StorageComponent>(Farm.Navigation.Storages.ToArray()))
                        {
                            if (IsValid())
                            {
                                if (food == null && !_storage.Inventory.TryGetItemToFoodChickens(Farm, out food)) continue;
                                if (_storage.Inventory.HasItem(food))
                                {
                                    yield return Move(_storage);

                                    if (IsValid())
                                    {
                                        if (moveMode == MoveMode.Finish && _storage?.IsValid == true && _storage.Inventory?.itemList?.FindAll(x => x.info == food) is List<Item> items)
                                        {
                                            foreach (var item in items)
                                            {
                                                int count = food.stackable - Farm.Farmer.Inventory.GetAmount(food);
                                                if (count <= 0) break;
                                                if (item.amount <= count)
                                                {
                                                    if (!item.MoveToContainer(Farm.Farmer.Inventory.containerMain))
                                                    {
                                                        brain?.SetStatus(StatusFarmer.ClearInventory);
                                                        StopCoroutineJob(true, false);
                                                        yield break;
                                                    }
                                                }
                                                else
                                                {
                                                    Item item2 = ItemManager.Create(food, count);
                                                    if (item2.MoveToContainer(Farm.Farmer.Inventory.containerMain)) item.UseItem(count);
                                                    else
                                                    {
                                                        item2.Remove();
                                                        brain?.SetStatus(StatusFarmer.ClearInventory);
                                                        StopCoroutineJob(true, false);
                                                        yield break;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    else
                                    {
                                        StopCoroutineJob(true, false);
                                        yield break;
                                    }
                                }
                            }
                            else
                            {
                                StopCoroutineJob(true, false);
                                yield break;
                            }
                        }
                    }

                    yield return CoroutineEx.waitForSeconds(timeWait);

                    bool hasAmount = food != null && Farm.Farmer.Inventory.GetAmount(food) > 0;

                    StopCoroutineJob(!hasAmount, hasAmount);
                }
                IEnumerator FoodChickens()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (IsValid())
                    {
                        yield return Move(chickenCoop);

                        if (IsValid())
                        {
                            if (moveMode == MoveMode.Finish && !chickenCoop.HasFood)
                            {
                                chickenCoop.FoodChickens(Farm.Farmer.Inventory.FindItemByItemID(food.itemid));
                            }
                        }
                    }

                    StopCoroutineJob(true, false);
                }
                #endregion
            }
