            /// <summary>
            /// Очистка инвентаря.
            /// </summary>
            public class JobClearInventory : BaseJob, IFarmerJob
            {
                public override void Start()
                {
                    base.Start();
                    Farm.SendLog("LogFarmer_ClearInventory");
                }
                public override bool IsValid() => farmer != null;
                public override void NextStage()
                {
                    base.NextStage();
                    switch (stage)
                    {
                        case 1:
                            {
                                status = "JobStatus_ClearInventory";
                                argsStatus = new object[0];
                                StartCoroutineJob(ClearInventory());
                                break;
                            }
                        default:
                            {
                                IsCompleted = true;
                                break;
                            }
                    }
                }

                #region Coroutines
                IEnumerator ClearInventory()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);
                    if (IsValid())
                    {
                        StorageComponent[] storages = Farm.Navigation.Storages.ToArray();
                        if (!Farm.Farmer.Inventory.containerMain.IsEmpty())
                        {
                            if (Farm.Data.UISetup.Fertilizers.EnableProductions && Farm.Farmer.Inventory.containerMain.itemList.Exists(x => Farm.CanComposter(x)))
                            {
                                foreach (var composter in FarmManager.GetFarmAccessEntity<FertilizerComponent>(storages))
                                {
                                    yield return Move(composter);
                                    if (IsValid())
                                    {
                                        if (moveMode == MoveMode.Finish && composter?.IsValid == true)
                                        {
                                            composter.MoveAllItems(Farm.Farmer.Inventory.containerMain);
                                        }

                                        if (Farm.Farmer.Inventory.containerMain.IsEmpty() || !Farm.Farmer.Inventory.containerMain.itemList.Exists(x => Farm.CanComposter(x))) break;
                                    }
                                    else StopCoroutineJob(true, false);
                                }
                            }

                            yield return CoroutineEx.waitForSeconds(timeWait);

                            Dictionary<ItemDefinition, List<ulong>> items = Pool.Get<Dictionary<ItemDefinition, List<ulong>>>();
                            foreach (var item in farmer.Inventory.containerMain.itemList)
                            {
                                if (item != null)
                                {
                                    if (!items.ContainsKey(item.info))
                                    {
                                        items.Add(item.info, new List<ulong>());
                                    }
                                    if (!items[item.info].Contains(item.skin)) items[item.info].Add(item.skin);
                                }
                            }

                            foreach (var item in items)
                            {
                                foreach (var skin in item.Value)
                                {
                                    yield return FindAndMoveItemsToIdealStorage(storages, farmer.Inventory.containerMain, item.Key, skin, storage => storage.SortItemsByShortName(), null);
                                    if (IsValid()) continue;
                                    else
                                    {
                                        StopCoroutineJob(true, false);
                                        yield break;
                                    }
                                }
                            }
                        }
                    }
                    yield return CoroutineEx.waitForSeconds(timeWait);
                    StopCoroutineJob(true, false);
                }
                #endregion

            }
            /// <summary>
            /// Collects food and waste for composting
            /// </summary>
            public class JobComposter : BaseJob, IFarmerJob
            {
                FertilizerComponent fertilizer;

                #region MethodsPool
                public override void EnterPool()
                {
                    base.EnterPool();
                    fertilizer = null;
                }
                #endregion

                public override void Start()
                {
                    base.Start();
                    Farm.SendLog("LogFarmer_Composter");
                }
                public override void Init(FarmManager _farm, params object[] args)
                {
                    base.Init(_farm, args);
                    fertilizer = args[0] as FertilizerComponent;
                    fertilizer.IsBusy = true;
                }
                public override bool IsValid() => fertilizer?.IsValid == true;
                public override void Stop()
                {
                    if (IsValid()) fertilizer.IsBusy = false;
                    base.Stop();
                }
                public override void NextStage()
                {
                    base.NextStage();
                    switch (stage)
                    {
                        case 1:
                            {
                                status = "JobStatus_ComposableItemsToComposter";
                                argsStatus = new object[0];
                                StartCoroutineJob(ComposableItemsToComposter());
                                break;
                            }
                        default:
                            {
                                IsCompleted = true;
                                break;
                            }
                    }
                }

                #region Coroutines
                IEnumerator ComposableItemsToComposter()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (IsValid())
                    {
                        foreach (var storage in FarmManager.GetFarmAccessEntity<StorageComponent>(Farm.Navigation.Storages.ToArray(), x => x.HasItemsComposter(fertilizer)))
                        {
                            yield return Move(storage);
                            if (IsValid())
                            {
                                if (moveMode == MoveMode.Finish && storage?.IsValid == true)
                                {
                                    storage.Inventory.MoveAllItems(Farm.Farmer.Inventory.containerMain, x => x != null && Farm.CanComposter(x) && fertilizer.Inventory.CanAcceptItem(x, -1) == ItemContainer.CanAcceptResult.CanAccept);
                                }
                            }
                        }

                        if (IsValid())
                        {
                            if (Farm.Farmer.Inventory.containerMain.itemList.Exists(x => Farm.CanComposter(x) && fertilizer.Inventory.CanAcceptItem(x, -1) == ItemContainer.CanAcceptResult.CanAccept))
                            {
                                yield return Move(fertilizer);
                                if (IsValid())
                                {
                                    if (moveMode == MoveMode.Finish)
                                    {
                                        fertilizer.MoveAllItems(Farm.Farmer.Inventory.containerMain);
                                    }
                                }
                            }
                        }

                        yield return CoroutineEx.waitForSeconds(timeWait);

                        if (IsValid())
                        {
                            int amountFertilizers = fertilizer.Inventory.GetAmount(fertilizer.FertilizerDef.itemid, false);
                            fertilizer.Inventory.MoveAllItems(Farm.Farmer.Inventory.containerMain, x => x != null && x.info == fertilizer.FertilizerDef);
                            amountFertilizers -= fertilizer.Inventory.GetAmount(fertilizer.FertilizerDef.itemid, false);
                            //отправить в статистику количество полученных удобрений из компостера
                            if(amountFertilizers > 0) Farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Composter, amountFertilizers);
                        }
                    }

                    yield return CoroutineEx.waitForSeconds(timeWait);
                    StopCoroutineJob(true, false);
                }
                #endregion

            }
