            {
                public override void Start()
                {
                    base.Start();
                    if(farmer?.Inventory?.containerMain?.IsFull() == true) brain.SetStatus(StatusFarmer.ClearInventory);
                    else Farm.SendLog("LogFarmer_PickupDroppedItem");
                }
                public override bool IsValid() => farmer?.GetNpc()?.IsValid() == true;
                public override void NextStage()
                {
                    base.NextStage();
                    switch (stage)
                    {
                        case 1:
                            {
                                status = "JobStatus_PickupDroppedItem";
                                argsStatus = new object[0];
                                StartCoroutineJob(MoveToDropItem());
                                break;
                            }
                        default:
                            {
                                IsCompleted = true;
                                break;
                            }
                    }
                }
                private IEnumerator MoveToDropItem()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (IsValid())
                    {
                        foreach (var item in Farm.Navigation.DropItems.ToArray())
                        {
                            if (item?.IsValid == true)
                            {
                                yield return Move(item.ServerPosition);
                                if (IsValid())
                                {
                                    if (moveMode == MoveMode.Finish)
                                    {
                                        if (item?.IsValid == true) item.GetEntity<DroppedItem>()?.TransferAllItemsToContainer(farmer.Inventory.containerMain, farmer.GetNpc().GetDropPosition());
