            /// <summary>
            /// Mining resources
            /// </summary>
            public class JobMiningResources : BaseJob, IFarmerJob
            {
                public override void Start()
                {
                    base.Start();
                    if(farmer?.Inventory?.containerMain?.IsFull() == true) brain.SetStatus(StatusFarmer.ClearInventory);
                    else Farm.SendLog("LogFarmer_MiningResources");
                }
                public override void Update()
                {
                    if (!IsValid()) StopCoroutineJob(true, false);
                    else base.Update();
                }
                public override bool IsValid() => farmer?.GetNpc()?.IsValid() == true;
                public override void NextStage()
                {
                    base.NextStage();
                    switch (stage)
                    {
                        case 1:
                            {
                                status = "JobStatus_FindToolMining";
                                argsStatus = new object[0];
                                StartCoroutineJob(FindToolMining());
                                break;
                            }
                        case 2:
                            {
                                status = "JobStatus_Mining";
                                argsStatus = new object[0];
                                StartCoroutineJob(Mining());
                                break;
                            }
                        default:
                            {
                                IsCompleted = true;
                                break;
                            }
                    }
                }
                private IEnumerator FindToolMining()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (IsValid())
                    {
                        yield return EquipItem(Farm.Settings.Controller.MiningItem, Farm.Settings.Controller.MiningItem.CanCreate, item => !item.isBroken);

                        if (IsValid())
                        {
                            if (Farm.Farmer.GetNpc().GetActiveItem() is Item item && Farm.Settings.Controller.MiningItem.EqualsItem(item) && item.GetHeldEntity() is BaseMelee) StopCoroutineJob(false, true);
                            else
                            {
                                Farm.SendLog("LogFarmer_ToolMiningItemNotFound");
                                StopCoroutineJob(true, false);
                            }
                            yield break;
                        }
                    }

                    StopCoroutineJob(true, false);
                }
                private IEnumerator Mining()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (IsValid())
                    {
                        foreach (var resource in Farm.Navigation.ResourceEntities.ToArray())
                        {
                            if (resource?.IsValid == true)
                            {
                                yield return Move(resource.ServerPosition);
                                if (IsValid())
                                {
                                    if (moveMode == MoveMode.Finish)
                                    {
                                        if (resource?.IsValid == true)
                                        {
                                            NPCPlayer npc = farmer.GetNpc();
                                            OreResourceEntity target = resource.GetEntity<OreResourceEntity>();
                                            while (target?.IsValid() == true)
                                            {
                                                npc.SetAimDirection(resource.ServerPosition);
                                                brain.AttackMelee(npc.GetHeldEntity(), target);
                                                brain.ResetTimerStatus();
                                                yield return CoroutineEx.waitForSeconds(2f);
                                            }
                                        }
                                    }
                                    else
                                    {
                                        Farm.Navigation.ResourceEntities.Remove(resource);
                                        Destroy(resource);
                                    }
                                }
                                else
                                {
                                    StopCoroutineJob(true, false);
                                    yield break;
                                }
                            }
                            if (farmer?.Inventory.containerMain.IsFull() == true) brain.SetStatus(StatusFarmer.ClearInventory);
                            else brain.ResetTimerStatus();
                        }
                    }
                    StopCoroutineJob(false, true);
                }
            }
            public class JobSortedStorages : BaseJob, IFarmerJob
            {
                #region MethodsPool
                #endregion

                public override void Start()
                {
                    base.Start();
                    Farm.SendLog("LogFarmer_SortedStorages");
                }
                public override void Update()
                {
                    if (!IsValid()) StopCoroutineJob(true, false);
                    else base.Update();
                }
                public override bool IsValid() => Farm.IsSorted;
                public override void NextStage()
                {
                    base.NextStage();
                    switch (stage)
                    {
                        case 1:
                            {
                                StartCoroutineJob(SortedStorages());
                                break;
                            }
                        default:
                            {
                                IsCompleted = true;
                                break;
                            }
                    }
                }
                private void GiveFarmerItems(ItemDefinition itemDef, ulong skin)
                {
                    List<Item> items = Pool.Get<List<Item>>();
                    items.AddRange(Farm.SortedContainer.itemList);
                    foreach (var item in items)
                    {
                        if (item.info == itemDef && item.skin == skin)
                        {
                            item.RemoveFromContainer();
                            farmer.GetNpc().GiveItem(item);
                        }
                    }
                    Pool.FreeUnmanaged(ref items);
                }
                private IEnumerator SortedStorages()
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (IsValid())
                    {
                        IFarmComponent[] list = Farm.Navigation.Storages.ToArray();

                        while (!Farm.SortedContainer.IsEmpty())
                        {
                            yield return CoroutineEx.waitForSeconds(timeWait);
                            Farm.SortedContainerOrderBy();
                            var itemDef = Farm.SortedContainer.itemList[0]?.info;
                            if (itemDef == null) continue;
                            ulong skin = Farm.SortedContainer.itemList[0].skin;

                            yield return FindAndMoveItemsToIdealStorage(list, Farm.SortedContainer, itemDef, skin, null, GiveFarmerItems);

                            if (IsValid()) continue;
                            else break;
                        }
                    }

                    StopCoroutineJob(true, false);
                }
            }
            public class JobMetabolism : BaseJob, IFarmerJob
            {
                StatusFarmer? statusFarmer;
                NPCPlayer npc;
                MetabolismAttribute hydration => npc?.metabolism.hydration;
                MetabolismAttribute calories => npc?.metabolism.calories;
                public override void EnterPool()
                {
                    base.EnterPool();
                    npc = null;
                    statusFarmer = null;
                }
                public override void Init(FarmManager _farm, params object[] args)
                {
                    base.Init(_farm, args);

                    npc = farmer.GetNpc();
                    statusFarmer = (StatusFarmer)args[0];
                }
                public override void Update()
                {
                    if (!IsValid()) StopCoroutineJob(true, false);
                    else base.Update();
                }
                public override bool IsValid() => npc != null;
                public override void NextStage()
                {
                    base.NextStage();
                    switch (stage)
                    {
                        case 1:
                            {
                                if (statusFarmer != null)
                                {
                                    if (statusFarmer == StatusFarmer.Drink && hydration != null) StartCoroutineJob(MetabolismDrink());
                                    if (statusFarmer == StatusFarmer.Eat && calories != null) StartCoroutineJob(MetabolismFood());
                                    if (statusFarmer == StatusFarmer.Medication && npc != null) StartCoroutineJob(MetabolismMedication());
                                }
                                else IsCompleted = true;
                                break;
                            }
                        default:
                            {
                                IsCompleted = true;
                                break;
                            }
                    }
                }
                private bool SV_Drink()
                {
                    BasePlayer player = npc;
                    if ((bool)player && player.metabolism.CanConsume() && (!player.isMounted || player.GetMounted().canDrinkWhileMounted))
                    {
                        ItemDefinition itemDefinition = WaterTypes.WaterItemDef;
                        ItemModConsumable component = itemDefinition.GetComponent<ItemModConsumable>();
                        Item itemWater = ItemManager.Create(itemDefinition, component.amountToConsume, 0uL);
                        ItemModConsume component2 = itemWater.info.GetComponent<ItemModConsume>();
                        if (component2.CanDoAction(itemWater, player))
                        {
                            Farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Farmer, DataFarm.StatsGeneral.StatsFarmer.FarmerType.UseItems, itemDefinition.itemid, component.amountToConsume);
                            component2.DoAction(itemWater, player);
                        }
                        itemWater?.Remove();
                        player.metabolism.MarkConsumption();
                        return true;
                    }
                    return false;
                }
                public void SVDrink(ItemContainer inventory)
                {
                    if (!npc.metabolism.CanConsume())
                    {
                        return;
                    }

                    foreach (Item item in inventory.itemList)
                    {
                        ItemModConsume component = item.info.GetComponent<ItemModConsume>();
                        ItemModConsumable component2 = item.info.GetComponent<ItemModConsumable>();
                        if (!(component == null) && component.CanDoAction(item, npc))
                        {
                            Farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Farmer, DataFarm.StatsGeneral.StatsFarmer.FarmerType.UseItems, item.info.itemid, component2.amountToConsume > item.amount ? item.amount : component2.amountToConsume);
                            component.DoAction(item, npc);
                            break;
                        }
                    }
                }
                private IEnumerator MetabolismDrink()
                {
                    Farm.SendLog("LogFarmer_MetabolismDrink");
                    yield return CoroutineEx.waitForSeconds(timeWait);
                    if (IsValid())
                    {
                        if (farmer.CanDrink())
                        {
                            foreach (var container in FarmManager.GetFarmAccessEntity<WaterContainersComponent>(Farm.Navigation.Waters.ToArray(), x => x.HasWater))
                            {
                                yield return Move(container);

                                if (moveMode == MoveMode.Finish)
                                {
                                    while (IsValid() && container?.IsValid == true && container.HasWater && hydration.value < hydration.max)
                                    {
                                        SVDrink(container.Inventory);
                                        yield return CoroutineEx.waitForSeconds(2f);
                                    }
                                }
                            }
                            if (IsValid() && hydration.value < hydration.max && Farm.Navigation.RiverPoint != Vector3.zero)
                            {
                                yield return Move(Farm.Navigation.RiverPoint);
                                if (moveMode == MoveMode.Finish)
                                {
                                    while (IsValid() && SV_Drink() && hydration.value < hydration.max)
                                    {
                                        yield return CoroutineEx.waitForSeconds(2f);
                                    }
                                }
                            }
                        }
                    }
                    StopCoroutineJob(true, false);
                }
                private IEnumerator MetabolismFood()
                {
                    Farm.SendLog("LogFarmer_MetabolismFood");
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (IsValid())
                    {
                        if (farmer.CanEat())
                        {
                            foreach (var container in FarmManager.GetFarmAccessEntity<StorageComponent>(Farm.Navigation.Storages.ToArray(), x => x.HasFoodFarmer()))
                            {
                                yield return Move(container);
                                if (IsValid())
                                {
                                    if (moveMode == MoveMode.Finish && container.IsValid)
                                    {
                                        while (calories.value < calories.max && container?.IsValid == true && container.Inventory.itemList.Find(x => x.info.HasComponent<ItemModConsume>()) is Item item && item.amount > 0 && item.info.TryGetComponent<ItemModConsume>(out var modConsume))
                                        {
                                            try
                                            {
                                                if (modConsume.CanDoAction(item, npc))
                                                {
                                                    int id = item.info.itemid;
                                                    modConsume.DoAction(item, npc);
                                                    Farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Farmer, DataFarm.StatsGeneral.StatsFarmer.FarmerType.UseItems, id, 1);
                                                }
                                            }
                                            catch (Exception ex)
                                            {
                                                Debug.LogError(ex?.Message);
                                                break;
                                            }
                                            yield return CoroutineEx.waitForSeconds(3f);
                                        }
                                        if (calories.value >= calories.max)
                                        {
                                            StopCoroutineJob(true, false);
                                            yield break;
                                        }
                                    }
                                }
                            }
                            if (IsValid() && farmer.CanEat())
                            {
                                Farm.SendLog("LogFarmer_MetabolismNotFood");
                            }
                        }

                        StopCoroutineJob(true, false);
                    }
                }
                private IEnumerator MetabolismMedication()
                {
                    Farm.SendLog("LogFarmer_MetabolismMedication");
                    yield return CoroutineEx.waitForSeconds(timeWait);
                    
                    if (IsValid() && farmer.CanMedication())
                    {
                        yield return EquipItem(Farm.Settings.Controller.MedicineItem.GetItemDefinition(), Farm.Settings.Controller.MedicineItem.Item.SkinID, Farm.Settings.Controller.MedicineItem.CanCreate);

                        yield return CoroutineEx.waitForSeconds(6f);
                        
                        while (IsValid() && farmer.CanMedication() && npc.Health() < npc.MaxHealth() && npc.GetActiveItem() is Item item && item.amount > 0 && item.GetHeldEntity() is MedicalTool medicalTool)
                        {
                            int id = item.info.itemid;
                            medicalTool.ServerUse();
                            Farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Farmer, DataFarm.StatsGeneral.StatsFarmer.FarmerType.UseItems, id, 1);

                            yield return CoroutineEx.waitForSeconds(8f);
                        }

                        yield return CoroutineEx.waitForSeconds(1f);
                        
                        while (IsValid() && farmer.CanMedication() && npc.Health() < npc.MaxHealth() && npc.GetActiveItem() is Item item && item.amount > 0 && item.info.TryGetComponent<ItemModConsume>(out var modConsume))
                        {
                            int id = item.info.itemid;
                            if (modConsume.CanDoAction(item, npc)) modConsume.DoAction(item, npc);
                            Farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Farmer, DataFarm.StatsGeneral.StatsFarmer.FarmerType.UseItems, id, 1);

                            yield return CoroutineEx.waitForSeconds(8f);
                        }
                    }

                    StopCoroutineJob(true, false);
                }
            }
            public abstract class BaseJob : Pool.IPooled
            {
                private static Dictionary<Type, List<BaseJob>> buffer = new();
                public BaseJob Get => this;
                public FarmManager Farm { get; private set; }
                public BrainFarmer brain => Farm?.Farmer?.Brain;
                public FarmerController farmer => Farm?.Farmer;
                protected IFarmComponent target;
                protected Coroutine coroutine;
                protected MoveMode moveMode = MoveMode.Idle;
                protected string status = "";
                protected object[] argsStatus = new object[0];
                public bool IsCompleted { get; protected set; } = false;
                protected int stage = 0;
                protected bool stageCompleted = false;
                private TimeSince timerJob = 0;

                public BaseJob()
                {
                }


                public virtual void Init(FarmManager _farm, params object[] args)
                {
                    Farm = _farm;
                    timerJob = 0;
                }
                public virtual void NextStage()
                {
                    stage++;
                    stageCompleted = false;
                    brain?.ResetTimerStatus();
                }

                #region MethodsInterface
                public virtual bool IsValid() => true;
                public virtual void Start()
                {
                    NextStage();
#if DebugLog
                    Debug.Log($"Start Job: {GetType().Name}(timer queue: {timerJob:0.00} sec) Farmer[{Farm?.Farmer?.GetNpc()?.displayName}]");
#endif
                    timerJob = 0;
                }
                public virtual void Update()
                {
                    if (stageCompleted) NextStage();
                }
                public virtual void Stop()
                {
#if DebugLog
                    Debug.Log($"Stop Job: {GetType().Name}(timer job: {timerJob:0.00} sec) Farmer[{Farm?.Farmer?.GetNpc()?.displayName}]");
#endif
                }
                #endregion

                #region Methods
                protected bool TryGetStorageFromItem(IFarmComponent[] list, ItemDefinition itemDef, ulong skin, out StorageComponent storage, Func<StorageComponent, bool> func)
                {
                    storage = null;
                    List<StorageComponent> storages = Pool.Get<List<StorageComponent>>();
                    foreach (StorageComponent _storage in FarmManager.GetFarmAccessEntity(list, func)) storages.Add(_storage);
                    if (storages.Count > 0)
                    {
                        storage = storages.Max(x =>
                        {
                            return x.Inventory.GetAmount(itemDef.itemid, true);
                        });
                    }
                    Pool.FreeUnmanaged(ref storages);
                    return storage != null;
                }
                private void FinishMoveTarget(bool finish)
                {
                    if (!finish) moveMode = MoveMode.NotFinish;
                    else moveMode = MoveMode.Finish;
                }
                protected IEnumerator Move(IFarmComponent _target)
                {
                    target = _target;
                    if (target != null)
                    {
                        moveMode = MoveMode.Moving;
                        Farm.MoveTo(target.ServerPosition, FinishMoveTarget);
                        while (moveMode == MoveMode.Moving) yield return CoroutineEx.waitForSeconds(timeWait);
                    }
                    else moveMode = MoveMode.NotFinish;
                }
                protected IEnumerator Move(Vector3 _target)
                {
                    moveMode = MoveMode.Moving;
                    Farm.MoveTo(_target, FinishMoveTarget);
                    while (moveMode == MoveMode.Moving) yield return CoroutineEx.waitForSeconds(timeWait);
                }
                protected void StartCoroutineJob(IEnumerator routine)
                {
                    if (coroutine != null) StopCoroutine(coroutine);
                    IsCompleted = false;
                    stageCompleted = false;
                    coroutine = StartCoroutine(routine);
                }
                protected void StopCoroutineJob(bool isCompleted, bool isStageCompleted)
                {
                    IsCompleted = isCompleted;
                    stageCompleted = isStageCompleted;
                    if (coroutine != null) StopCoroutine(coroutine);
                    coroutine = null;
                }
                private Coroutine StartCoroutine(IEnumerator routine) => brain?.StartCoroutine(routine) ?? null;
                private void StopCoroutine(Coroutine coroutine) => brain?.StopCoroutine(coroutine);
                public string GetStatus()
                {
                    if (!string.IsNullOrEmpty(status)) return Farm.GetLangText(status, argsStatus);
                    else return "";
                }
                public virtual void EnterPool()
                {
                    if (coroutine != null)
                    {
                        IsCompleted = true;
                        StopCoroutine(coroutine);
                        coroutine = null;
                    }
                    status = null;
                    argsStatus = null;
                    Farm = null;
                    target = null;
                    timerJob = 0;
                }
                public virtual void LeavePool()
                {
                    status = "JobStatus_InitJob";
                    argsStatus = new object[0];
                    IsCompleted = false;
                    moveMode = MoveMode.Idle;
                    stage = 0;
                    stageCompleted = false;
                }
                #endregion

                #region Coroutines
                /// <summary>
                /// Поиск в хранилище и добавление предмета на пояс с активацией, предварительно проверка наличия на поясе и в инвентаре.
                /// Если есть сторонний предмет на поясе. то он перекладывается в инвентарь, если места в инвентаре нету, то вызывается работа по освобождению инвентаря.
                /// </summary>
                /// <param name="itemUI"> предмет класса плагина</param>
                /// <param name="canCreate"> разрешение на создание предмета, если он не найден в хранилище</param>
                /// <param name="func">дополнительная проверка предмета для соответствия поиску</param>
                /// <returns></returns>
                protected IEnumerator EquipItem(ItemUI itemUI, bool canCreate = false, Func<Item, bool> func = null)
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    Item searchItem = null;

                    if (Farm.Farmer.Inventory.containerBelt.GetSlot(0) is Item item)
                    {
                        if (itemUI.EqualsItem(item) && (func == null || func(item)))
                        {
                            brain?.ActivatedBeltItem();
                            yield break;
                        }
                        else
                        {
                            if (!brain.MoveItemBeltToMain())
                            {
                                brain?.SetStatus(StatusFarmer.ClearInventory);
                                yield break;
                            }
                        }
                    }
                    else
                    {
                        foreach (var item2 in Farm.Farmer.Inventory.containerMain.itemList)
                        {
                            if (item2 != null && itemUI.EqualsItem(item2) && (func == null || func(item2)))
                            {
                                searchItem = item2;
                                break;
                            }
                        }

                        yield return CoroutineEx.waitForSeconds(timeWait);

                        if (searchItem == null)
                        {
                            foreach (var storage in FarmManager.GetFarmAccessEntity<StorageComponent>(Farm.Navigation.Storages.ToArray(), x => x.Inventory.itemList.Exists(y => y != null && itemUI.EqualsItem(y) && (func == null || func(y)))))
                            {
                                yield return Move(storage);

                                if (moveMode == MoveMode.Finish && storage?.IsValid == true)
                                {
                                    foreach (var item2 in storage.Inventory.itemList)
                                    {
                                        if (item2 != null && itemUI.EqualsItem(item2) && (func == null || func(item2)))
                                        {
                                            searchItem = item2;
                                            break;
                                        }
                                    }
                                }
                                if (searchItem != null) break;
                                else yield return CoroutineEx.waitForSeconds(timeWait);
                            }
                        }
                    }

                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (searchItem == null && canCreate)
                    {
                        searchItem = itemUI.CreateItem();
                    }

                    if (searchItem != null && searchItem.MoveToContainer(Farm.Farmer.Inventory.containerBelt, 0)) brain?.ActivatedBeltItem();
                }
                /// <summary>
                /// Поиск в хранилище и добавление предмета на пояс с активацией, предварительно проверка наличия на поясе и в инвентаре.
                /// Если есть сторонний предмет на поясе. то он перекладывается в инвентарь, если места в инвентаре нету, то вызывается работа по освобождению инвентаря.
                /// </summary>
                /// <param name="def"> предмет класса ItemDefinition</param>
                /// <param name="skin"> скин предмета</param>
                /// <param name="canCreate"> разрешение на создание предмета, если он не найден в хранилище</param>
                /// <param name="func">дополнительная проверка предмета для соответствия поиску</param>
                /// <returns></returns>
                protected IEnumerator EquipItem(ItemDefinition def, ulong skin, bool canCreate = false, Func<Item, bool> func = null)
                {
                    if (def == null) yield break;
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    Item searchItem = null;

                    if (Farm.Farmer.Inventory.containerBelt.GetSlot(0) is Item item)
                    {
                        if (item?.info == def && item.skin == skin && (func == null || func(item)))
                        {
                            brain?.ActivatedBeltItem();
                            yield break;
                        }
                        else
                        {
                            if (!brain.MoveItemBeltToMain())
                            {
                                brain?.SetStatus(StatusFarmer.ClearInventory);
                                yield break;
                            }
                        }
                    }
                    else
                    {
                        foreach (var item2 in Farm.Farmer.Inventory.containerMain.itemList)
                        {
                            if (item2?.info == def && item2.skin == skin && (func == null || func(item2)))
                            {
                                searchItem = item2;
                                break;
                            }
                        }

                        yield return CoroutineEx.waitForSeconds(timeWait);

                        if (searchItem == null)
                        {
                            foreach (var storage in FarmManager.GetFarmAccessEntity<StorageComponent>(Farm.Navigation.Storages.ToArray(), x => x.Inventory.itemList.Exists(y => y?.info == def && y.skin == skin && (func == null || func(y)))))
                            {
                                yield return Move(storage);

                                if (moveMode == MoveMode.Finish && storage?.IsValid == true)
                                {
                                    foreach (var item2 in storage.Inventory.itemList)
                                    {
                                        if (item2?.info == def && item2.skin == skin && (func == null || func(item2)))
                                        {
                                            searchItem = item2;
                                            break;
                                        }
                                    }
                                }
                                if (searchItem != null) break;
                                else yield return CoroutineEx.waitForSeconds(timeWait);
                            }
                        }
                    }

                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (searchItem == null && canCreate)
                    {
                        searchItem = ItemManager.Create(def, 1, skin);
                    }
                    bool move = searchItem != null && searchItem.MoveToContainer(Farm.Farmer.Inventory.containerBelt, 0);
                    #if DebugLog
                        Debug.Log($"EquipItem item {move}");
                    #endif
                    if (move) brain?.ActivatedBeltItem();
                }
                /// <summary>
                /// Наполнение водой активного предмета из накопителей воды на ферме
                /// </summary>
                /// <param name="amountWater">необходимое наполнение количества воды</param>
                /// <returns></returns>
                protected IEnumerator FillActiveWaterContainer(int amountWater)
                {
                    Item waterContainer = Farm.Farmer.Inventory.containerBelt.GetSlot(0);
                    BaseLiquidVessel liquidVessel = waterContainer?.GetHeldEntity() as BaseLiquidVessel;

                    if (liquidVessel == null) yield break;

                    int num1 = waterContainer.contents.maxStackSize - waterContainer.contents.GetAmount(WaterTypes.WaterItemDef.itemid, true);

                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (amountWater > waterContainer.contents.GetAmount(WaterTypes.WaterItemDef.itemid, true) && num1 > 0)
                    {
                        bool flag = false;
                        foreach (var water in FarmManager.GetFarmAccessEntity<WaterContainersComponent>(Farm.Navigation.Waters.ToArray(), x => x.HasWater))
                        {
                            yield return Move(water);
                            if (moveMode == MoveMode.Finish && water?.IsValid == true && water.HasWater)
                            {
                                int num3 = amountWater < waterContainer.contents.maxStackSize ? amountWater : waterContainer.contents.maxStackSize;
                                var findWater = water.Inventory.itemList.Find(x => x.info == WaterTypes.WaterItemDef);
                                if (findWater != null && liquidVessel != null)
                                {
                                    int amount = findWater.amount < num3 ? findWater.amount : num3;
                                    liquidVessel?.AddLiquid(WaterTypes.WaterItemDef, amount);
                                    findWater.UseItem(amount);
                                }
                            }
                            else continue;

                            int num4 = waterContainer.contents.GetAmount(WaterTypes.WaterItemDef.itemid, true);
                            if (num4 >= waterContainer.contents.maxStackSize || amountWater <= num4)
                            {
                                flag = true;
                                break;
                            }

                            yield return CoroutineEx.waitForSeconds(timeWait);
                        }
                        if (!flag && Farm.Navigation.RiverPoint != Vector3.zero)
                        {
                            yield return Move(Farm.Navigation.RiverPoint);
                            if (moveMode == MoveMode.Finish || farmer.GetNpc().WaterFactor() > 0.1f)
                            {
                                int num3 = amountWater < waterContainer.contents.maxStackSize ? amountWater : waterContainer.contents.maxStackSize;
                                int num4 = waterContainer.contents.GetAmount(WaterTypes.WaterItemDef.itemid, true);
                                if (num3 - num4 > 0) liquidVessel?.AddLiquid(WaterTypes.WaterItemDef, num3 - num4);
                            }
                        }
                    }
                }
                /// <summary>
                /// Наполнение водой из активного предмета, объекта фермы потребляющий воду
                /// </summary>
                /// <typeparam name="T">интерфейс потребляющий воду</typeparam>
                /// <param name="farmEntity">объект фермы потребляющий воду</param>
                /// <param name="liquidVessel">активный предмет класса BaseLiquidVessel</param>
                /// <returns></returns>
                protected IEnumerator FillFarmEntityWithWater<T>(T farmEntity, BaseLiquidVessel liquidVessel) where T : IWaterConsumer
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (farmEntity?.IsValid == true)
                    {
                        yield return Move(farmEntity);
                        if (farmEntity?.IsValid == true)
                        {
                            if (moveMode == MoveMode.Finish && liquidVessel?.GetContents() is Item water)
                            {
                                farmEntity.DoSplash(water);
                            }
                        }
                    }
                }
                /// <summary>
                /// Поиск и перемещение предметов в подходящее хранилище
                /// </summary>
                /// <param name="arrayStorages">массив хранилищ</param>
                /// <param name="itemDef">шаблон предмета</param>
                /// <param name="skin">скин предмета</param>
                /// <param name="callbackIsNotStorage">метод который вызывается, если не найдено хранилище</param>
                /// <returns></returns>
                protected IEnumerator FindAndMoveItemsToIdealStorage(IFarmComponent[] arrayStorages, ItemContainer container, ItemDefinition itemDef, ulong skin, UnityAction<StorageComponent> callbackFromMovesItems, UnityAction<ItemDefinition, ulong> callbackIsNotStorage)
                {
                    yield return CoroutineEx.waitForSeconds(timeWait);

                    StorageComponent storage = null;
                    bool isFoodSpoiling = itemDef.HasComponent<ItemModFoodSpoiling>();

                    if (TryGetStorageFromItem(arrayStorages, itemDef, skin, out storage, x => !x.Inventory.IsFull() && x.ExistCategory(itemDef.category) && x.IsFreeze == isFoodSpoiling))
                    {
                        yield return Move(storage);
                        if (IsValid())
                        {
                            if (moveMode == MoveMode.Finish && storage?.IsValid == true)
                            {
                                container.MoveAllItems(storage.Inventory, x => x != null && x.info == itemDef && x.skin == skin);
                                callbackFromMovesItems?.Invoke(storage);
                                yield break;
                            }
                        }
                        else yield break;
                    }

                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (TryGetStorageFromItem(arrayStorages, itemDef, skin, out storage, x => !x.Inventory.IsFull() && x.CategoryAll && x.IsFreeze == isFoodSpoiling))
                    {
                        yield return Move(storage);
                        if (IsValid())
                        {
                            if (moveMode == MoveMode.Finish && storage?.IsValid == true)
                            {
                                container.MoveAllItems(storage.Inventory, x => x != null && x.info == itemDef);
                                callbackFromMovesItems?.Invoke(storage);
                                yield break;
                            }
                        }
                        else yield break;
                    }

                    yield return CoroutineEx.waitForSeconds(timeWait);

                    if (isFoodSpoiling)
                    {
                        if (TryGetStorageFromItem(arrayStorages, itemDef, skin, out storage, x => !x.Inventory.IsFull() && x.ExistCategory(itemDef.category) && x.IsFreeze == false))
                        {
                            yield return Move(storage);
                            if (IsValid())
                            {
                                if (moveMode == MoveMode.Finish && storage?.IsValid == true)
                                {
                                    container.MoveAllItems(storage.Inventory, x => x != null && x.info == itemDef);
                                    callbackFromMovesItems?.Invoke(storage);
                                    yield break;
                                }
                            }
                            else yield break;
                        }

                        yield return CoroutineEx.waitForSeconds(timeWait);

                        if (TryGetStorageFromItem(arrayStorages, itemDef, skin, out storage, x => !x.Inventory.IsFull() && x.CategoryAll && x.IsFreeze == false))
                        {
                            yield return Move(storage);
                            if (IsValid())
                            {
                                if (moveMode == MoveMode.Finish && storage?.IsValid == true)
                                {
                                    container.MoveAllItems(storage.Inventory, x => x != null && x.info == itemDef);
                                    callbackFromMovesItems?.Invoke(storage);
                                    yield break;
                                }
                            }
                            else yield break;
                        }
                    }
                    callbackIsNotStorage?.Invoke(itemDef, skin);
                }
                #endregion

                public static T GetPool<T>(FarmManager _farm, params object[] args) where T : BaseJob, new()
                {
                    BaseJob job = null;
                    if (buffer.TryGetValue(typeof(T), out var bufferJob) && bufferJob.Count > 0)
                    {
                        job = bufferJob[0];
                        bufferJob.RemoveAt(0);
                    }
                    else job = new T();

                    if (job is T) job.LeavePool();
#if DebugLog
                    Debug.Log($"GetPool: {typeof(T).Name}(timer pooled: {job.timerJob:0.00} sec)");
#endif
                    job.Init(_farm, args);
                    return job as T;
                }
                public static void SetPool(BaseJob job)
                {
                    job.EnterPool();
                    var type = job.GetType();
                    if (!buffer.TryGetValue(type, out var bufferJob)) buffer.Add(type, bufferJob = new());
                    bufferJob.Add(job);
                }
                public static void InitPlugin() => buffer = new();
                public static void UnloadPlugin() => buffer = null;

                public enum MoveMode
                {
                    Idle, Moving, Finish, NotFinish, NotTarget
                }
            }
            #endregion

            public enum StatusFarmer
            {
                Idle, Initialization, NotInitialization, Authorization, PickupDropDeath, Sleeping, Eat, Drink, Medication, ClearInventory, Job, Sorted
            }
        }
        public partial class FarmerController : PluginFarmerComponent
        {
            public const float depth = 1.5f;
            public BrainFarmer Brain;
            private FarmManager farm;
            private FrankensteinPet frankenstein;
            private BaseNavigator navigator;
            private PathController pathController;
            private Vector3 startPoint;
            private Vector3 endPoint;
            private UnityAction<bool> onFinished;
            public BasePlayer GetOwnerPlayer => owner.OwnerID.IsSteamId() ? BasePlayer.FindByID(owner.OwnerID) : null;
            private float velocity => frankenstein?.NavAgent?.velocity.magnitude ?? 0;
            private TimeSince timerNotVelocity = 0;
            private TimeSince timerWarp = 0;
            private float distanceFarmerToPathFromCurrentPoint;
            public FarmManager Farm => farm;
            public bool IsInit => navigator != null && farm?.IsInitFarm == true;
            public bool IsSleeping => frankenstein.HasPlayerFlag(BasePlayer.PlayerFlags.Sleeping);
            public float PercentHealth => frankenstein ? frankenstein.Health() / frankenstein.MaxHealth() : 0;
            public float PercentCalories => frankenstein ? frankenstein.metabolism.calories.value / frankenstein.metabolism.calories.max : 0;
            public float PercentHydration => frankenstein ? frankenstein.metabolism.hydration.value / frankenstein.metabolism.hydration.max : 0;
            // private TimeSince timerPointForWarp;
            private TimeSince timerLife = 0;
            public TimeSince GetTimerLife => timerLife;
            private bool canWaterDamage => farm.Settings.Controller.CanWaterDamage;
            private bool canMoveIsDepth => farm.Settings.Controller.CanMoveIsDepth;
            private bool canRouteIsDepth => farm.Settings.Controller.CanRouteIsDepth;
            private float tickUpdate => farm?.Settings?.Controller.TickUpdateController ?? -1f;
            private float setSpeed => 0.5f;
            private float checkDistancePath => 2f;
            public bool Pause
            {
                get => pathController.IsPause;
                set
                {
                    if (value)
                    {
                        pathController.Pause();
                        navigator?.Stop();
                    }
                    else
                    {
                        if (IsSleeping) Sleeping(false);
                        pathController.Resume();
                        // navigator?.Resume();
                    }
                }
            }
            public bool IsMoving => navigator?.Moving ?? false;
            public PlayerInventory Inventory => frankenstein?.inventory;
            private Sphere sphere;

            #region UnityCallbacks
            protected override void Awake()
            {
                base.Awake();
                frankenstein = owner as FrankensteinPet;
                frankenstein.ApplyPetStatModifiers();
                Brain = gameObject.AddComponent<BrainFarmer>();
                pathController = new();
                Pause = true;
                sphere = new Sphere(ServerPosition, 1f);
                Invoke(() => navigator = frankenstein.Brain.Navigator, 0.5f);
            }
            private void Update()
            {
                if (tickUpdate == 0) TickUpdate();
            }
            #endregion

            #region Methods
            private void TickUpdate()
            {
                if (IsInit)
                {
                    if (!Pause && pathController.HasPath)
                    {
                        UpdateDetected();
                        UpdatePath();
                    }
                    else
                    {
                        timerNotVelocity = 0;
                        timerWarp = 0;
                    }
                }
            }
            private void UpdateDetected()
            {
                if(velocity != 0f) timerNotVelocity = 0;
                sphere.position = ServerPosition;
                frankenstein.SetAimDirection(pathController.Current - ServerPosition);
                distanceFarmerToPathFromCurrentPoint = owner.Distance(pathController.Current);
            }
            private void UpdatePath()
            {
                if (pathController.IsEndPathFarmer && sphere.Contains(pathController.CurrentFarmer))
                {
                    Pause = true;
                    OnCurrentFinish();
                    return;
                }
                UpdateRoutePath();
            }
            private void UpdateRoutePath()
            {
                if (!canMoveIsDepth && owner.WaterFactor() > depth)
                {
                    farm.SendLog($"LogFarmer_BigDepth");
                    Pause = true;
                    Warp(pathController.LastFarmer);
                    onFinished?.Invoke(false);
                    return;
                }
                if (!pathController.IsEndPath)
                {
                    if (sphere.Contains(pathController.Current) || distanceFarmerToPathFromCurrentPoint < checkDistancePath)
                    {
                        pathController.NextPointGeneral();
                        Move(pathController.Current);
                        timerWarp = 0;
                        return;
                    }
                }
                float h = ServerPosition.y,
                h2 = pathController.LastFarmer.y + farm.Settings.Controller.OffsetPointY,
                h3 = pathController.LastFarmer.y - farm.Settings.Controller.OffsetPointY,
                h4 = pathController.CurrentFarmer.y + farm.Settings.Controller.OffsetPointY,
                h5 = pathController.CurrentFarmer.y - farm.Settings.Controller.OffsetPointY;
                if ((h > h2 && h > h4) || (h < h3 && h < h5))
                {
                    Warp(pathController.LastFarmer);
                }
                if (sphere.Contains(pathController.CurrentFarmer))
                {
                    pathController.NextPointFarmer();
                    Move(pathController.Current);
                    timerWarp = 0;
                }
                else
                {
                    if (timerWarp < 3f) Warp(Vector3.LerpUnclamped(ServerPosition, pathController.CurrentFarmer, tickUpdate == 0 ? Time.deltaTime : tickUpdate));
                    else
                    {
                        Warp(pathController.CurrentFarmer);
                        timerWarp = 0;
                    }
                }
            }
            private void OnCurrentFinish()
            {
                farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Farmer, DataFarm.StatsGeneral.StatsFarmer.FarmerType.Distance, pathController.Distance);
                onFinished?.Invoke(true);
            }
            public override void Init(FarmManager farmManager)
            {
                farm = farmManager;
                Brain.Init(farm);
                if (tickUpdate > 0f) InvokeRepeating(TickUpdate, tickUpdate, tickUpdate);
            }
            public void Sleeping(bool sleep) => frankenstein.SetPlayerFlag(BasePlayer.PlayerFlags.Sleeping, sleep);
            public void SetDestination(Vector3 point, UnityAction<bool> onFinished)
            {
                if (!IsInit) return;
                Pause = true;
                startPoint = pathController.HasPath ? pathController.Current : ServerPosition;
                endPoint = point;
                if (Vector3.Distance(startPoint, endPoint) <= checkDistancePath) onFinished?.Invoke(true); //farm.NextTick(() => onFinished?.Invoke(true));
                else
                {
                    this.onFinished = onFinished;
                    farm.Navigation.SearchPath(startPoint, endPoint, !canRouteIsDepth, InitPathFarm);
                }
            }
            private void Move(Vector3 point)
            {
                Pause = false;
                navigator?.SetDestination(point, setSpeed);
            }
            private void Warp(Vector3 point) => navigator?.Warp(point);
            private void InitPathFarm(Vector3[] path, Router.Response response)
            {
                #if DebugLog
                    if (response != Router.Response.Completed) Debug.Log($"InitPathFarm response [{response}]]");
                #endif
                switch (response)
                {
                    case Router.Response.Completed:
                        {
                            if (path.Length <= 1)
                            {
                                OnCurrentFinish();
                                return;
                            }
                            pathController.SetPath(path, ServerPosition);
                            Move(pathController.Current);
                            timerNotVelocity = 0;
                            return;
                        }
                    case Router.Response.NotFoundRoute:
                        {
                            farm.SendLog("LogFarmer_NotFoundRouteFarm");
                            goto default;
                        }
                    default:
                        {
                            onFinished?.Invoke(false);
                            break;
                        }
                }
            }
            public static float DistanceHorizontal(Vector3 aimAt, Vector3 aimFrom)
            {
                return (new Vector3(aimAt.x, 0f, aimAt.z) - new Vector3(aimFrom.x, 0f, aimFrom.z)).magnitude;
            }
            public void SetLootToDrop()
            {
                bool isLockedWear = owner.inventory.containerWear.IsLocked();
                if (owner.inventory.containerBelt.IsEmpty() && owner.inventory.containerMain.IsEmpty() && (isLockedWear || owner.inventory.containerWear.IsEmpty())) return;
                var backpack = GameManager.server.CreateEntity("assets/prefabs/misc/item drop/item_drop_backpack.prefab", ServerPosition, Quaternion.identity) as DroppedItemContainer;

                backpack.inventory = new ItemContainer();
                backpack.inventory.ServerInitialize(null, owner.inventory.containerBelt.itemList.Count + owner.inventory.containerMain.itemList.Count + (isLockedWear ? 0 : owner.inventory.containerWear.itemList.Count));
                backpack.inventory.GiveUID();
                if (!isLockedWear)
                {
                    if (owner.inventory.containerWear.GetSlot(ItemContainer.BackpackSlotIndex) is Item item && item.IsBackpack() && item.contents != null && !item.contents.IsEmpty())
                    {
                        item.Drop(owner.GetDropPosition(), owner.GetDropVelocity());
                    }
                    owner.inventory.containerWear.MoveAllItems(backpack.inventory);
                }
                else owner.inventory.containerWear.Kill();
                owner.inventory.containerBelt.MoveAllItems(backpack.inventory);
                owner.inventory.containerMain.MoveAllItems(backpack.inventory);
                backpack.inventory.SetFlag(ItemContainer.Flag.NoItemInput, true);
                backpack.ResetRemovalTime();
                backpack.EnableSaving(false);
                backpack.Spawn();
                farm.DeadDrop = backpack;
            }
            public void Death()
            {
                SetLootToDrop();
                SendStatsTimerLife();
                farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Farmer, DataFarm.StatsGeneral.StatsFarmer.FarmerType.Dead);
                farm.Data.OnDeadFarmer(owner);
                farm.RespawnFarmer();
            }
            public override float GetWaterDamageScale()
            {
                if (!canWaterDamage) return 0f;
                return base.GetWaterDamageScale();
            }
            public float Depth(Vector3 pos)
            {
                float radius = owner.playerCollider.radius;
                float num = owner.playerCollider.height * 0.5f;
                Vector3 start = pos + owner.playerCollider.transform.rotation * (owner.playerCollider.center - Vector3.up * (num - radius));
                Vector3 end = pos + owner.playerCollider.transform.rotation * (owner.playerCollider.center + Vector3.up * (num - radius));
                WaterLevel.WaterInfo info = WaterLevel.GetWaterInfo(start, end, radius, waves: true, volumes: true, owner);
                return WaterLevel.Factor(in info, start, end, radius);
            }
            public bool IsDepth(Vector3 pos) => farm.Navigation.IsDepth(pos);
            public bool IsDepthFarmer() => owner.WaterFactor() > depth;
            public void SendStatsTimerLife()
            {
                farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Farmer, DataFarm.StatsGeneral.StatsFarmer.FarmerType.Life, timerLife);
            }
