            {
                NONE, Farm, World
            }
            public struct Speed
            {
                private BasePlayer testing;
                public TimeSince TimerStop;
                private Vector3 lastPosition;
                private float speed;

                public Speed(BasePlayer testing) : this()
                {
                    this.testing = testing;
                    lastPosition = testing.ServerPosition;
                }
                public void Update(float timeUpdate)
                {
                    if (!testing)
                    {
                        speed = 0;
                        TimerStop = 0;
                        return;
                    }
                    var pos = testing.ServerPosition;
                    var dist = pos - lastPosition;
                    speed = dist.magnitude / timeUpdate;
                    lastPosition = pos;
                    if (speed != 0) TimerStop = 0;
                }
                public float Get() => speed;
            }
            public partial class PathController
            {
                private Vector3[] _path;
                public Vector3 Current { get; private set; }
                public Vector3 CurrentFarmer { get; private set; }
                public Vector3 Last { get; private set; }
                public Vector3 LastFarmer { get; private set; }
                public int Index { get; private set; }
                public int IndexFarmer { get; private set; }
                public DirectionPath Direction { get; private set; } = DirectionPath.Forward;
                public DirectionPath LastDirection { get; private set; } = DirectionPath.Forward;
                public int Count => _path?.Length ?? 0;
                public bool IsEndPath => (LastDirection == DirectionPath.Forward && Index == Count - 1) || (LastDirection == DirectionPath.Backward && Index == 0);
                public bool IsEndPathFarmer => (LastDirection == DirectionPath.Forward && IndexFarmer == Count - 1) || (LastDirection == DirectionPath.Backward && IndexFarmer == 0);
                public bool IsPause => Direction == DirectionPath.Pause;
                public bool HasPath => (_path?.Length ?? 0) > 0;
                public bool CanWarp => !IsPause && !IsEndPath && ((LastDirection == DirectionPath.Forward && IndexFarmer <= Index) || (LastDirection == DirectionPath.Backward && IndexFarmer >= Index));
                public float Distance => distance;
                private float distance;

                public void Clear(Vector3 position)
                {
                    Pause();
                    Last = Current;
                    LastFarmer = Current;
                    Index = 0;
                    IndexFarmer = 0;
                    _path = new Vector3[0];
                }
                public void SetPath(Vector3[] path, Vector3 position, int index = 0, DirectionPath direction = DirectionPath.Forward)
                {
                    _path = path;
                    Index = index;
                    IndexFarmer = index;
                    Current = _path[index];
                    CurrentFarmer = Current;
                    Last = position;
                    LastFarmer = position;
                    distance = path.Distance();
                    SetDirection(direction);
                }
                public void NextPoint()
                {
                    Last = Current;
                    if (!IsEndPath)
                    {
                        Index += (int)Direction;
                    }
                    Current = _path[Index];
                }
                public void NextPointGeneral()
                {
                    LastFarmer = Current;
                    NextPoint();
                    IndexFarmer = Index;
                    CurrentFarmer = Current;
                }
                public void NextPointFarmer()
                {
                    if ((LastDirection == DirectionPath.Forward && IndexFarmer >= Index) || (LastDirection == DirectionPath.Backward && IndexFarmer <= Index)) return;
                    LastFarmer = CurrentFarmer;
                    if (!IsEndPathFarmer)
                    {
                        IndexFarmer += (int)Direction;
                    }
                    CurrentFarmer = _path[IndexFarmer];
                }
                public Vector3 GetNextPoint()
                {
                    if (!IsEndPath)
                    {
                        return _path[Index + (int)LastDirection];
                    }
                    return _path[Index];
                }
                public Vector3 GetNextFarmerPoint()
                {
                    if (!IsEndPathFarmer)
                    {
                        return _path[IndexFarmer + (int)LastDirection];
                    }
                    return _path[IndexFarmer];
                }
                public void SetCurrentPoint(Vector3 point)
                {
                    Current = point;
                }
                public void Pause()
                {
                    if (Direction != DirectionPath.Pause) SetDirection(DirectionPath.Pause);
                }
                public void Resume()
                {
                    if (Direction == DirectionPath.Pause) SetDirection(LastDirection);
                }
                public void Revers()
                {
                    Resume();
                    if (Direction == DirectionPath.Forward) SetDirection(DirectionPath.Backward);
                    else SetDirection(DirectionPath.Forward);
                }
                private void SetDirection(DirectionPath direction)
                {
                    if (direction != DirectionPath.Pause) LastDirection = Direction = direction;
                    else Direction = direction;
                }
                internal Vector3[] GetPath()
                {
                    return _path;
                }

                public enum DirectionPath
                {
                    Backward = -1, Pause = 0, Forward = 1
                }
            }
            
        }
