            #region МетодыПосадкиСемян из PersonalFermer.cs
            public void PlantGrowableFermer(Item seed)
            {
                if (seed?.amount >= 1 && seed.info?.TryGetComponent<ItemModDeployable>(out var deployable) == true)
                {
                    NPCPlayer bot = farm.Farmer.GetNpc();
                    Construction construction = PrefabAttribute.server.Find<Construction>(deployable.entityPrefab.resourceID);
                    List<Construction.Target> targets = Pool.Get<List<Construction.Target>>();

                    foreach (Socket_Base sock in PrefabAttribute.server.FindAll<Socket_Base>(owner.prefabID)) 
                    {
                        if (!sock.female)
                            continue;

                        Vector3 socketPoint = owner.transform.TransformPoint(sock.worldPosition);
                        Construction.Target target = new Construction.Target();

                        target.entity = owner;
                        target.ray = new Ray(socketPoint + Vector3.up * 1.0f, Vector3.down);
                        target.onTerrain = false;
                        target.position = socketPoint;
                        target.normal = Vector3.up;
                        target.rotation = new Vector3();
                        target.player = bot;
                        target.valid = true;
                        target.socket = sock;
                        // target.inBuildingPrivilege = true;

                        if (!IsFree(construction, target))
                            continue;

                        targets.Add(target);
                    }

                    foreach (Construction.Target target in targets) 
                    {
                        DoBuild(target, construction, deployable, seed, bot);
                        seed.UseItem();
                        
                        if (seed.amount == 0)
                            break;
                    }

                    Pool.FreeUnmanaged(ref targets);
                }
            }
            private bool IsFree(Construction common, Construction.Target target)
            {
                List<Socket_Base> list = Pool.Get<List<Socket_Base>>();
                common.FindMaleSockets(target, list);
                Socket_Base socketBase = list[0];
                Pool.FreeUnmanaged(ref list);
                Construction.Placement placement = socketBase.DoPlacement(target);
                return !target.entity.IsOccupied(target.socket) && socketBase.CheckSocketMods(ref placement);
            }
            private BaseEntity DoBuild(Construction.Target target, Construction component, ItemModDeployable itemModDeployable, Item item, NPCPlayer bot)
            {
                GameObject gameObject = DoPlacement(target, component, bot);

                Debug.Log("Called placement");

                if (gameObject != null)
                {
                    Debug.Log("Entity built");
                    Interface.CallHook("OnEntityBuilt", this, gameObject);
                    BaseEntity baseEntity = GameObjectEx.ToBaseEntity(gameObject);
                    Deployable deployable = itemModDeployable.GetDeployable(baseEntity);
                    if (baseEntity != null && deployable != null)
                    {
                        if (ShouldParent(target.entity, deployable))
                        {
                            if (target.socket is Socket_Specific_Female socket_Specific_Female)
                            {
                                if (socket_Specific_Female.parentToBone)
                                {
                                    baseEntity.SetParent(target.entity, socket_Specific_Female.boneName, worldPositionStays: true);
                                }
                                else
                                {
                                    baseEntity.SetParent(target.entity, worldPositionStays: true);
                                }
                            }
                            else
                            {
                                baseEntity.SetParent(target.entity, worldPositionStays: true);
                            }
                        }

                        if (deployable.placeEffect.isValid)
                        {
                            if ((bool)target.entity && target.socket != null)
                            {
                                Effect.server.Run(deployable.placeEffect.resourcePath, target.entity.transform.TransformPoint(target.socket.worldPosition), target.entity.transform.up);
                            }
                            else
                            {
                                Effect.server.Run(deployable.placeEffect.resourcePath, target.position, target.normal);
                            }
                        }

                        baseEntity.OnDeployed(baseEntity.GetParentEntity(), bot, item);
                    }

                    return baseEntity;
                }

                return null;
            }
            private GameObject DoPlacement(Construction.Target placement, Construction component, NPCPlayer bot)
            {
                BaseEntity baseEntity = component.CreateConstruction(placement, bNeedsValidPlacement: false);
                if (!baseEntity) return null;

                float num = 1f;
                float num2 = 1f;

                PoolableEx.AwakeFromInstantiate(baseEntity.gameObject);

                BaseCombatEntity baseCombatEntity = baseEntity as BaseCombatEntity;
                if ((bool)baseCombatEntity)
                {
                    num2 = baseCombatEntity.startHealth;
                    baseCombatEntity.ResetLifeStateOnSpawn = false;
                    baseCombatEntity.InitializeHealth(num2 * num, baseCombatEntity.StartMaxHealth());
                }

                baseEntity.OnPlaced(bot);
                baseEntity.OwnerID = bot.userID;
                baseEntity.Spawn();

                return baseEntity.gameObject;
            }
            private bool ShouldParent(BaseEntity targetEntity, Deployable deployable)
            {
                if (targetEntity != null && targetEntity.SupportsChildDeployables() && (targetEntity.ForceDeployableSetParent() || (deployable != null && deployable.setSocketParent)))
                {
                    return true;
                }

                return false;
            }
            #endregion

            #region Planting
            public void PlantGrowable(Item seed)
            {
                if (seed?.amount >= 1 && seed.info?.TryGetComponent<ItemModDeployable>(out var deployable) == true)
                {
                    foreach (var socket in socketBaseArray)
                    {
                        if (socket is Socket_Specific_Female && IsSpawnPointFreeSearch(socket.localPosition))
                        {
                            Vector3 vector3 = entity.transform.TransformPoint(socket.localPosition);
                            BaseEntity baseEntity = GameManager.server.CreateEntity(deployable.entityPrefab.resourcePath, vector3, Quaternion.identity, true);
                            baseEntity.SetParent(entity, true, false);
                            baseEntity.Spawn();
                            GrowableEntity growableEntity = baseEntity as GrowableEntity;
                            int id = seed.info.itemid;
                            seed.UseItem();
                            farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Planted, DataFarm.StatsGeneral.StatsPlaned.PlantedType.Seeds, id, 1);
                            return;
                        }
                    }
                }
            }
            #endregion

            public override void Init(FarmManager farmManager)
            {
                base.Init(farmManager);
                socketBaseArray = PrefabAttribute.server.FindAll<Socket_Base>(entity.prefabID);
                Construction construction = PrefabAttribute.server.Find<Construction>(entity.prefabID);

                if (!farm.Data.PlantedFarm.TryGetValue(netId, out data))
                {
                    data = new DataFarm.PlantedData(new DataFarm.UIDataEntity(owner.skinID));
                    farm.Data.PlantedFarm[netId] = data;
                }

                config = farm.Settings.Planters;
                if (data.entityUI.CanDrawStatus) SubscribeStatusFarm();
                UI = new UIProduction.UIProductionContent.UIPlanterSetup(farm.GetOwnerPlayer(), farm, this, instance.UI_ProductionConfig.ContentPanelMenu.SetupProduction.Planted, instance.UI_ProductionConfig.ContentPanelMenu.SetupProduction.SwitchAccessFarmer, farm.GetStartUICommand, FarmManager.LayerUISubPanel, FarmManager.LayerUISubPanel + ".Content", FarmManager.LayerUISubPanel + ".Content");
            }
            public void DoSplash(Item water)
            {
                if (water == null) return;
                int num = entity.DoSplash(water.info, water.amount);
                water.UseItem(num);
                farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Planted, DataFarm.StatsGeneral.StatsPlaned.PlantedType.Water, num);
            }
            public bool CanHarvesting()
            {
                foreach (var child in entity.children)
                {
                    if (child is GrowableEntity growableEntity && CanPick(growableEntity)) return true;
                }
                return false;
            }
            public bool CanWatering()
            {
                if (entity.soilSaturationFraction > 0.5f) return false;
                foreach (var child in entity.children)
                {
                    if (child is GrowableEntity growableEntity && growableEntity.State != PlantProperties.State.Ripe && growableEntity.State != PlantProperties.State.Dying) return true;
                }
                return false;
            }
            private bool CanPick(GrowableEntity growableEntity)
            {
                return growableEntity.State == PlantProperties.State.Ripe || growableEntity.State == PlantProperties.State.Dying;
            }
            public int CountSlots()
            {
                int count = 0;
                foreach (var socket in socketBaseArray)
                {
                    if (socket is Socket_Specific_Female) count++;
                }
                return count;
            }
            public int CountGrowAble()
            {
                int count = 0;
                foreach (var child in entity.children)
                {
                    if (child is GrowableEntity) count++;
                }
                return count;
            }
            private bool IsSpawnPointFreeSearch(Vector3 localPos)
            {
                List<BaseEntity>.Enumerator enumerator = entity.children.GetEnumerator();
                try
                {
                    foreach (var item in entity.children)
                    {
                        if (!(item is GrowableEntity) || Vector3.Distance(item.transform.localPosition, localPos) >= 0.05f)
                        {
                            continue;
                        }
                        return false;
                    }
                    return true;
                }
                finally
                {
                    ((IDisposable)enumerator).Dispose();
                }
            }
            public bool CanTakeClone(GrowableEntity growableEntity)
            {
                if (growableEntity == null || !farm.Data.UISetup.Planters.ClonesEnabled.Contains(growableEntity.SourceItemDef.itemid)) return false;
                if (growableEntity.CanClone())
                {
                    if (growableEntity.Genes.GetNegativeGeneCount() == 0) return true;
                    int num = growableEntity.Genes.GetGeneTypeCount(GrowableGenetics.GeneType.Empty);
                    int num2 = growableEntity.Genes.Genes.Length - growableEntity.Genes.GetPositiveGeneCount();
                    return num == num2 && num <= farm.Data.UISetup.Planters.CountEmptyGenes;
                }
                return false;
            }
            public void TakeClone(GrowableEntity growableEntity)
            {
                if (growableEntity == null || !growableEntity.CanClone())
                {
                    return;
                }

                int num = growableEntity.Properties.BaseCloneCount + growableEntity.Genes.GetGeneTypeCount(GrowableGenetics.GeneType.Yield) / 2;
                if (num > 0)
                {
                    BasePlayer initiator = farm?.Farmer?.GetNpc();
                    Item item = ItemManager.Create(growableEntity.Properties.CloneItem, num, 0uL);
                    item.SetItemOwnership(initiator, ItemOwnershipPhrases.Cloned);
                    GrowableGeneEncoding.EncodeGenesToItem(growableEntity, item);
                    initiator.GiveItem(item, BaseEntity.GiveItemReason.ResourceHarvested);
                    //отправить в статистику
                    farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Planted, DataFarm.StatsGeneral.StatsPlaned.PlantedType.Harvested, item.info.itemid, item.amount);
                    if (growableEntity.Properties.pickEffect.isValid)
                    {
                        Effect.server.Run(growableEntity.Properties.pickEffect.resourcePath, base.transform.position, Vector3.up);
                    }

                    TellPlanter(growableEntity);
                    growableEntity.Die();
                }
            }
            private void TellPlanter(GrowableEntity growableEntity)
            {
                BaseEntity baseEntity = growableEntity.GetParentEntity();
                if (baseEntity != null && baseEntity is PlanterBox planterBox)
                {
                    planterBox.OnPlantRemoved(growableEntity, null);
                }
            }
            public bool HasTakeClones()
            {
                foreach (var child in entity.children)
                {
                    if (child is GrowableEntity growableEntity && CanTakeClone(growableEntity)) return true;
                }
                return false;
            }
            public override void SubscribeStatusFarm()
            {
                farm.SubscribeStatusFarmer(DrawStatus);
            }
            public override void UnSubscribeStatusFarm()
            {
                farm.UnSubscribeStatusFarmer(DrawStatus);
            }
            protected override void DrawStatus(BasePlayer player)
            {
                player?.SendConsoleCommand("ddraw.text", farm.UpdateStatus, Color.yellow, ServerPosition + entity.bounds.center, GetNameUI(player.UserIDString));
            }
            public bool CanSeedUsed(ItemDefinition seedDef) => data.CanSeedUsed(seedDef);
            public void AddSeed(int itemID) => data.AddSeed(itemID);
            public void RemoveSeed(int itemID) => data.RemoveSeed(itemID);
            public IEnumerable<GrowableEntity> GetGrowableEntitiesRip()
            {
                foreach (var child in entity.children.ToArray())
                {
                    if (child is GrowableEntity growableEntity && CanPick(growableEntity)) yield return growableEntity;
                }
            }
            public IEnumerable<GrowableEntity> GetTakeClones()
            {
                foreach (var child in entity.children.ToArray())
                {
                    if (child is GrowableEntity growableEntity && CanTakeClone(growableEntity)) yield return growableEntity;
                }
            }
            internal void SetFertilizers(ItemContainer inventory)
            {
                foreach (Item item in inventory.itemList.ToArray())
                {
                    if (item.info.itemid == idFertilizer)
                    {
                        int amount = item.amount;
                        if (!item.MoveToContainer(Inventory))
                        {
                            amount -= item.amount;
                        }
                        if (amount > 0)
                        {
                            //Отправить в статистику добавленное удобрение на грядку
                            farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Planted, DataFarm.StatsGeneral.StatsPlaned.PlantedType.Fertilizer, amount);
                        }
                    }
                }
            }
            public bool CanSeedAllUsed() => data.CanSeedAllUsed();
            public ItemDefinition GetSeedDef() => data.GetSeedDef(FarmManager.GetFarmAccessEntity(farm.Navigation.Storages));
            public object Copy() => data.Copy();
            public void Paste(object value) => data.Paste(value);
            public bool HasBuffer(object value) => data.HasBuffer(value);
            public bool CanAddFertilizers() => CountGrowAble() != 0 && CountFertilizers == 0;
        }
        public class FertilizerComponent : FarmEntity<Composter>, IFarmComponent
        {
            private IItemContainerEntity container;
            private DataFarm.FertilizerData data;
            public FarmerSetup.EntityFarmSetup config;
            public override string NameUI
            {
                get => data?.NameUI;
                set => data.NameUI = value;
            }
            public bool CanDrawStatus
            {
                get => data.entityUI.CanDrawStatus;
                set
                {
                    data.entityUI.CanDrawStatus = value;
                    if (value) SubscribeStatusFarm();
                    else UnSubscribeStatusFarm();
                }
            }
            public override bool CanAccessFarmer
            {
                get => data.entityUI.CanAccessFarmer;
                set => data.entityUI.CanAccessFarmer = value;
            }
            public override ItemContainer Inventory => container?.inventory;

            public ItemDefinition FertilizerDef => entity?.FertilizerDef;


            #region UnityCallbacks
            protected override void Awake()
            {
                base.Awake();
                container = entity;
            }

            protected override void OnDestroy()
            {
                base.OnDestroy();

                if (!IsValid)
                {
                    farm?.Data?.FertilizersFarm?.Remove(netId);
                    farm?.Navigation?.Fertilizers?.Remove(this);
                }
                else container.inventory.canAcceptItem = entity.InventoryItemFilter;
            }

            #endregion
            public override void Init(FarmManager farmManager)
            {
                base.Init(farmManager);

                if (!farm.Data.FertilizersFarm.TryGetValue(netId, out data))
                {
                    data = new DataFarm.FertilizerData(new DataFarm.UIDataEntity(owner.skinID));
                    farm.Data.FertilizersFarm[netId] = data;
                }

                config = farm.Settings.Fertilizer;
                if (data.entityUI.CanDrawStatus) SubscribeStatusFarm();
                container.inventory.canAcceptItem = Filter;
                UI = new UIProduction.UIProductionContent.UIFertilizerSetup(farm.GetOwnerPlayer(), farm, this, instance.UI_ProductionConfig.ContentPanelMenu.SetupProduction.Fertilizer, instance.UI_ProductionConfig.ContentPanelMenu.SetupProduction.SwitchAccessFarmer, farm.GetStartUICommand, FarmManager.LayerUISubPanel, FarmManager.LayerUISubPanel + ".Content", FarmManager.LayerUISubPanel + ".Content");
            }

            public override void SubscribeStatusFarm()
            {
                farm.SubscribeStatusFarmer(DrawStatus);
            }

            public override void UnSubscribeStatusFarm()
            {
                farm.UnSubscribeStatusFarmer(DrawStatus);
            }

            protected override void DrawStatus(BasePlayer player)
            {
                player?.SendConsoleCommand("ddraw.text", farm.UpdateStatus, Color.yellow, ServerPosition + entity.bounds.center, GetNameUI(player.UserIDString));
            }

            internal bool HasFertilizer() => Inventory?.HasItem(FertilizerDef) == true;

            public bool Filter(Item item, int slot)
            {
                if (item == null || FertilizerDef == null)
                {
                    return false;
                }
                if (slot == 0 && item.info.itemid != FertilizerDef.itemid)
                {
                    return false;
                }
                if (item.info.GetComponent<ItemModCompostable>() != null || entity.ItemIsFertilizer(item))
                {
                    return true;
                }
                return false;
            }

            internal bool IsFull()
            {
                return Inventory.IsFull() ? true : Inventory.GetSlot(0) == null && Inventory.itemList.Count == Inventory.capacity - 1;
            }

            internal void MoveAllItems(ItemContainer inventory)
            {
                foreach (Item item in inventory.itemList.ToArray())
                {
                    if (farm.CanComposter(item))
                    {
                        int amount = item.amount;
                        if (!item.MoveToContainer(Inventory))
                        {
                            amount -= item.amount;
                        }
                        if (amount > 0)
                        {
                            //Отправить в статистику добавленный предмет в компостер
                            farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.Composter, item.info.itemid, amount);
                        }
                    }
                }
            }

        }
        public class ChickenCoopComponent : FarmEntity<ChickenCoop>, IWaterConsumer
        {
            private IItemContainerEntity container;
            private DataFarm.ChickenCoopData data;
            public FarmerSetup.EntityFarmSetup config;
            public override string NameUI
            {
                get => data?.NameUI;
                set => data.NameUI = value;
            }
            public bool CanDrawStatus
            {
