                    else UnSubscribeStatusFarm();
                }
            }
            public override bool CanAccessFarmer
            {
                get => data.entityUI.CanAccessFarmer;
                set => data.entityUI.CanAccessFarmer = value;
            }
            public override ItemContainer Inventory => container?.inventory;

            public int MaxWater => Inventory.maxStackSize;

            public int AmountWater => entity.CurrentWaterItem?.amount ?? 0;

            public int AvailableWaterCapacity => MaxWater - AmountWater;

            public bool HasFood => Inventory.GetSlot(ChickenCoop.FoodSlot) is Item food && food.amount > 0;

            public bool HasEgg => Inventory.GetSlot(ChickenCoop.FoodProductionSlot) is Item egg && egg.amount > 0;

            public bool CanHatching => !entity.HasFlag(ChickenCoop.Full) && !entity.HasFlag(ChickenCoop.Hatching);

            #region UnityCallbacks
            protected override void Awake()
            {
                base.Awake();
                container = entity;
            }

            protected override void OnDestroy()
            {
                base.OnDestroy();

                if (!IsValid)
                {
                    farm?.Data?.ChickenCoopFarm?.Remove(netId);
                    farm?.Navigation?.Chickens?.Remove(this);
                }
            }

            #endregion
            public override void Init(FarmManager farmManager)
            {
                base.Init(farmManager);

                if (!farm.Data.ChickenCoopFarm.TryGetValue(netId, out data))
                {
                    data = new DataFarm.ChickenCoopData(new DataFarm.UIDataEntity(owner.skinID));
                    farm.Data.ChickenCoopFarm[netId] = data;
                }

                config = farm.Settings.Fertilizer;
                if (data.entityUI.CanDrawStatus) SubscribeStatusFarm();
                UI = new UIProduction.UIProductionContent.UIChickenCoopSetup(farm.GetOwnerPlayer(), farm, this, instance.UI_ProductionConfig.ContentPanelMenu.SetupProduction.Chicken, instance.UI_ProductionConfig.ContentPanelMenu.SetupProduction.SwitchAccessFarmer, farm.GetStartUICommand, FarmManager.LayerUISubPanel, FarmManager.LayerUISubPanel + ".Content", FarmManager.LayerUISubPanel + ".Content");
            }
            public bool IsChickenLove(float love)
            {
                foreach (var animal in entity.Animals.ToArray())
                {
                    if (animal.SpawnedAnimal.TryGet(true, out var chicken) && chicken.AnimalLove < love) return true;
                }
                return false;
            }
            public bool HasChickens()
            {
                foreach (var animal in entity.Animals.ToArray())
                {
                    if (animal.SpawnedAnimal.IsValid(true)) return true;
                }
                return false;
            }
            public void PettedChicken(FarmableAnimal chicken)
            {
                if (!chicken.HasFlag(BaseEntity.Flags.Reserved1) && !chicken.HasFlag(BaseEntity.Flags.Reserved3) && !farm.Farmer.GetNpc().InGesture)
                {
                    chicken.SendMessage("ServerPetChicken", new BaseEntity.RPCMessage() { player = farm.Farmer.GetNpc() });
                }
            }
            public override void SubscribeStatusFarm()
            {
                farm.SubscribeStatusFarmer(DrawStatus);
            }

            public override void UnSubscribeStatusFarm()
            {
                farm.UnSubscribeStatusFarmer(DrawStatus);
            }

            protected override void DrawStatus(BasePlayer player)
            {
                player?.SendConsoleCommand("ddraw.text", farm.UpdateStatus, Color.yellow, ServerPosition + entity.bounds.center, GetNameUI(player.UserIDString));
            }

            public bool CanFood()
            {
                return HasChickens() && !HasFood;
            }
            public bool CanWatering()
            {
                return HasChickens() && AmountWater < MaxWater * 0.5f;
            }

            public void DoSplash(Item water)
            {
                if (water == null) return;
                int amount = Mathf.Min(water.amount, AvailableWaterCapacity);
                if (amount < water.amount)
                {
                    Item _water = ItemManager.Create(water.info, amount);
                    if (_water.MoveToContainer(Inventory, ChickenCoop.WaterSlot))
                    {
                        water.UseItem(amount);
                    }
                    else _water.Remove();
                }
                else water.MoveToContainer(Inventory, ChickenCoop.WaterSlot);
                if (amount > 0) farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.ChickenCoop, DataFarm.StatsGeneral.StatsChickenCoop.ChickenCoopType.WaterAdd, amount);
            }

            internal void FoodChickens(Item item)
            {
                if (item == null) return;
                int amount = item.amount;
                if (!item.MoveToContainer(Inventory, ChickenCoop.FoodSlot))
                {
                    amount -= item.amount;
                }
                if (amount > 0) farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.ChickenCoop, DataFarm.StatsGeneral.StatsChickenCoop.ChickenCoopType.FoodsAdded, item.info.itemid, amount);

            }

            internal bool PickEgg()
            {
                Item egg = Inventory.GetSlot(ChickenCoop.FoodProductionSlot);
                if (egg == null) return false;
                int amount = egg.amount;
                if (!egg.MoveToContainer(farm.Farmer.Inventory.containerMain))
                {
                    amount -= egg.amount;
                }
                if (amount > 0) farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.ChickenCoop, DataFarm.StatsGeneral.StatsChickenCoop.ChickenCoopType.EggsCollected, amount);
                return amount > 0;
            }

            internal ItemDefinition GetItemDefEgg()
            {
                return entity.ChickenPrefab.GetEntity() is FarmableAnimal animal ? animal.ItemToCreate : null;
            }

            internal void EggHatching(Item egg)
            {
                if (egg != null)
                {
                    Item _egg = ItemManager.Create(egg.info);
                    if (_egg.MoveToContainer(Inventory, ChickenCoop.EggInsertSlot))
                    {
                        egg.UseItem(1);
                        SubmitEggForHatching();
                        farm.Data.AddStats(DataFarm.StatsGeneral.StatsType.ChickenCoop, DataFarm.StatsGeneral.StatsChickenCoop.ChickenCoopType.EggsAdd, 1);
                    }
                    else _egg.Remove();
                }
            }
            private void SubmitEggForHatching()
            {
                if (entity.HasFlag(BaseEntity.Flags.Reserved3) || entity.HasFlag(BaseEntity.Flags.Reserved1))
                {
                    return;
                }

                Item slot = Inventory.GetSlot(0);
                if (slot != null && slot.info.shortname == "egg")
                {
                    slot.UseItem();
                    entity.Animals.Add(new ChickenCoop.AnimalStatus
                    {
                        TimeUntilHatch = entity.ChickenHatchTimeMinutes * 60f
                    });
                    entity.SetFlag(BaseEntity.Flags.Reserved1, b: true);
                    entity.SetFlag(BaseEntity.Flags.Reserved3, entity.Animals.Count >= entity.MaxChickens);
                    if (!entity.IsInvoking("CheckEggHatchState"))
                    {
                        entity.InvokeRepeating("CheckEggHatchState", 10f, 10f);
                    }

                    entity.SendNetworkUpdate();
                }
            }

        }
