        #region OwnerComponents
        public abstract class FarmEntity<T> : PluginEntityFarmComponent, IFarmEntity where T : BaseCombatEntity
        {
            public T entity;
            public abstract string NameUI { get; set; }
            public abstract bool CanAccessFarmer { get; set; }
