        public class Debug
        {
            public static void Log(string message, params object[] args) => LogMessage(nameof(PersonalFarmer), TypeDebug.Log, message, args);
            public static void LogError(string message, params object[] args) => LogMessage(nameof(PersonalFarmer), TypeDebug.LogError, message, args);
            public static void LogWarning(string message, params object[] args) => LogMessage(nameof(PersonalFarmer), TypeDebug.LogWarning, message, args);
            public static void LogTest(string message, params object[] args) => LogMessage(nameof(PersonalFarmer), TypeDebug.Test, message, args);
            public static void LogTest<T>(string message, params object[] args) => LogMessage(nameof(PersonalFarmer) + "." + typeof(T).FullName, TypeDebug.Test, message, args);

            private static void LogMessage(string namePlugin, TypeDebug typeDebug, string message, params object[] args)
            {
                switch (typeDebug)
                {
                    case TypeDebug.Log: UnityEngine.Debug.Log($"[{namePlugin}] Log: " + string.Format(message, args)); break;
                    case TypeDebug.LogError: UnityEngine.Debug.LogError($"[{namePlugin}] Error: " + string.Format(message, args)); break;
                    case TypeDebug.LogWarning: UnityEngine.Debug.LogWarning($"[{namePlugin}] Warning: " + string.Format(message, args)); break;
                    case TypeDebug.Test: UnityEngine.Debug.LogWarning($"[{namePlugin} Test log]: " + string.Format(message, args)); break;
                }
            }
            private enum TypeDebug
            {
                Log, LogError, LogWarning, Test
            }
        }
        public class BotIdGenerator
        {
            private static HashSet<ulong> _usedIds; // Хранение использованных ID

            public static ulong GenerateBotId(string steamIdOwner, int maxDigits)
            {
                ulong maxValue = (ulong)Math.Pow(10, maxDigits);
                int startIndex = Math.Max(0, steamIdOwner.Length - maxDigits);
                string substring = steamIdOwner.Substring(startIndex);

                substring = substring.TrimStart('0');
                if(substring.Length == 0 || substring == "0") substring = "1";
                while (substring.Length < maxDigits)
                {
                    substring += "0";
                }
                ulong botId = ulong.Parse(substring);

                ulong attempts = 1;
                while (_usedIds.Contains(botId) && attempts < 100)
                {
                    botId = (botId + 1) % maxValue; 
                    if (botId == 0) botId = 1;
                    Debug.LogTest($"Generate: {botId}");

                    substring = botId.ToString();

                    while (substring.Length < maxDigits)
                    {
                        substring += "0";
                    }
                    botId = ulong.Parse(substring);
                    attempts++;
                }


                if (!_usedIds.Contains(botId))
                {
                    _usedIds.Add(botId);
                }

                return botId;
            }
            public static ulong GenerateBotIdOld(string steamIdOwner, int maxDigits)
            {
                using (System.Security.Cryptography.SHA256 sha256 = System.Security.Cryptography.SHA256.Create())
                {
                    // Шаг 1: Хэширование Steam ID
                    byte[] hashBytes = sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(steamIdOwner));

                    // Шаг 2: Извлечение первых 8 байт (64 бита) для преобразования в ulong
                    byte[] ulongBytes = new byte[8];
                    Array.Copy(hashBytes, ulongBytes, 8); // Первые 8 байта
                    ulong maxValue = (ulong)Math.Pow(10, maxDigits);
                    ulong botId = BitConverter.ToUInt64(ulongBytes, 0) % maxValue;

                    // Шаг 4: Проверка уникальности
                    int attempts = 0;
                    while (_usedIds.Contains(botId) && attempts < 100)
                    {
                        botId = (botId + 1) % maxValue;
                        attempts++;
                    }

                    if (!_usedIds.Contains(botId))
                    {
                        _usedIds.Add(botId);
                    }

                    return botId;
                }
            }
            public static void InitPlugin()
            {
                _usedIds = new HashSet<ulong>();
            }
            public static void UnloadPlugin()
            {
                _usedIds = null;
            }

            public static void AddID(ulong farmerId)
            {
                if (!_usedIds.Contains(farmerId))
                {
                    _usedIds.Add(farmerId);
                }
            }
            public static void RemoveID(ulong id) => _usedIds.Remove(id);

        }
        #endregion

        #region SearchRouteBase
        public abstract class GeneralRouter : Router
        {
            private bool canCheckDepth;
            protected Rect currentLimitMap;

            #region Methods
            public void FindPath(bool canCheckDepth, Vector3 start, Vector3 end, UnityAction<Vector3[], Response> pathResponse)
            {
                parent.StopAllCoroutines();
                this.canCheckDepth = canCheckDepth;

                bool startGround = IsGroundPoint(start);
                bool endGround = IsGroundPoint(end);
                if ((startGround && endGround) || (!startGround && !endGround))
                {
                    if (!startGround && !endGround)
                    {
                        parent.StartCoroutine(FindFarmRouteCoroutine(false, start, end, pathResponse));
                    }
                    else
                    {
                        parent.StartCoroutine(FindGroundRouteCoroutine(true, 1f, start, end, pathResponse));
                    }
                }
                else
                {
                    if (!startGround)
                    {
                        parent.StartCoroutine(FindFarmToGroundRouteCoroutine(false, 2f, start, end, false, pathResponse));
                    }
                    else
                    {
                        parent.StartCoroutine(FindFarmToGroundRouteCoroutine(false, 2f, end, start, true, pathResponse));
                    }
                }
            }
            private bool IsGroundPoint(Vector3 point)
            {
                point += Vector3.up * 0.1f;
                if (Physics.Raycast(point, Vector3.down, 100, LayerMask.GetMask("Construction"))) return false;
                else return true;
            }

            /// <summary>
            /// Recovers a path from a list of closed points
            /// </summary>
            /// <param name="endNode">Finish node</param>
            /// <param name="closedList">List of closed nodes</param>
            private void ReconstructPath(Node endNode, Dictionary<Vector3, Node> closedList, List<Vector3> _path)
            {
                while (endNode.HasParent)
                {
                    Vector3 point = endNode.PositionNode;
                    _path.Add(point);
                    if (!closedList.ContainsKey(endNode.ParentPosition)) break;
                    else endNode = closedList[endNode.ParentPosition];
                }
            }

            private float Heuristic(Vector3 current, Vector3 end) => (end - current).magnitude;
            protected virtual bool CheckStarFarmPoint(Vector3 position) => !canCheckDepth || !IsDepth(position);
            protected virtual bool CheckStarGroundPoint(Vector3 position) => (IsBuildingPrivlidge(position) || currentLimitMap.ContainsVector3(position)) && (!canCheckDepth || !IsDepth(position));
            protected virtual bool CheckEndFarmPoint(Vector3 position) => !canCheckDepth || !IsDepth(position);
            protected virtual bool CheckEndGroundPoint(Vector3 position) => (IsBuildingPrivlidge(position) || currentLimitMap.ContainsVector3(position)) && (!canCheckDepth || !IsDepth(position));

            public virtual void Destroy()
            {
                parent.StopAllCoroutines(); 
            }
            private bool IsEnd(Node currentNode, Node end, bool canObstacle, float step, bool canCheckZone)
            {
                if (step <= 0f) return currentNode.PositionNode == end.PositionNode;
                else return Vector3.Distance(currentNode.PositionNode, end.PositionNode) <= step && IsWalkable(currentNode.PositionNode, end.PositionNode, canObstacle, false, canCheckZone);
            }
            protected virtual bool IsWalkableGround(Vector3 current, Vector3 neighbor, bool canObstacle, bool canCheckZone) => (IsBuildingPrivlidge(neighbor) || currentLimitMap.ContainsVector3(neighbor) || !canCheckZone) && (!canCheckDepth || !IsDepth(neighbor));
            protected virtual bool IsWalkableFarm(Vector3 current, Vector3 neighbor, bool canObstacle) => !canCheckDepth || !IsDepth(neighbor);
            #endregion

            #region AbstractMethods
            /// <summary>
            /// Before searching for a route from the event controller, you must set the search parameters; if the router is in the transport controller, you can set it once when creating an instance of the router class
            /// </summary>
            /// <param name="settings">transport settings from the config</param>
            public abstract void CalculateHightGround(ref Vector3 position);
            public abstract bool IsWalkable(Vector3 current, Vector3 neighbor, bool canObstacle, bool isFarmRoute, bool canCheckZone);
            public abstract bool CheckStartPoint(Vector3 position, bool isFarmRoute);
            public abstract bool CheckEndPoint(Vector3 position, bool isFarmRoute);
            /// <summary>
            /// Abstract Method for checking whether a position belongs to a cupboard
            /// </summary>
            /// <param name="position"></param>
            /// <returns>True if the point meets the requirements, false otherwise</returns>
            protected abstract bool IsBuildingPrivlidge(Vector3 position);
            /// <summary>
            /// Abstract Method for checking the depth of a position in a water
            /// </summary>
            /// <param name="position"></param>
            /// <returns>True, if the point meets the requirements, false otherwise</returns>
            protected abstract bool IsDepth(Vector3 position);
            protected abstract bool GetNearestFarmPoint(Vector3 position, out NavigationFarm.FarmPointNode nearestNode, float maxDistance, bool canObstacle);
            protected abstract IEnumerable<NavigationFarm.FarmPointNode> GetGroundPoints(Vector3 position, List<NavigationFarm.FarmPointNode> sortedNodes);
            protected abstract Node CreateFarmNode(Vector3 neighbor, float g, float h, Vector3 parent);
            protected abstract void DrawNode(Node node, float time, float radius, Color color);
            #endregion

            /// <summary>
            /// Coroutine for finding a route around the farm
            /// </summary>
            /// <param name="canObstacle"></param>
            /// <param name="_start"></param>
            /// <param name="_end"></param>
            /// <param name="callbackPath"></param>
            /// <returns></returns>
            private IEnumerator FindFarmRouteCoroutine(bool canObstacle, Vector3 _start, Vector3 _end, UnityAction<Vector3[], Response> callbackPath)
            {
                Response response = Response.Completed;
                Dictionary<Vector3, Node> openList = Pool.Get<Dictionary<Vector3, Node>>();
                Dictionary<Vector3, Node> closedList = Pool.Get<Dictionary<Vector3, Node>>();
                TimeSince timer = 0;
                List<Vector3> path = Pool.Get<List<Vector3>>();

                if (!CheckStartPoint(_start, true))
                {
                    response = Response.NotCheckStartPoint;
                    goto EndCoroutine;
                }
                if (!CheckEndPoint(_end, true))
                {
                    response = Response.NotCheckEndPoint;
                    goto EndCoroutine;
                }
                
                yield return new WaitForFixedUpdate();

                if (!GetNearestFarmPoint(_start, out var startPoint, 10f, true))
                {
                    response = Response.NotNeighborStartPoint;
                    goto EndCoroutine;
                }

                yield return new WaitForFixedUpdate();

                if (!GetNearestFarmPoint(_end, out var endPoint, 10f, true))
                {
                    response = Response.NotNeighborEndPoint;
                    goto EndCoroutine;
                }

                yield return new WaitForFixedUpdate();

                Node start = Pool.Get<Node>().InitFarmNode(startPoint, 0, 0);
                Node end = Pool.Get<Node>().InitFarmNode(endPoint, 0, 0);

                yield return CreateRouteCoroutine(start, end, openList, closedList, canObstacle, 0f, false);

                yield return new WaitForFixedUpdate();

                bool hasPath = end.HasParent;
                if (hasPath)
                {
                    ReconstructPath(end, closedList, path);
                    path.Reverse();
                }
#if DebugLog
                    Debug.Log(RU ? $"Маршрут {(hasPath ? "найден" : "не найден")}, на поиск ушло {timer} секунд." : $"Route {(hasPath ? "found" : "not found")}, search took {timer} seconds.");
#endif
                response = hasPath ? Response.Completed : Response.NotFoundRoute;

            EndCoroutine:
                Vector3[] pathArray = path.ToArray();
                Pool.Free(ref openList, true);
                Pool.Free(ref closedList, true);
                Pool.FreeUnmanaged(ref path);

                yield return new WaitForFixedUpdate();
                callbackPath?.Invoke(pathArray, response);
                yield break;
            }
            private IEnumerator FindGroundRouteCoroutine(bool canObstacle, float step, Vector3 _start, Vector3 _end, UnityAction<Vector3[], Response> callbackPath)
            {
                Response response = Response.Completed;
                Dictionary<Vector3, Node> openList = Pool.Get<Dictionary<Vector3, Node>>();
                Dictionary<Vector3, Node> closedList = Pool.Get<Dictionary<Vector3, Node>>();
                TimeSince timer = 0;
                List<Vector3> path = Pool.Get<List<Vector3>>();

                if (!CheckStartPoint(_start, false))
                {
                    response = Response.NotCheckStartPoint;
                    goto EndCoroutine;
                }
                if (!CheckEndPoint(_end, false))
                {
                    response = Response.NotCheckEndPoint;
                    goto EndCoroutine;
                }
                
                yield return new WaitForFixedUpdate();

                // yield return new WaitForFixedUpdate();
                CalculateHightGround(ref _start);
                CalculateHightGround(ref _end);

                Node start = Pool.Get<Node>().InitMapNode(_start, 0, 0, step);
                Node end = Pool.Get<Node>().InitMapNode(_end, 0, 0, step);

                yield return CreateRouteCoroutine(start, end, openList, closedList, canObstacle, step, true);

                yield return new WaitForFixedUpdate();

                bool hasPath = end.HasParent;
                if (hasPath)
                {
                    ReconstructPath(end, closedList, path);
                    path.Reverse();
                }
#if DebugLog
                    Debug.Log(RU ? $"Маршрут {(hasPath ? "найден" : "не найден")}, на поиск ушло {timer} секунд." : $"Route {(hasPath ? "found" : "not found")}, search took {timer} seconds.");
#endif
                response = hasPath ? Response.Completed : Response.NotFoundRoute;

            EndCoroutine:
                Vector3[] pathArray = path.ToArray();
                Pool.Free(ref openList, true);
                Pool.Free(ref closedList, true);

                yield return new WaitForFixedUpdate();
                callbackPath?.Invoke(pathArray, response);
                yield break;
            }

            private IEnumerator FindFarmToGroundRouteCoroutine(bool canObstacle, float step, Vector3 botPosition, Vector3 finish, bool isReversPath, UnityAction<Vector3[], Response> callbackPath)
            {
                Response response = Response.Completed;
                Dictionary<Vector3, Node> pathFarm = Pool.Get<Dictionary<Vector3, Node>>();
                Dictionary<Vector3, Node> pathGround = Pool.Get<Dictionary<Vector3, Node>>();
                Dictionary<Vector3, Node> pathGround2 = Pool.Get<Dictionary<Vector3, Node>>();
                Dictionary<Vector3, Node> openList = Pool.Get<Dictionary<Vector3, Node>>();
                Dictionary<Vector3, Node> closedList = Pool.Get<Dictionary<Vector3, Node>>();
                Dictionary<Vector3, Node> currentGroundPath = Pool.Get<Dictionary<Vector3, Node>>();
                List<NavigationFarm.FarmPointNode> sorted = Pool.Get<List<NavigationFarm.FarmPointNode>>();
                Node num1 = null, num2 = null, num3 = null;
                TimeSince timer = 0;
                List<Vector3> currentPath = Pool.Get<List<Vector3>>();
                List<Vector3> path = Pool.Get<List<Vector3>>();
                bool hasPath = false;

                if (!CheckStartPoint(botPosition, true))
                {
                    response = Response.NotCheckStartPoint;
                    goto EndCoroutine;
                }
                if (!CheckEndPoint(finish, false))
                {
                    response = Response.NotCheckEndPoint;
                    goto EndCoroutine;
                }

                if (!GetNearestFarmPoint(botPosition, out var startPoint, 10f, true))
                {
                    response = Response.NotNeighborStartPoint;
                    goto EndCoroutine;
                }
                
                yield return new WaitForFixedUpdate();

                CalculateHightGround(ref finish);
                foreach (var nodeFarmPoint in GetGroundPoints(finish, sorted))
                {
                    if(!nodeFarmPoint.HasFlag(NavigationFarm.FarmPointNode.Flag.HasGround)) continue;
                    yield return new WaitForFixedUpdate();

                    openList.GetPoolNodes();
                    closedList.GetPoolNodes();

                    Vector3 pointGroundFarm = nodeFarmPoint.GetGroundPoint();
                    CalculateHightGround(ref pointGroundFarm);
                    // if (!CheckEndPoint(pointGroundFarm, false)) continue;

                    Node start = Pool.Get<Node>().InitMapNode(finish, 0, 0, step);
                    Node end = Pool.Get<Node>().InitMapNode(pointGroundFarm, 0, 0, step);


                    yield return CreateRouteCoroutine(start, end, openList, closedList, true, step, true);

                    yield return new WaitForFixedUpdate();

                    if (end.HasParent)
                    {
                        try
                        {
                            currentGroundPath.GetPoolNodes();
                            foreach (var item in closedList) currentGroundPath.Add(item.Key, item.Value);
                            closedList.Clear();
                            openList.GetPoolNodes();
                        }
                        catch (System.Exception ex)
                        {
                            Debug.LogError($"Test1: {ex.Message}");
                        }

                        Node start3 = Pool.Get<Node>().InitFarmNode(isReversPath ? nodeFarmPoint : startPoint, 0, 0);
                        Node end3 = Pool.Get<Node>().InitFarmNode(isReversPath ? startPoint : nodeFarmPoint, 0, 0);

                        yield return CreateRouteCoroutine(start3, end3, openList, closedList, canObstacle, step, false);

                        yield return new WaitForFixedUpdate();

                        if (end3.HasParent)
                        {
                            try
                            {
                                // if (Vector3.Distance(nodeFarmPoint.GroundPoint, finish) is float distance && distance < goodDistance)
                                // {
                                    num1 = end;
                                    // num2 = end2;
                                    num3 = end3;
                                    pathFarm.GetPoolNodes();
                                    foreach (var item in closedList) pathFarm.Add(item.Key, item.Value);
                                    closedList.Clear();

                                    pathGround.GetPoolNodes();
                                    foreach (var item in currentGroundPath) pathGround.Add(item.Key, item.Value);
                                    currentGroundPath.Clear();
                                    // goodDistance = distance;
                                    hasPath = true;
                                    break;
                                // }
                            }
                            catch (System.Exception ex)
                            {
                                Debug.LogError($"Test2: {ex.Message}");
                            }
                        }
                    }
                }

                if (hasPath)
                {
                    try
                    {
                        if (isReversPath)
                        {
                            ReconstructPath(num3, pathFarm, path);
                            ReconstructPath(num1, pathGround, path);
                            path.Reverse();
                        }
                        else
                        {
                            ReconstructPath(num1, pathGround, currentPath);
                            currentPath.Reverse();
                            path.AddRange(currentPath);
                            currentPath.Clear();
                            ReconstructPath(num3, pathFarm, path);
                            path.Reverse();
                        }
                    }
                    catch (System.Exception ex)
                    {
                        Debug.LogError($"Test3: {ex.Message}");
                    }
#if DebugLog
                    Debug.Log(RU ? $"Маршрут {(hasPath ? "найден" : "не найден")}, на поиск ушло {timer} секунд." : $"Route {(hasPath ? "found" : "not found")}, search took {timer} seconds.");
#endif
                }


            EndCoroutine:
                Vector3[] pathArray = path.ToArray();
                Pool.Free(ref openList, true);
                Pool.Free(ref closedList, true);
                Pool.Free(ref pathFarm, true);
                Pool.Free(ref pathGround, true);
                Pool.Free(ref currentGroundPath, true);
                Pool.FreeUnmanaged(ref sorted);
                Pool.FreeUnmanaged(ref currentPath);
                Pool.FreeUnmanaged(ref path);
                num1 = num2 = num3 = null;

                yield return new WaitForFixedUpdate();
                callbackPath?.Invoke(pathArray, response);
                yield break;
            }

            /// <summary>
            /// Coroutine for general route search between two positions
            /// </summary>
            /// <param name="start"></param>
            /// <param name="end"></param>
            /// <param name="openList"></param>
            /// <param name="closedList"></param>
            /// <param name="canObstacle"></param>
            /// <param name="stepGride"></param>
            /// <returns></returns>
            private IEnumerator CreateRouteCoroutine(Node start, Node end, Dictionary<Vector3, Node> openList, Dictionary<Vector3, Node> closedList, bool canObstacle, float stepGride, bool canCheckZone)
            {
                bool isFarmRoute = start.IsFarmNode;
                if (isFarmRoute) stepGride = 0f;

                start.Update(0, Heuristic(start.PositionNode, end.PositionNode));
                openList.Add(start.PositionNode, start);
                int iterationCount = 0;
                while (openList.Count > 0)
                {
                    iterationCount++;
                    if (canYieldReturn && iterationCount % limitCyclesCreateRoute == 0) yield return new WaitForFixedUpdate();

                    Node currentNode = null;
                    float _f = float.MaxValue;
                    foreach (var item in openList.Values) if (item.f < _f)
                        {
                            _f = item.f;
                            currentNode = item;
                        }

                    openList.Remove(currentNode.PositionNode);
                    closedList.Add(currentNode.PositionNode, currentNode);

                    if (IsEnd(currentNode, end, canObstacle, stepGride, canCheckZone))
                    {
                        if (!isFarmRoute)
                        {
                            end.Update(0, 0, currentNode.PositionNode);
                        }
                        yield break;
                    }

                    List<Vector3> neighbors = currentNode.GetNeighbors();

                    for (int i = 0; i < neighbors.Count; i++)
                    {
                        Vector3 neighbor = neighbors[i];
                        if (!isFarmRoute) CalculateHightGround(ref neighbor);
                        if (closedList.ContainsKey(neighbor) || !IsWalkable(currentNode.PositionNode, neighbor, canObstacle, isFarmRoute, canCheckZone)) continue;

                        float g = currentNode.g + Heuristic(currentNode.PositionNode, neighbor);
                        float h = Heuristic(currentNode.PositionNode, end.PositionNode);
                        float f = g + h;

                        if (openList.TryGetValue(neighbor, out Node existingNode))
                        {
                            if (f < existingNode.f) existingNode.Update(g, h, currentNode.PositionNode);
                        }
                        else
                        {
                            Node node;
                            if (isFarmRoute)
                            {
                                if (end.PositionNode == neighbor)
                                {
                                    node = end;
                                    node.Update(g, h, currentNode.PositionNode);
                                }
                                else node = CreateFarmNode(neighbor, g, h, currentNode.PositionNode);
                            }
                            else node = Pool.Get<Node>().InitMapNode(neighbor, g, h, stepGride, currentNode.PositionNode);
                            if (node != null) openList.Add(neighbor, node);
                        }
                    }
                }
            }

            /// <summary>
            /// Route point node with pool capability
            /// </summary>
            public sealed class Node : Pool.IPooled
            {
                private NavigationFarm.FarmPointNode pointFarm;
                private List<Vector3> neighbors = null;
                public float g; // Cost from start to node
                public float h; // Estimated cost from node to end
                public float f; // Total cost (g + h)

                public Vector3 PositionNode { get; private set; }
                private Vector3? parentPosition { get; set; }
                public bool IsFarmNode => pointFarm != null;
                public bool HasParent => parentPosition.HasValue;
                public Vector3 ParentPosition => parentPosition ?? Vector3.zero;

                public Node InitFarmNode(NavigationFarm.FarmPointNode point, float g, float h, Vector3? parent = null)
                {
                    pointFarm = point;
                    this.g = g;
                    this.h = h;
                    f = g + h;
                    parentPosition = parent;
                    return InitMapNode(point.Position, g, h, 0f, parent);
                }
                public Node InitMapNode(Vector3 point, float g, float h, float step, Vector3? parent = null)
                {
                    neighbors = Pool.Get<List<Vector3>>();
                    PositionNode = point;
                    Update(g, h);
                    parentPosition = parent;
                    InitNeighbors(step);
                    return this;
                }
                public void Update(float g, float h, Vector3 parent)
                {
                    this.g = g;
                    this.h = h;
                    f = g + h;
                    parentPosition = parent;
                }
                public void Update(float g, float h)
                {
                    this.g = g;
                    this.h = h;
                    f = g + h;
                }
                public List<Vector3> GetNeighbors() => neighbors;
                private void InitNeighbors(float step)
                {
                    if (step <= 0) pointFarm?.GetLinks(neighbors);
                    else
                    {
                        for (int x = -1; x <= 1; x++)
                        {
                            for (int z = -1; z <= 1; z++)
                            {
                                if (x == 0 && z == 0) continue;
                                Vector3 neighbor = new Vector3(PositionNode.x + x * step, PositionNode.y, PositionNode.z + z * step);
                                neighbors.Add(neighbor);
                            }
                        }
                    }
                }
                public void EnterPool()
                {
                    pointFarm = null;
                    g = 0;
                    h = 0;
                    f = 0;
                    parentPosition = null;
                    PositionNode = Vector3.zero;
                    Pool.FreeUnmanaged(ref neighbors);
                }

                public void LeavePool()
                {
                }
            }
            
        }
        public abstract class Router
        {
            protected abstract bool canYieldReturn { get; set; }
            protected abstract int limitCyclesCreateRoute { get; set; }
            protected MonoBehaviour parent { get; set; }
            public enum Response
            {
                Completed = 0, NotNeighborStartPoint = 1, NotCheckStartPoint = 2, NotFoundRoute = 3,
                NotCheckEndPoint = 4, NotNeighborEndPoint = 5,
                NotFoundEnterFarmPoint = 6,
            }
            public static void Free<TKey, TVal>(ref Dictionary<TKey, TVal> dict) where TVal : class, Pool.IPooled, new()
            {
                if (dict != null)
                {
                    foreach (var item in dict)
                    {
                        if (item.Value != null)
                        {
                            TVal val = item.Value;
                            Pool.Free(ref val);
                        }
                    }
                    dict.Clear();
                    Pool.Free(ref dict);
                }
            }
            public abstract class BaseNode
            {
                public float g; // Cost from start to node
                public float h; // Estimated cost from node to end
                public float f; // Total cost (g + h)


                public abstract Vector3 position { get; set; }
                public abstract Vector3 parent { get; set; }
            }
        }
        #endregion
    }

