        [Command(CommandUI)]
        private void CMD_UI(Core.Libraries.Covalence.IPlayer user, string command, string[] args)
        {
            if (user.Object is BasePlayer player && args?.Length is int length && length >= 2 && ulong.TryParse(args[0], out ulong targetId) && PluginFarmManagerComponent.TryGetComponent<FarmManager>(targetId, out var farm))
            {
                farm.Invoke(() => farm?.ProcessingCommandUI(player, args.Skip(1)), 0.1f);
            }
        }

        partial class FarmManager
        {
