                UIManager = new OwnerPanel(ownerPlayer, this, instance.UI_OwnerPanel, GetStartUICommand, "Overall", layerUI, layerUI);
                UIManager.AddMenu("UI_Menu_Setup", new UISetup(ownerPlayer, this, instance.UI_SetupConfig, GetStartUICommand, layerUI + "_MENU", layerUI + "_CONTENT", layerUI + "_CONTENT"));
                UIManager.AddMenu("UI_Menu_Storage", new UIStorage(ownerPlayer, this, instance.UI_StorageConfig, GetStartUICommand, layerUI + "_MENU", layerUI + "_CONTENT", layerUI + "_CONTENT"));
