                UIManager.AddMenu("UI_Menu_Logs", new UILogs(ownerPlayer, this, Data.logs, instance.UI_LogsConfig, GetStartUICommand, layerUI + "_MENU", layerUI + "_CONTENT", layerUI + "_CONTENT"));

