            public void OpenButtonUI(BasePlayer player)
            {
                if (player && player.userID == Data.OwnerId) buttonOpenUI?.OpenUI();
            }
            public void CloseButtonUI(BasePlayer player)
            {
                if (player && player.userID == Data.OwnerId)
                {
                    buttonOpenUI?.CloseUI();
                }
            }
            private void CloseUI()
            {
                UIManager?.CloseUI();
                isOpenUI = false;
            }
            public void ProcessingCommandUI(BasePlayer player, params string[] args)
            {
                if (!player && player.userID != Data.OwnerId) return;
                switch (args[0])
                {
                    case "open": isOpenUI = UIManager?.OpenUI() ?? false; return;
                    case "close": CloseUI(); return;
                }
                UIManager?.ClickButton(args);
            }
            private void AddLog(string text)
            {
                DateTime dateTime = DateTime.Now;
                text = dateTime.ToShortDateString() + " " + dateTime.ToLongTimeString() + ": " + text;
                Data.logs.Insert(0, text);
                if (Data.logs.Count > MaxBufferLogs) Data.logs.RemoveAt(MaxBufferLogs);
                if (isOpenUI) UIManager?.ClickButton("update_logs");
                lastAddLog = 0;
            }
