                        public BeehiveInfoUIConfig BeehiveInfo = new();

                        public class BeehiveInfoUIConfig : ImageUIConfig
                        {
                            protected const int order = orderImage + 100;

                            [JsonProperty(RU ? "Панель ядра улья" : "Nucleus panel", Order = order + 10)]
                            public ImageUIConfig NucleusPanel = new();

                            [JsonProperty(RU ? "Содержимое меда" : "Honeycomb content", Order = order + 20)]
                            public ContentItemsUIConfig2 ContentItems = new();

                            public void AddBeehiveInfo(List<CuiElement> list, string parent, string nameLayer, string nameLayerItemNucleus, string nameLayerHoneayCombPanel, string title, string destroyLayer)
                            {
                                AddImageElement(list, parent, nameLayer, destroyLayer);
                                NucleusPanel.AddImageElement(list, nameLayer, nameLayerItemNucleus, nameLayerItemNucleus);
                                ContentItems.AddImageElement(list, nameLayer, nameLayerHoneayCombPanel, nameLayerHoneayCombPanel);
                                ContentItems.ScrollPanel.AddScrollBackgroundElement(list, nameLayerHoneayCombPanel, nameLayerHoneayCombPanel + ".scroll.panel", nameLayerHoneayCombPanel + ".scroll.panel");
                                ContentItems.TitlePanel.AddTextPanelElement(list, nameLayerHoneayCombPanel, nameLayerHoneayCombPanel + ".title.panel", nameLayerHoneayCombPanel + ".title.text", nameLayerHoneayCombPanel + ".title.panel", title);
                            }
                            public void SetNucleus(List<CuiElement> list, int itemId, string nameLayerItemNucleus, string level)
                            {
                                list.Add(new CuiElement
                                {
                                    Parent = nameLayerItemNucleus,
                                    Name = nameLayerItemNucleus + ".element",
                                    DestroyUi = nameLayerItemNucleus + ".element",
                                    Components =
                                        {
                                            FullScreenTransform,
                                            new CuiImageComponent
                                            {
                                                Color = "1 1 1 1",
                                                ItemId = itemId,
                                                SkinId = 0,
                                            }
                                        }
                                });
                                list.Add(new CuiElement
                                {
                                    Parent = nameLayerItemNucleus + ".element",
                                    Name = nameLayerItemNucleus + ".element.level",
                                    DestroyUi = nameLayerItemNucleus + ".element.level",
                                    Components =
                                        {
                                            new CuiRectTransformComponent
                                            {
                                                AnchorMin = "0 0", AnchorMax = "1 0",
                                                OffsetMin = "0 2", OffsetMax = "-2 20"
                                            },
                                            new CuiTextComponent
                                            {
                                                Color = "0.7 0.7 0.7 1",
                                                Text = level,
                                                FontSize = 10,
                                                Align = TextAnchor.LowerCenter,
                                            }
                                        }
                                });
                            }
                            public void SetScrollHoneycombs(List<CuiElement> list, string nameLayerHoneayCombPanel, int countItems, UnityAction<List<CuiElement>, int, string> addElement)
                            {
                                ContentItems.ScrollPanel.AddScrollPanelElement(list, nameLayerHoneayCombPanel + ".scroll.panel", nameLayerHoneayCombPanel + ".scroll", nameLayerHoneayCombPanel + ".scroll", countItems);
                                ContentItems.ScrollPanel.AddContents(list, nameLayerHoneayCombPanel + ".scroll", nameLayerHoneayCombPanel + ".scroll.content.panel", nameLayerHoneayCombPanel + ".scroll.content", countItems, addElement);
                            }
                        }
                    }
