            public class ContentScroll : ImageUIConfig
            {
                protected const int order = orderImage + 100;

                [JsonProperty(RU ? "Статистика фермера" : "Farmer stats", Order = order + 10)]
                public StatsFarmerUI StatsFarmer = new();

                [JsonProperty(RU ? "Статистика посева" : "Planting stats", Order = order + 20)]
                public StatsPlantedUI StatsPlanted = new();

                [JsonProperty(RU ? "Статистика удобрения" : "Fertilizer stats", Order = order + 30)]
                public StatsFertilizerUI StatsComposter = new();

                [JsonProperty(RU ? "Статистика курятника" : "Chicken coop stats", Order = order + 40)]
                public StatsChickenCoopUI StatsChickenCoop = new();

                [JsonProperty(RU ? "Статистика пчеловода" : "Bee hive stats", Order = order + 50)]
                public StatsBeehiveUI StatsBeehive = new();

                [JsonProperty(RU ? "Статистика воды" : "Water stats", Order = order + 55)]
                public StatsWatersUI StatsWaters = new();

                [JsonProperty(RU ? "Статистика собранных ресурсов" : "Collected resources stats", Order = order + 60)]
                public StatsPickupCollectedUI StatsPickupCollected = new();

                [JsonProperty(RU ? "Статистика добытых ресурсов" : "Resources stats", Order = order + 70)]
                public StatsMiningResourcesUI StatsMiningResources = new();

