        public class OwnerPanel : BasePanelUI
        {
            private ScrollMenuUIConfig styleMenu;
            private string currentMenu;
            private int currentIndexMenu = 0;
            public Dictionary<string, ICommandsUIPanel> menu = new();
            public OwnerPanel()
            {
            }

            public OwnerPanel(BasePlayer owner, FarmManager farm, OwnerPanelConfig config, string command, string parentLayer, string nameLayer, string destroyLayer) : base(owner, farm, config, command, parentLayer, nameLayer, destroyLayer)
            {
                config.ManagerWindow.AddImageElement(this, Name, Name + "_panel", Name + "_panel");
                config.ManagerWindow.TitlePanel.AddTextPanelElement(this, Name + "_panel", Name + "_title", Name + "_title_text", Name + "_title", farm.GetLangText("UI_Title"));
                config.ManagerWindow.CloseButton.AddButtonIconElement(this, Name + "_panel", Name + "_close_button", Name + "_close_icon", Name + "_close_button", command + " close", null);
                config.ManagerWindow.PanelContent.AddImageElement(this, Name + "_panel", Name + "_PANEL_CONTENT", Name + "_PANEL_CONTENT");
                config.ManagerWindow.PanelContent.ContentPanelMenu.AddImageElement(this, Name + "_PANEL_CONTENT", Name + "_MENU", null);
                styleMenu = config.ManagerWindow.PanelContent.ScrollMenu;
            }

            public override void AddMenu(string key, ICommandsUIPanel panel)
            {
                menu.Add(key, panel);
            }
            public override void CreateMenu()
            {
                currentMenu = menu.Keys.ElementAt(currentIndexMenu) ?? "";
                currentSubPanelUI = !string.IsNullOrEmpty(currentMenu) ? menu[currentMenu] : null;

                styleMenu.AddImageElement(this, Name + "_PANEL_CONTENT", Name + "_panel_Content_menu", null);
                styleMenu.ScrollPanel.AddScrollBackgroundElement(this, Name + "_panel_Content_menu", Name + "_panel_Content_menu.scroll.Panel", Name + "_panel_Content_menu.scroll.Panel");
                styleMenu.ScrollPanel.AddScrollPanelElement(this, Name + "_panel_Content_menu.scroll.Panel", Name + "_panel_Content_menu.scroll", Name + "_panel_Content_menu.scroll", menu.Count);
                styleMenu.ScrollPanel.AddContents(this, Name + "_panel_Content_menu.scroll", Name + "_panel_Content_menu.scroll.content", Name + "_panel_Content_menu.scroll.content", menu.Count, AddMenuElement);
            }
            private void AddMenuElement(List<CuiElement> list, int index, string parent)
            {
                styleMenu.SwitchButtonText.AddSwitchButtonTextElement(list,
                    parent,
                    Name + "_panel_Content_menu.scroll.content.layer" + index,
                    Name + "_panel_Content_menu.scroll.content.layer.activated" + index,
                    Name + "_panel_Content_menu.scroll.content.button" + index,
                    Name + "_panel_Content_menu.scroll.content.button.text" + index, null,
                    Farm.GetLangText(menu.Keys.ElementAt(index)),
                    commandButton + " " + "menu_button" + " " + index, null);
                styleMenu.SwitchButtonText.AddActivated(list,
                    Name + "_panel_Content_menu.scroll.content.layer.activated" + index,
                    Name + "_panel_Content_menu.scroll.content.layer.active" + index, false);

            }

            public override void SetElementsForOpenUI(List<CuiElement> list)
            {
                base.SetElementsForOpenUI(list);
                styleMenu.SwitchButtonText.AddActivated(list,
                    Name + "_panel_Content_menu.scroll.content.layer.activated" + currentIndexMenu,
                    Name + "_panel_Content_menu.scroll.content.layer.active" + currentIndexMenu, true);
            }
            public override void ClickButton(params string[] args)
            {
                switch (args[0])
                {
                    case "menu_button":
                        {
                            if (args.Length != 2) break;
                            string nameMenu = menu.Keys.ElementAt(int.Parse(args[1])) ?? "";
                            if (nameMenu != currentMenu && menu.TryGetValue(nameMenu, out var target))
                            {
                                currentSubPanelUI?.CloseUI();

                                containerUpdate.Clear();
                                styleMenu.SwitchButtonText.AddActivated(containerUpdate,
                                Name + "_panel_Content_menu.scroll.content.layer.activated" + currentIndexMenu,
                                Name + "_panel_Content_menu.scroll.content.layer.active" + currentIndexMenu, false);

                                currentIndexMenu = int.Parse(args[1]);
                                currentMenu = nameMenu;
                                currentSubPanelUI = target;

                                styleMenu.SwitchButtonText.AddActivated(containerUpdate,
                                Name + "_panel_Content_menu.scroll.content.layer.activated" + currentIndexMenu,
                                Name + "_panel_Content_menu.scroll.content.layer.active" + currentIndexMenu, true);

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);

                                currentSubPanelUI?.OpenUI();
                            }

                            break;
                        }
                    default: break;
                }

                base.ClickButton(args);
            }

        }
        public class UISetup : BasePanelUI
        {
            private UISetupConfig.UIMenuSetupConfig style;
