                AddMenu("UI_Menu_Setup_Farmer", new UISetupFarmer(owner, farm, config.ContentPanelMenu, command, Name + ".owner_setup.content.background", Name + ".owner_setup.content", Name + ".owner_setup.content"));
                AddMenu("UI_Menu_Setup_Planters", new UISetupPlanters(owner, farm, config.ContentPanelMenu, "UI_ActivateProduction", command, Name + ".owner_setup.content.background", Name + ".owner_setup.content", Name + ".owner_setup.content"));
