                AddMenu("UI_Menu_Setup_Beehives", new UISetupBeehives(owner, farm, config.ContentPanelMenu, "UI_ActivateProduction", command, Name + ".owner_setup.content.background", Name + ".owner_setup.content", Name + ".owner_setup.content"));
            }

