            public override void AddMenu(string key, ICommandsUIPanel panel)
            {
                menu.Add(key, panel);
                switch (key)
                {
                    case "UI_Menu_Setup_General":
                        icons.Add(style.MenuElement.IconGeneralSetup);
                        break;
                    case "UI_Menu_Setup_Farmer":
                        icons.Add(style.MenuElement.IconFarmerSetup);
                        break;
                    case "UI_Menu_Setup_Planters":
                        icons.Add(style.MenuElement.IconPlantersSetup);
                        break;
                    case "UI_Menu_Setup_Fertilizers":
                        icons.Add(style.MenuElement.IconFertilizerSetup);
                        break;
                    case "UI_Menu_Setup_Chickens":
                        icons.Add(style.MenuElement.IconChickenSetup);
                        break;
                    case "UI_Menu_Setup_Beehives":
                        icons.Add(style.MenuElement.IconBeehivesSetup);
                        break;
                }
            }
            public void SetScroll(List<CuiElement> list)
            {
                style.ScrollMenuPanel.AddScrollPanelElement(
                    list, Name + ".scroll.owner_setup.menu.background",
                    Name + ".scroll.owner_setup.menu.panel",
                    Name + ".scroll.owner_setup.menu.panel",
                    menu.Count
                );
                style.ScrollMenuPanel.AddContents(
                    list, Name + ".scroll.owner_setup.menu.panel",
                    Name + ".scroll.owner_setup.menu.content",
                    Name + ".scroll.owner_setup.menu.content.element",
                    menu.Count,
                    AddElementMenu
                );
            }
            public void AddElementMenu(List<CuiElement> list, int indexElement, string parent)
            {
                style.MenuElement.AddSwitchButtonElement(
                    list, parent,
                    Name + ".scroll.owner_setup.menu.element.switch.layer" + indexElement,
                    Name + ".scroll.owner_setup.menu.element.switch.activated" + indexElement,
                    Name + ".scroll.owner_setup.menu.element.switch.button" + indexElement,
                    Name + ".scroll.owner_setup.menu.element.switch.layer" + indexElement,
                    commandButton + " " + "setup_menu_button" + " " + indexElement, null
                );
                icons[indexElement].AddImageAndBackgroundElement(
                    list, Name + ".scroll.owner_setup.menu.element.switch.button" + indexElement,
                    Name + ".scroll.owner_setup.menu.element.switch.icon.background" + indexElement,
                    Name + ".scroll.owner_setup.menu.element.switch.icon" + indexElement,
                    Name + ".scroll.owner_setup.menu.element.switch.icon.background" + indexElement
                );
                style.MenuElement.Name.AddTextPanelElement(
                    list, Name + ".scroll.owner_setup.menu.element.switch.button" + indexElement,
                    Name + ".scroll.owner_setup.menu.element.switch.title" + indexElement,
                    Name + ".scroll.owner_setup.menu.element.switch.title.text" + indexElement,
                    Name + ".scroll.owner_setup.menu.element.switch.title" + indexElement,
                    Farm.GetLangText(menu.Keys.ElementAt(indexElement))
                );
                AddActivated(list, indexElement, currentIndexMenu == indexElement);
            }
            public void AddActivated(List<CuiElement> list, int indexElement, bool isActive)
            {
                style.MenuElement.AddActivated(
                    list, Name + ".scroll.owner_setup.menu.element.switch.activated" + indexElement,
                    Name + ".scroll.owner_setup.menu.element.switch.active" + indexElement,
                    isActive
                );
                if (isActive) currentSubPanelUI = menu.Values.ElementAt(indexElement);
            }
            public override void ClickButton(params string[] args)
            {
                switch (args[0])
                {
                    case "setup_menu_button":
                        {
                            if (args.Length != 2) break;

                            if (int.TryParse(args[1], out int index) && index != currentIndexMenu && index < menu.Count)
                            {
                                currentSubPanelUI?.CloseUI();
                                int lastIndex = currentIndexMenu;
                                currentIndexMenu = index;

                                containerUpdate.Clear();
                                AddActivated(containerUpdate, lastIndex, false);
                                AddActivated(containerUpdate, index, true);

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);

                                currentSubPanelUI = menu.Values.ElementAt(index);
                                currentSubPanelUI?.OpenUI();
                            }

                            break;
                        }
                    default: break;
                }

                base.ClickButton(args);
            }

