                private void UpdateInfoFarmer(BasePlayer player)
                {
                    containerUpdate.Clear();
                    config.InfoFarmer.Text.AddTextElement(
                        containerUpdate, Name + ".info_farmer",
                        Name + ".info_farmer.text",
                        Name + ".info_farmer.text",
                        Farm.Farmer.Brain.GetStatus(player.UserIDString)
                    );
                    CuiHelper.AddUi(player, containerUpdate);
                }
                public override void CloseUI()
                {
                    Farm.UnSubscribeStatusFarmer(UpdateInfoFarmer);
                    base.CloseUI();
                }
                public override void ClickButton(params string[] args)
                {
                    switch (args[0])
                    {
                        case "expiration":
                            {
                                containerUpdate.Clear();
                                if (args.Length > 1 && int.TryParse(args[1], out int value) && value > 0 && value <= 100)
                                {
                                    Farm.Data.UISetup.Farm.PercentSpoiling = value / 100f;
                                }
                                config.Expiration.InputPanel.Input.AddInputElement(
                                    containerUpdate, Name + ".expiration.input.panel",
                                    Name + ".expiration.input",
                                    Name + ".expiration.input",
                                    Farm.Data.UISetup.Farm.PercentSpoiling.ToString("0 %"),
                                    commandButton + " " + "expiration "
                                );
                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "logs_to_chat":
                            {
                                Farm.Data.UISetup.Farm.CanSendLogToChat = !Farm.Data.UISetup.Farm.CanSendLogToChat;
                                if (Farm.Data.UISetup.Farm.CanSendLogToChat) Farm.SubscribeLogs(Farm.ChatMessageOwnerPlayer);
                                else Farm.UnSubscribeLogs(Farm.ChatMessageOwnerPlayer);
                                containerUpdate.Clear();
                                config.SendLogsToChat.Switch.AddActivated(
                                    containerUpdate, Name + ".SendLogsToChat.switch.activated",
                                    Name + ".SendLogsToChat.switch.active",
                                    Farm.Data.UISetup.Farm.CanSendLogToChat
                                );
                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "logs_to_console":
                            {
                                Farm.Data.UISetup.Farm.CanSendLogToConsole = !Farm.Data.UISetup.Farm.CanSendLogToConsole;
                                if (Farm.Data.UISetup.Farm.CanSendLogToConsole) Farm.SubscribeLogs(Farm.ConsoleMessageOwnerPlayer);
                                else Farm.UnSubscribeLogs(Farm.ConsoleMessageOwnerPlayer);
                                containerUpdate.Clear();
                                config.SendLogsToConsole.Switch.AddActivated(
                                    containerUpdate, Name + ".SendLogsToConsole.switch.activated",
                                    Name + ".SendLogsToConsole.switch.active",
                                    Farm.Data.UISetup.Farm.CanSendLogToConsole
                                );
                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "init":
                            {
                                if (Farm.IsNewInitializationRequired && Farm.Farmer)
                                {
                                    CuiHelper.DestroyUi(OwnerPlayer, Name + ".init.button");
                                    Farm.Farmer.Brain.SetStatus(BrainFarmer.StatusFarmer.Initialization);
                                }
                                break;
                            }
                    }
                    base.ClickButton(args);
                }
            }
