                            Farm.Data.UISetup.Farmer.CanPickupCollectibleItems
                        );
                    if (Farm.Settings.Controller.CanMining)
                        config.AllowMineResources.Switch.AddActivated(
                            list, Name + ".AllowMineResources.switch.activated",
                            Name + ".AllowMineResources.switch.active",
                            Farm.Data.UISetup.Farmer.CanMining
                        );
                    if (Farm.Settings.Controller.CanPickupDroppedItems)
                        config.AllowPickUpDroppedItems.Switch.AddActivated(
                            list, Name + ".AllowPickUpDroppedItems.switch.activated",
                            Name + ".AllowPickUpDroppedItems.switch.active",
                            Farm.Data.UISetup.Farmer.CanPickupDroppedItems
                        );
