                public override void ClickButton(params string[] args)
                {
                    switch (args[0])
                    {
                        case "status_farmer":
                            {
                                Farm.Data.UISetup.Farmer.CanVisibleFarmerState = !Farm.Data.UISetup.Farmer.CanVisibleFarmerState;
                                if (Farm.Data.UISetup.Farmer.CanVisibleFarmerState) Farm.Farmer?.Brain?.SubscribeStatusVisible();
                                else Farm.Farmer?.Brain?.UnSubscribeStatusVisible();
                                containerUpdate.Clear();
                                config.ShowFarmerStatus.Switch.AddActivated(
                                    containerUpdate, Name + ".farmer.status.switch.activated",
                                    Name + ".farmer.status.switch.active",
                                    Farm.Data.UISetup.Farmer.CanVisibleFarmerState
                                );
                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "toggle_pickup_collect":
                            {
                                Farm.Data.UISetup.Farmer.CanPickupCollectibleItems = !Farm.Data.UISetup.Farmer.CanPickupCollectibleItems;
                                containerUpdate.Clear();
                                
                                config.AllowCollectResources.Switch.AddActivated(
                                    containerUpdate, Name + ".AllowCollectResources.switch.activated",
                                    Name + ".AllowCollectResources.switch.active",
                                    Farm.Data.UISetup.Farmer.CanPickupCollectibleItems
                                );
                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "toggle_mining_res":
                            {
                                Farm.Data.UISetup.Farmer.CanMining = !Farm.Data.UISetup.Farmer.CanMining;
                                containerUpdate.Clear();

                                config.AllowMineResources.Switch.AddActivated(
                                    containerUpdate, Name + ".AllowMineResources.switch.activated",
                                    Name + ".AllowMineResources.switch.active",
                                    Farm.Data.UISetup.Farmer.CanMining
                                );
                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "toggle_pickup_dropped_items":
                            {
                                Farm.Data.UISetup.Farmer.CanPickupDroppedItems = !Farm.Data.UISetup.Farmer.CanPickupDroppedItems;
                                containerUpdate.Clear();

                                config.AllowPickUpDroppedItems.Switch.AddActivated(
                                    containerUpdate, Name + ".AllowPickUpDroppedItems.switch.activated",
                                    Name + ".AllowPickUpDroppedItems.switch.active",
                                    Farm.Data.UISetup.Farmer.CanPickupDroppedItems
                                );
                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "sorted":
                            {
                                if (!Farm.IsSorted)
                                {
                                    Farm.StartSortedStorages();
                                }
                                break;
                            }
                    }
                    base.ClickButton(args);
                }
            }
