                public override void ClickButton(params string[] args)
                {
                    switch (args[0])
                    {
                        case "switcher_items_to_enabled_seed":
                            {
                                int indexElement = int.Parse(args[1]);
                                ItemDefinition item = instance.seeds.Keys.ElementAt(indexElement);
                                if (!Farm.Data.UISetup.Planters.SeedsEnabled.Contains(item.itemid)) Farm.Data.UISetup.Planters.SeedsEnabled.Add(item.itemid);
                                else Farm.Data.UISetup.Planters.SeedsEnabled.Remove(item.itemid);
                                bool isEnable = Farm.Data.UISetup.Planters.SeedsEnabled.Contains(item.itemid);
                                containerUpdate.Clear();
                                config.SeedsEnabled.ElementItem.AddActivated(
                                    containerUpdate, Name + ".scroll.content.element.activated.layer" + indexElement,
                                    Name + ".scroll.content.element.active" + indexElement,
                                    isEnable
                                );

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "switcher_items_to_enabled_clone":
                            {
                                int indexElement = int.Parse(args[1]);
                                ItemDefinition item = instance.seeds.Values.ElementAt(indexElement);
                                if (!Farm.Data.UISetup.Planters.ClonesEnabled.Contains(item.itemid)) Farm.Data.UISetup.Planters.ClonesEnabled.Add(item.itemid);
                                else Farm.Data.UISetup.Planters.ClonesEnabled.Remove(item.itemid);
                                bool isEnable = Farm.Data.UISetup.Planters.ClonesEnabled.Contains(item.itemid);
                                containerUpdate.Clear();
                                config.ClonesEnabled.ElementItem.AddActivated(
                                    containerUpdate, Name + ".scroll2.content.element.activated.layer" + indexElement,
                                    Name + ".scroll2.content.element.active" + indexElement,
                                    isEnable
                                );

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "switcher_plant_seeds":
                            {
                                Farm.Data.UISetup.Planters.CanPlantSeeds = !Farm.Data.UISetup.Planters.CanPlantSeeds;
                                containerUpdate.Clear();
                                config.SwitcherPlantSeeds.Switch.AddActivated(
                                    containerUpdate, Name + ".element.switch_1.activated",
                                    Name + ".element.switch_1.active",
                                    Farm.Data.UISetup.Planters.CanPlantSeeds
                                );
                                if(Farm.Data.UISetup.Planters.CanPlantSeeds) AddSeedsEnebledPanel(containerUpdate);
                                else CuiHelper.DestroyUi(OwnerPlayer, Name + ".SeedsEnabled.panel");

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "switcher_add_fertilizers":
                            {
                                Farm.Data.UISetup.Planters.CanFertilizers = !Farm.Data.UISetup.Planters.CanFertilizers;
                                containerUpdate.Clear();
                                config.SwitcherAddFertilizers.Switch.AddActivated(
                                    containerUpdate, Name + ".element.switch_2.activated",
                                    Name + ".element.switch_2.active",
                                    Farm.Data.UISetup.Planters.CanFertilizers
                                );
                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "switcher_clone":
                            {
                                Farm.Data.UISetup.Planters.CanClones = !Farm.Data.UISetup.Planters.CanClones;
                                containerUpdate.Clear();
                                config.SwitcherClone.Switch.AddActivated(
                                    containerUpdate, Name + ".element.switch_3.activated",
                                    Name + ".element.switch_3.active",
                                    Farm.Data.UISetup.Planters.CanClones
                                );
                                if(Farm.Data.UISetup.Planters.CanClones) AddClonesEnebledPanel(containerUpdate);
                                else CuiHelper.DestroyUi(OwnerPlayer, Name + ".ClonesEnabled.panel");

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                    }
                    base.ClickButton(args);
                }

            }
