                public override void ClickButton(params string[] args)
                {
                    switch (args[0])
                    {
                        case "switcher_items_to_composter":
                            {
                                int indexElement = int.Parse(args[1]);
                                ItemDefinition item = instance.composterItems[indexElement];
                                if (!Farm.Data.UISetup.Fertilizers.ComposterItems.ContainsKey(item.itemid)) Farm.Data.UISetup.Fertilizers.ComposterItems.Add(item.itemid, false);
                                else Farm.Data.UISetup.Fertilizers.ComposterItems.Remove(item.itemid);
                                bool isEnable = Farm.Data.UISetup.Fertilizers.ComposterItems.ContainsKey(item.itemid);
                                containerUpdate.Clear();
                                config.ItemsToComposter.Element.Switcher.Switch.AddActivated(
                                    containerUpdate, Name + ".items_to_composter.scroll.content.element.switcher.switch.activated" + indexElement,
                                    Name + ".items_to_composter.scroll.content.element.switcher.switch.active" + indexElement,
                                    isEnable
                                );

                                if (isEnable && instance.foodsSpoiling.Contains(item))
                                {
                                    ActivatedSwitchElementExpiration(containerUpdate, indexElement, Farm.Data.UISetup.Fertilizers.ComposterItems[item.itemid]);
                                }
                                else CuiHelper.DestroyUi(OwnerPlayer, Name + ".items_to_composter.scroll.content.element.switcher.count_expiration" + indexElement);

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "switcher_items_to_composter_count_expiration":
                            {
                                int indexElement = int.Parse(args[1]);
                                ItemDefinition item = instance.composterItems[indexElement];
                                if (Farm.Data.UISetup.Fertilizers.ComposterItems.TryGetValue(item.itemid, out bool isEnable))
                                {
                                    containerUpdate.Clear();
                                    isEnable = !isEnable;
                                    Farm.Data.UISetup.Fertilizers.ComposterItems[item.itemid] = isEnable;
                                    config.ItemsToComposter.Element.SwitchCountExpiration.Switch.AddActivated(
                                        containerUpdate, Name + ".items_to_composter.scroll.content.element.switcher.count_expiration.switch.activated" + indexElement,
                                        Name + ".items_to_composter.scroll.content.element.switcher.count_expiration.switch.active" + indexElement,
                                        isEnable
                                    );
                                    CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                }
                                break;
                            }
                    }
                    base.ClickButton(args);
                }


            }
