                    config.FoodToChickens.Element.SwitchCountExpiration.Switch.AddSwitchButtonElement(
                        list, Name + ".chickens.food_to_chickens.scroll.content.element.switcher.count_expiration" + indexElement,
                        Name + ".chickens.food_to_chickens.scroll.content.element.switcher.count_expiration.switch" + indexElement,
                        Name + ".chickens.food_to_chickens.scroll.content.element.switcher.count_expiration.switch.activated" + indexElement,
                        Name + ".chickens.food_to_chickens.scroll.content.element.switcher.count_expiration.switch.button" + indexElement,
                        Name + ".chickens.food_to_chickens.scroll.content.element.switcher.count_expiration.switch" + indexElement,
                        commandButton + " switcher_items_to_chickens_count_expiration " + indexElement, null
                    );
                    config.FoodToChickens.Element.SwitchCountExpiration.Switch.AddActivated(
                        list, Name + ".chickens.food_to_chickens.scroll.content.element.switcher.count_expiration.switch.activated" + indexElement,
                        Name + ".chickens.food_to_chickens.scroll.content.element.switcher.count_expiration.switch.active" + indexElement,
                        active
                    );
                }
                public override void ClickButton(params string[] args)
                {
                    switch (args[0])
                    {
                        case "switch_to_raise_chickens":
                            {
                                containerUpdate.Clear();
                                Farm.Data.UISetup.Chickens.EnableRaiseChickens = !Farm.Data.UISetup.Chickens.EnableRaiseChickens;
                                config.SwitchToRaiseChickens.Switch.AddActivated(
                                    containerUpdate, Name + ".chickens.switch.to.raise.chickens.switch.activated",
                                    Name + ".chickens.switch.to.raise.chickens.switch.active",
                                    Farm.Data.UISetup.Chickens.EnableRaiseChickens
                                );
                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "switcher_items_to_chickens":
                            {
                                int indexElement = int.Parse(args[1]);
                                ItemDefinition item = instance.chickensFood[indexElement];
                                if (!Farm.Data.UISetup.Chickens.FoodItems.ContainsKey(item.itemid)) Farm.Data.UISetup.Chickens.FoodItems.Add(item.itemid, false);
                                else Farm.Data.UISetup.Chickens.FoodItems.Remove(item.itemid);
                                bool isEnable = Farm.Data.UISetup.Chickens.FoodItems.ContainsKey(item.itemid);
                                containerUpdate.Clear();
                                config.FoodToChickens.Element.Switcher.Switch.AddActivated(
                                    containerUpdate, Name + ".chickens.food_to_chickens.scroll.content.element.switcher.switch.activated" + indexElement,
                                    Name + ".chickens.food_to_chickens.scroll.content.element.switcher.switch.active" + indexElement,
                                    isEnable
                                );

                                if (isEnable && instance.foodsSpoiling.Contains(item))
                                {
                                    ActivatedSwitchElementExpiration(containerUpdate, indexElement, Farm.Data.UISetup.Chickens.FoodItems[item.itemid]);
                                }
                                else CuiHelper.DestroyUi(OwnerPlayer, Name + ".chickens.food_to_chickens.scroll.content.element.switcher.count_expiration" + indexElement);

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                break;
                            }
                        case "switcher_items_to_chickens_count_expiration":
                            {
                                int indexElement = int.Parse(args[1]);
                                ItemDefinition item = instance.chickensFood[indexElement];
                                if (Farm.Data.UISetup.Chickens.FoodItems.TryGetValue(item.itemid, out bool isEnable))
                                {
                                    containerUpdate.Clear();
                                    isEnable = !isEnable;
                                    Farm.Data.UISetup.Chickens.FoodItems[item.itemid] = isEnable;
                                    config.FoodToChickens.Element.SwitchCountExpiration.Switch.AddActivated(
                                        containerUpdate, Name + ".chickens.food_to_chickens.scroll.content.element.switcher.count_expiration.switch.activated" + indexElement,
                                        Name + ".chickens.food_to_chickens.scroll.content.element.switcher.count_expiration.switch.active" + indexElement,
                                        isEnable
                                    );
                                    CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                }
                                break;
                            }
                    }
                    base.ClickButton(args);
                }
            }
