        public class UIProduction : BasePanelUI
        {
            private UIProductionConfig.UIMenuProductionsConfig style;
            private string currentMenu;
            private int currentIndexMenu = 0;
            public Dictionary<string, ICommandsUIPanel> menu = new();
            private List<ImageBackgroundUIConfig> icons = new();

            public UIProduction()
            {
            }

            public UIProduction(BasePlayer owner, FarmManager farm, UIProductionConfig config, string command, string parentLayer, string nameLayer, string destroyLayer) : base(owner, farm, config, command, parentLayer, nameLayer, destroyLayer)
            {
                style = config.ScrollMenu;
                style.AddImageElement(this, Name, Name + ".productions.panel", Name + ".productions.panel");
                style.ScrollMenuPanel.AddScrollBackgroundElement(
                    this, Name + ".productions.panel",
                    Name + ".scroll.productions.menu.background",
                    Name + ".scroll.productions.menu.background"
                );
                style.BackgroundContentMenu.AddImageElement(
                    this, Name + ".productions.panel",
                    Name + ".productions.setup.content.background",
                    Name + ".productions.setup.content.background"
                );
                if (farm.Settings.Planters.Enabled()) AddMenu("UI_Menu_Planters", new UIProductionContent(owner, farm, config.ContentPanelMenu, farm.Navigation.Planters, command, Name + ".productions.setup.content.background", Name + ".productions.setup.content", Name + ".productions.setup.content"));
                if (farm.Settings.Fertilizer.Enabled()) AddMenu("UI_Menu_Fertilizers", new UIProductionContent(owner, farm, config.ContentPanelMenu, farm.Navigation.Fertilizers, command, Name + ".productions.setup.content.background", Name + ".productions.setup.content", Name + ".productions.setup.content"));
                if (farm.Settings.Chickens.Enabled()) AddMenu("UI_Menu_Chickens", new UIProductionContent(owner, farm, config.ContentPanelMenu, farm.Navigation.Chickens, command, Name + ".productions.setup.content.background", Name + ".productions.setup.content", Name + ".productions.setup.content"));
                if (farm.Settings.Beehives.Enabled()) AddMenu("UI_Menu_Hives", new UIProductionContent(owner, farm, config.ContentPanelMenu, farm.Navigation.Beehives, command, Name + ".productions.setup.content.background", Name + ".productions.setup.content", Name + ".productions.setup.content"));
                if (farm.Settings.Waters.Enabled()) AddMenu("UI_Menu_Waters", new UIProductionContent(owner, farm, config.ContentPanelMenu, farm.Navigation.Waters, command, Name + ".productions.setup.content.background", Name + ".productions.setup.content", Name + ".productions.setup.content"));
            }

            public override void SetElementsForOpenUI(List<CuiElement> list)
            {
                if (menu.Count > 0)
                {
                    base.SetElementsForOpenUI(list);
                    SetScroll(list);
                }
                else
                {
                    list.Add(substrate);
                    instance.UI_OwnerPanel.ManagerWindow.PanelContent.TextPanelMenuEmpty.AddTextPanelElement(
                        list, Name, Name + ".owner_setup.panel",
                        Name + ".TextEmptyMenu",
                        Name + ".owner_setup.panel",
                        Farm.GetLangText("UI_EmptyMenuProductions")
                    );
                }
            }
            public override void AddMenu(string key, ICommandsUIPanel panel)
            {
                menu.Add(key, panel);
                switch (key)
                {
                    case "UI_Menu_Planters":
                        icons.Add(style.ProductionMenuElement.IconPlanter);
                        break;
                    case "UI_Menu_Fertilizers":
                        icons.Add(style.ProductionMenuElement.IconFertilizer);
                        break;
                    case "UI_Menu_Chickens":
                        icons.Add(style.ProductionMenuElement.IconChicken);
                        break;
                    case "UI_Menu_Hives":
                        icons.Add(style.ProductionMenuElement.IconHives);
                        break;
                    case "UI_Menu_Waters":
                        icons.Add(style.ProductionMenuElement.IconWater);
                        break;
                }
            }
            public void SetScroll(List<CuiElement> list)
            {
                style.ScrollMenuPanel.AddScrollPanelElement(
                    list, Name + ".scroll.productions.menu.background",
                    Name + ".scroll.productions.menu.panel",
                    Name + ".scroll.productions.menu.panel",
                    menu.Count
                );
                style.ScrollMenuPanel.AddContents(
                    list, Name + ".scroll.productions.menu.panel",
                    Name + ".scroll.productions.menu.content",
                    Name + ".scroll.productions.menu.content.element",
                    menu.Count,
                    AddElementMenu
                );
            }
            public void AddElementMenu(List<CuiElement> list, int indexElement, string parent)
            {
                style.ProductionMenuElement.AddSwitchButtonElement(
                    list, parent,
                    Name + ".scroll.productions.menu.element.switch.layer" + indexElement,
                    Name + ".scroll.productions.menu.element.switch.activated" + indexElement,
                    Name + ".scroll.productions.menu.element.switch.button" + indexElement,
                    Name + ".scroll.productions.menu.element.switch.layer" + indexElement,
                    commandButton + " " + "productions_menu_button" + " " + indexElement, null
                );
                icons[indexElement].AddImageAndBackgroundElement(
                    list, Name + ".scroll.productions.menu.element.switch.button" + indexElement,
                    Name + ".scroll.productions.menu.element.switch.icon.background" + indexElement,
                    Name + ".scroll.productions.menu.element.switch.icon" + indexElement,
                    Name + ".scroll.productions.menu.element.switch.icon.background" + indexElement
                );
                style.ProductionMenuElement.Name.AddTextPanelElement(
                    list, Name + ".scroll.productions.menu.element.switch.button" + indexElement,
                    Name + ".scroll.productions.menu.element.switch.title" + indexElement,
                    Name + ".scroll.productions.menu.element.switch.title.text" + indexElement,
                    Name + ".scroll.productions.menu.element.switch.title" + indexElement,
                    Farm.GetLangText(menu.Keys.ElementAt(indexElement))
                );
                AddActivated(list, indexElement, currentIndexMenu == indexElement);
            }
            public void AddActivated(List<CuiElement> list, int indexElement, bool isActive)
            {
                style.ProductionMenuElement.AddActivated(
                    list, Name + ".scroll.productions.menu.element.switch.activated" + indexElement,
                    Name + ".scroll.productions.menu.element.switch.active" + indexElement,
                    isActive
                );
                if (isActive) currentSubPanelUI = menu.Values.ElementAt(indexElement);
            }
            public override void ClickButton(params string[] args)
            {
                switch (args[0])
                {
                    case "productions_menu_button":
                        {
                            if (args.Length != 2) break;

                            if (int.TryParse(args[1], out int index) && index != currentIndexMenu && index < menu.Count)
                            {
                                currentSubPanelUI?.CloseUI();
                                int lastIndex = currentIndexMenu;
                                currentIndexMenu = index;

                                containerUpdate.Clear();
                                AddActivated(containerUpdate, lastIndex, false);
                                AddActivated(containerUpdate, index, true);

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);

                                currentSubPanelUI = menu.Values.ElementAt(index);
                                currentSubPanelUI?.OpenUI();
                            }

                            break;
                        }
                    default: break;
                }

                base.ClickButton(args);
            }

            public class UIProductionContent : UIEntityFarm
