                    private int countPlanterItems => planter.entity.children.Count;


                    public UIPlanterSetup()
                    {
                    }

                    public UIPlanterSetup(BasePlayer owner, FarmManager farm, PlanterComponent planter, UIProductionConfig.UIProductionContentConfig.ProductionSetupUIConfig.PlantedSetupUIConfig config, SwitchAndTitleUIConfig switchAccess, string command, string parentLayer, string nameLayer, string destroyLayer) : base(owner, farm, config.NameProduction, "UI_TitleInputNameObject", switchAccess, config, command, parentLayer, nameLayer, destroyLayer)
                    {
                        this.planter = planter;
                        style = config;

                        // config.SwitcherClone.AddPanelElement(
                        //     this, Name,
                        //     Name + ".clone",
                        //     Name + ".clone",
                        //     farm.GetLangText("UI_TitlePlanterCloneEnabled"),
                        //     commandButton + " " + "planter_clone_button");

                        // AddFullPanelSeedsScrollItems(this);

                        style.SeedsEnabled.AddPanelElement(
                            this, Name,
                            Name + ".seeds",
                            Name + ".seeds",
                            farm.GetLangText("UI_TitlePlanterSeedsEnabled")
                        );

                        style.ContentGrowable.AddPanelElement(
                            this, Name,
                            Name + ".planted_items",
                            Name + ".planted_items",
                            farm.GetLangText("UI_TitlePlanterContentItems")
                        );

                        config.ContentItems.AddScrollBackgroundElement(
                            this, Name,
                            Name + ".container_items.panel",
                            Name + ".container_items.panel"
                        );
                        config.ContentItems.TitlePanel.AddTextPanelElement(
                            this, Name + ".container_items.panel",
                            Name + ".container_items.title.panel",
                            Name + ".container_items.title.text",
                            Name + ".container_items.title.panel",
                            farm.GetLangText("UI_TitlePlanterContentItems")
                        );
