                    public override void SetElementsForOpenUI(List<CuiElement> list)
                    {
                        base.SetElementsForOpenUI(list);
                        // style.SwitcherClone.AddActivated(list, Name + ".clone", planter.IsEnabledUsedClone);
                        // if (!planter.IsEnabledUsedClone) AddFullPanelSeedsScrollItems(list);
                        
                        style.SeedsEnabled.AddScrollPanel(
                            list, Name + ".seeds",
                            instance.seeds.Count,
                            AddContentSeedElement
                        );
                        style.ContentGrowable.AddScrollPanel(
                            list, Name + ".planted_items",
                            countPlanterItems,
                            AddElementPlantedScrollItems
                        );
                        SetScrollItems(list);
                        if (!planter.HasBuffer(Farm.BufferCopyPlantedSeeds))
                        {
                            style.SeedsEnabled.AddButtonCopyPase(list, Name + ".seeds", Name + ".button1", Farm.GetLangText("UI_NameButtonCopy"), commandButton + " planter_seed_copy", true);
                            if (Farm.BufferCopyPlantedSeeds != null) style.SeedsEnabled.AddButtonCopyPase(list, Name + ".seeds", Name + ".button2", Farm.GetLangText("UI_NameButtonPaste"), commandButton + " planter_seed_paste", false);
                        }
                    }
                    private void AddContentSeedElement(List<CuiElement> list, int indexElement, string parent)
                    {
                        ItemDefinition item = instance.seeds.Keys.ElementAt(indexElement);
                        style.SeedsEnabled.AddSwitchElement(list, parent, commandButton + " planter_seed_to_used " + indexElement, item.itemid, 0, planter.CanSeedUsed(item));
                    }
                    private void AddElementPlantedScrollItems(List<CuiElement> list, int index, string parent)
                    {
                        style.ContentGrowable.Element.AddImageElement(
                            list, parent,
                            parent + ".background",
                            parent + ".background"
                        );
                        list.Add(new CuiElement
                        {
                            Parent = parent + ".background",
                            Name = parent + ".item.background",
                            DestroyUi = parent + ".item.background",
                            Components =
                            {
                                style.ContentGrowable.Element.IconPosition.GetCuiTransform(),
                                style.ContentGrowable.BackgroundItem.CreateCuiImageComponent()
                            }
                        });
                        GrowableEntity growable = planter.entity.children[index] as GrowableEntity;
                        ItemDefinition item = growable ? growable.SourceItemDef : null;
                        if (item == null) return;
                        list.Add(new CuiElement
                        {
                            Parent = parent + ".item.background",
                            Name = parent + ".item.icon",
                            DestroyUi = parent + ".item.icon",
                            Components =
                                {
                                    FullScreenTransform,
                                    new CuiImageComponent
                                    {
                                        Color = "1 1 1 1",
                                        ItemId = item.itemid,
                                        SkinId = 0,
                                    }
                                }
                        });
                        style.ContentGrowable.AmountItem.AddTextElement(
                            list, parent + ".item.background",
                            parent + ".item.amount",
                            parent + ".item.amount",
                            "x" + growable.CurrentPickAmount
                        );
                        string text = "";
                        if (growable.Genes?.Genes != null)
                        {
                            for (var i = 0; i < growable.Genes.Genes.Length; i++)
                            {
                                GrowableGene gene = growable.Genes.Genes[i];
                                text += gene.GetColourCodedDisplayCharacter() + (i < growable.Genes.Genes.Length - 1 ? "-" : "");
                            }
                        }
                        text += $"\nStage: {growable.State}";
                        style.ContentGrowable.Element.InfoPanel.AddTextPanelElement(
                            list, parent + ".background",
                            parent + ".info.background",
                            parent + ".info",
                            parent + ".info.background",
                            text
                        );
                    }
                    private void SetScrollItems(List<CuiElement> container)
                    {
                        style.ContentItems.AddScrollPanelElement(
                            container, Name + ".container_items.panel",
                            Name + ".container_items.scroll.panel",
                            Name + ".container_items.scroll.panel",
                            countItems
                        );

                        style.ContentItems.AddContents(
                            container, Name + ".container_items.scroll.panel",
                            Name + ".container_items.scroll.Content.Panel",
                            Name + ".container_items.scroll.Content",
                            countItems, AddElementContentScrollItems
                        );
                    }
                    private void AddElementContentScrollItems(List<CuiElement> list, int index, string parent)
                    {
                        list.Add(new CuiElement
                        {
                            Parent = parent,
                            Name = Name + ".container_items.scroll.Content.element.background" + index,
                            Components =
                                {
                                    FullScreenTransform,
                                    new CuiImageComponent
                                    {
                                        Color = UIColor.gray2(0.6f).GetColor(UIColor.Type.Background),
                                    }
                                }
                        });
                        Item item = planter.Inventory.GetSlot(index);
                        if (item == null) return;
                        list.Add(new CuiElement
                        {
                            Parent = Name + ".container_items.scroll.Content.element.background" + index,
                            Name = Name + ".ContentItems.scroll.content.element.image" + index,
                            DestroyUi = Name + ".ContentItems.scroll.content.element.image" + index,
                            Components =
                                {
                                    FullScreenTransform,
                                    new CuiImageComponent
                                    {
                                        Color = "1 1 1 1",
                                        ItemId = item.info.itemid,
                                        SkinId = item.skin,
                                    }
                                }
                        });
                        if (item.amount > 1)
                        {
                            list.Add(new CuiElement
                            {
                                Parent = Name + ".ContentItems.scroll.content.element.image" + index,
                                Name = Name + ".ContentItems.scroll.content.element.amount" + index,
                                DestroyUi = Name + ".ContentItems.scroll.content.element.amount" + index,
                                Components =
                                    {
                                        new CuiRectTransformComponent
                                        {
                                            AnchorMin = "0 0", AnchorMax = "1 0",
                                            OffsetMin = "0 2", OffsetMax = "-2 20"
                                        },
                                        new CuiTextComponent
                                        {
                                            Color = "0.7 0.7 0.7 1",
                                            Text = "x" + item.amount,
                                            FontSize = 10,
                                            Align = TextAnchor.LowerRight
                                        }
                                    }
                            });
                        }
                    }
                    public override void ClickButton(params string[] args)
                    {
                        switch (args[0])
                        {
                            case "planter_seed_copy":
                                {
                                    Farm.BufferCopyPlantedSeeds = planter.Copy();
                                    CuiHelper.DestroyUi(OwnerPlayer, Name + ".button2");
                                    break;
                                }
                            case "planter_seed_paste":
                                {
                                    planter.Paste(Farm.BufferCopyPlantedSeeds);
                                    containerUpdate.Clear();
                                    style.SeedsEnabled.AddContents(containerUpdate, Name + ".seeds", instance.seeds.Count, AddContentSeedElement);
                                    CuiHelper.DestroyUi(OwnerPlayer, Name + ".button1");
                                    CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                    break;
                                }
                            case "planter_clone_button":
                                {
                                    // planter.IsEnabledUsedClone = !planter.IsEnabledUsedClone;
                                    // containerUpdate.Clear();

                                    // if(!planter.IsEnabledUsedClone) AddFullPanelSeedsScrollItems(containerUpdate);
                                    // else CuiHelper.DestroyUi(OwnerPlayer, Name + ".seeds");

                                    // style.SwitcherClone.AddActivated(containerUpdate, Name + ".clone", planter.IsEnabledUsedClone);
                                    // CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                    break;
                                }
                            case "planter_seed_to_used":
                                {
                                    int indexElement = int.Parse(args[1]);
                                    ItemDefinition item = instance.seeds.Keys.ElementAt(indexElement);
                                    planter.AddSeed(item.itemid);
                                    bool isEnable = planter.CanSeedUsed(item);
                                    
                                    containerUpdate.Clear();
                                    style.SeedsEnabled.AddActivated(containerUpdate, Name + ".seeds", indexElement, isEnable);

                                    if (!planter.HasBuffer(Farm.BufferCopyPlantedSeeds))
                                    {
                                        style.SeedsEnabled.AddButtonCopyPase(containerUpdate, Name + ".seeds", Name + ".button1", Farm.GetLangText("UI_NameButtonCopy"), commandButton + " planter_seed_copy", true);
                                        style.SeedsEnabled.AddButtonCopyPase(containerUpdate, Name + ".seeds", Name + ".button2", Farm.GetLangText("UI_NameButtonPaste"), commandButton + " planter_seed_paste", false);
                                    }
                                    else
                                    {
                                        CuiHelper.DestroyUi(OwnerPlayer, Name + ".button1");
                                        CuiHelper.DestroyUi(OwnerPlayer, Name + ".button2");
                                    }
                                    
                                        
                                    CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                    break;
                                }
                        }
                        base.ClickButton(args);
                    }

                }
