                            container, parent,
                            name + ".pos",
                            name + ".icon",
                            name + ".condition.panel",
                            name + ".condition.current",
                            name + ".amount",
                            style.ContentPanel.Chicken.ChickenScrollElement.IconChicken.CreateImageElement(),
                            chicken.AnimalName, true, chickensCoop.entity.Health(), chickensCoop.entity.MaxHealth()
                        );
                    }
