                {
                    base.SetElementsForOpenUI(list);

                    SetScrollFilter(list);
                    AddActivatedCategoryAll(list, storage.CategoryAll);
                    SetScrollItems(list);
                }

                private void SetScrollFilter(List<CuiElement> container)
                {
                    style.FilterEnter.AddScrollPanelElement(
                        container, Name + ".FilterStorageSetup.panel",
                        Name + ".FilterStorageSetup.scroll.panel",
                        Name + ".FilterStorageSetup.scroll.panel",
                        instance.categoriesAll.Count);

                    style.FilterEnter.AddContents(
                        container, Name + ".FilterStorageSetup.scroll.panel", Name + ".FilterStorageSetup.scroll.Content.Panel",
                        Name + ".FilterStorageSetup.scroll.Content", instance.categoriesAll.Count, AddElementContentScrollFilter);
                }
                private void AddElementContentScrollFilter(List<CuiElement> list, int index, string parent)
                {
                    ItemCategory category = instance.categoriesAll[index];
                    style.FilterEnter.FilterElement.AddImageElement(
                        list, parent,
                        Name + ".FilterStorageSetup.scroll.content.element" + index,
                        Name + ".FilterStorageSetup.scroll.content.element" + index
                    );
                    style.FilterEnter.FilterElement.Switch.AddSwitchButtonElement(
                        list, Name + ".FilterStorageSetup.scroll.content.element" + index,
                        Name + ".FilterStorageSetup.scroll.content.element.switch" + index,
                        Name + ".FilterStorageSetup.scroll.content.element.switch.activated.layer" + index,
                        Name + ".FilterStorageSetup.scroll.content.element.switch.button" + index,
                        Name + ".FilterStorageSetup.scroll.content.element.switch" + index,
                        commandButton + " " + "switch_storage_category " + index, null
                    );
                    AddActivatedCategory(list, index, storage.CategoryAll || storage.ExistCategory(category));
                    style.FilterEnter.FilterElement.NameCategory.AddTextPanelElement(
                        list, Name + ".FilterStorageSetup.scroll.content.element" + index,
                        Name + ".FilterStorageSetup.scroll.content.element.title" + index,
                        Name + ".FilterStorageSetup.scroll.content.element.title.text" + index,
                        Name + ".FilterStorageSetup.scroll.content.element.title" + index,
                        Farm.GetLangText(category.ToString())
                    );
