                private void AddActivatedCategory(List<CuiElement> list, int index, bool active)
                {
                    style.FilterEnter.FilterElement.Switch.AddActivated(list,
                        Name + ".FilterStorageSetup.scroll.content.element.switch.activated.layer" + index,
                        Name + ".FilterStorageSetup.scroll.content.element.switch.activated" + index, active);
                }
                private void AddActivatedCategoryAll(List<CuiElement> list, bool active)
                {
                    style.FilterEnter.FilterElement.Switch.AddActivated(list,
                        Name + ".FilterStorageSetup.scroll.content.element.switch.activated.layer",
                        Name + ".FilterStorageSetup.scroll.content.element.switch.activated", active);
                }
