                {
                    style.ContentItems.AddScrollPanelElement(
                        container, Name + ".ContentItems.panel",
                        Name + ".ContentItems.scroll.panel",
                        Name + ".ContentItems.scroll.panel",
                        storage.Inventory.capacity
                    );

                    style.ContentItems.AddContents(
                        container, Name + ".ContentItems.scroll.panel",
                        Name + ".ContentItems.scroll.Content.Panel",
                        Name + ".ContentItems.scroll.Content",
                        storage.Inventory.capacity, AddElementContentScrollItems
                    );
                }
                private void AddElementContentScrollItems(List<CuiElement> list, int index, string parent)
                {
                    list.Add(new CuiElement
                    {
                        Parent = parent,
                        Name = Name + ".ContentItems.scroll.content.element" + index,
                        Components =
                            {
                                FullScreenTransform,
                                new CuiImageComponent
                                {
                                    Color = UIColor.gray2(0.6f).GetColor(UIColor.Type.Background),
                                }
                            }
                    });
                    Item item = storage.Inventory.GetSlot(index);
                    if (item == null) return;
                    list.Add(new CuiElement
                    {
                        Parent = Name + ".ContentItems.scroll.content.element" + index,
                        Name = Name + ".ContentItems.scroll.content.element.image" + index,
                        DestroyUi = Name + ".ContentItems.scroll.content.element.image" + index,
                        Components =
                            {
                                FullScreenTransform,
                                new CuiImageComponent
                                {
                                    Color = "1 1 1 1",
                                    ItemId = item.info.itemid,
                                    SkinId = item.skin
                                }
                            }
                    });
                    if (item.amount > 1)
                    {
                        style.ContentItems.Amount.AddTextElement(
                            list, Name + ".ContentItems.scroll.content.element" + index,
                            Name + ".ContentItems.scroll.content.element.amount" + index,
                            Name + ".ContentItems.scroll.content.element.amount" + index,
                            "x" + item.amount
                        );
                    }
                }
                public override void ClickButton(params string[] args)
                {
                    switch (args[0])
                    {
                        case "switch_storage_category":
                            {
                                if (args.Length != 2) break;

                                if (int.TryParse(args[1], out int index) && index >= -1 && index < instance.categoriesAll.Count)
                                {
                                    containerUpdate.Clear();
                                    bool all = storage.CategoryAll;
                                    ItemCategory category = ItemCategory.All;
                                    if (index == -1)
                                    {
                                        storage.CategoryAll = true;
                                        all = true;
                                    }
                                    else
                                    {
                                        category = instance.categoriesAll[index];
                                        if (storage.ExistCategory(category))
                                        {
                                            storage.RemoveCategory(category);
                                            all = storage.CategoryAll;
                                        }
                                        else storage.AddCategory(category);
                                    }
                                    if (all) SetScrollFilter(containerUpdate);
                                    else AddActivatedCategory(containerUpdate, index, storage.CategoryAll || storage.ExistCategory(category));
                                    AddActivatedCategoryAll(containerUpdate, storage.CategoryAll);
                                    CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                                }

                                break;
                            }
                        default: break;
                    }

                    base.ClickButton(args);
                }
            }
        }
        public class UIStats : BasePanelUI
        {
            private UIStatsConfig config;
            public UIStats()
