            }

            public UIStats(BasePlayer owner, FarmManager farm, UIStatsConfig config, string command, string parentLayer, string nameLayer, string destroyLayer) : base(owner, farm, config, command, parentLayer, nameLayer, destroyLayer)
            {
                this.config = config;
                config.ScrollPanel.AddScrollBackgroundElement(
                    this, Name,
                    Name + ".stats_filed.background",
                    Name + ".stats_filed.background"
                );
                config.ButtonReset.AddButtonTextIconElement(
                    this, Name,
                    Name + ".stats_filed.button_reset",
