            public override void SetElementsForOpenUI(List<CuiElement> list)
            {
                base.SetElementsForOpenUI(list);

                Farm.Data.Stats.AddScrollUI(list, Name + ".stats_filed.background", GetLangText);

                Farm.Data.Stats.CanUpdateUI = true;
                Farm.Data.Stats.playerUI = OwnerPlayer;
                Farm.SubscribeStatusFarmer(UpdateFarmerState);
