            public override void CloseUI()
            {
                Farm.Data.Stats.CanUpdateUI = false;
                Farm.Data.Stats.playerUI = null;
                Farm.UnSubscribeStatusFarmer(UpdateFarmerState);
                base.CloseUI();
            }
            private void UpdateFarmerState(BasePlayer player)
            {
                string text = Farm.GetLangText("UI_StateFarmerPrint", (Farm.Data.Stats.GetStatsFarmer.TimerLife + Farm.Farmer?.GetTimerLife ?? 0).ToStringTime(), Farm.Data.Stats.GetStatsFarmer.DeadCounter, (Farm.Farmer?.GetTimerLife ?? 0).ToStringTime(), Farm.Data.Stats.GetStatsFarmer.DistanceTraveled.ToString("0.0 m."), Farm.Farmer?.Brain.GetStatus(OwnerPlayer.UserIDString) ?? "");
                Farm.Data.Stats.GetStatsFarmer.Update_UI(OwnerPlayer, text);
            }
            private string GetLangText(string key) => Farm.GetLangText(key);

            public override void ClickButton(params string[] args)
            {
