                {
                    case "ResetStats":
                        {
                            Farm.Farmer.ResetTimerLife();
                            Farm.Data.Stats.Reset();
                            CloseUI();
                            OpenUI();
                            break;
                        }
                }
                base.ClickButton(args);
            }
        }
        public class UILogs : BasePanelUI
        {
            private TextUIConfig styleInfoBuffer;
            private TextUIConfig styleLogs;
            private List<string> logs;
            private int currentStart = 0;
            public UILogs()
            {
            }

            public UILogs(BasePlayer owner, FarmManager farm, List<string> logs, UILogsConfig config, string command, string parentLayer, string nameLayer, string destroyLayer) : base(owner, farm, config, command, parentLayer, nameLayer, destroyLayer)
            {
                this.logs = logs;
                styleInfoBuffer = config.ContentFiledLogs.InfoBuffer.Text;
                styleLogs = config.ContentFiledLogs.SwitchButtons.ViewCurrentValue.Text;
                config.ContentFiledLogs.AddImageElement(this, Name, Name + "_logs_filed", Name + "_logs_filed");
                config.ContentFiledLogs.ButtonClearLogs.AddButtonTextIconElement(this, Name + "_logs_filed",
                                                                                 Name + "_button_clear_logs",
                                                                                 Name + "_button_clear_logs_text",
                                                                                 Name + "_button_clear_logs_icon",
                                                                                 Name + "_button_clear_logs",
                                                                                 farm.GetLangText("UI_ClearLogs"), commandButton + " " + "ClearLogs", null);
                config.ContentFiledLogs.InfoBuffer.AddTextPanelElement(this, Name + "_logs_filed", Name + "_info_buffer", Name + "_info_buffer_text", Name + "_info_buffer", "");
                config.ContentFiledLogs.SwitchButtons.AddSwitchListPanelElement(this, Name + "_logs_filed",
                                                                                Name + "_logs_panel",
                                                                                Name + "_logs_panel_text_panel",
                                                                                Name + "_logs_panel_text",
                                                                                Name + "_logs_panel_previous_button",
                                                                                Name + "_logs_panel_previous_text",
                                                                                Name + "_logs_panel_previous_icon",
                                                                                Name + "_logs_panel_next_button",
                                                                                Name + "_logs_panel_next_text",
                                                                                Name + "_logs_panel_next_icon",
                                                                                Name + "_logs_panel",
                                                                                "▲", "▼", commandButton + " " + "log_previous", commandButton + " " + "log_next", "");
            }

            private string GetLogs()
            {
                if (logs.Count == 0) return "";
                string text = "";
                int max = logs.Count <= currentStart + Farm.MaxShowLogs ? logs.Count : currentStart + Farm.MaxShowLogs;
                for (int i = currentStart; i < max; i++)
                {
                    text += $"{logs[i]}\n";
                }
                return text;
            }
            private string GetInfoBuffer()
            {
                return Farm.GetLangText("UI_InfoBuffer", logs.Count, Farm.MaxBufferLogs, currentStart + 1);
            }
            private void UpdateInfoBuffer(List<CuiElement> list)
            {
                styleInfoBuffer.AddTextElement(list, Name + "_info_buffer", Name + "_info_buffer_text", Name + "_info_buffer_text", GetInfoBuffer());
                styleLogs.AddTextElement(list, Name + "_logs_panel_text_panel", Name + "_logs_panel_text", Name + "_logs_panel_text", GetLogs());
            }
            public override void SetElementsForOpenUI(List<CuiElement> list)
            {
                base.SetElementsForOpenUI(list);
                currentStart = 0;
                UpdateInfoBuffer(list);
            }
            public override void ClickButton(params string[] args)
            {
                switch (args[0])
                {
                    case "update_logs":
                        {
                            containerUpdate.Clear();
                            UpdateInfoBuffer(containerUpdate);
                            CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                            break;
                        }
                    case "log_previous":
                        {
                            if (currentStart > 0) currentStart--;
                            else break;
                            goto case "update_logs";
                        }
                    case "log_next":
                        {
                            if (currentStart < logs.Count - 1) currentStart++;
                            else break;
                            goto case "update_logs";
                        }
                    case "ClearLogs":
                        {
                            currentStart = 0;
                            logs.Clear();
                            goto case "update_logs";
                        }
                }
                base.ClickButton(args);
            }

        }

        public abstract class UIEntityFarm : BasePanelUI
        {
