            protected UIEntityFarm()
            {
            }

            protected UIEntityFarm(BasePlayer owner, FarmManager farm, ImageUIConfig backgroundScroll, ScrollPanelUIConfig panelScroll, ImageUIConfig backgroundParentContent, PanelUIConfig styleSubstrate, string command, string parentLayer, string nameLayer, string destroyLayer) : base(owner, farm, styleSubstrate, command, parentLayer, nameLayer, destroyLayer)
