                );

                backgroundParentContent.AddImageElement(this, Name, FarmManager.LayerUISubPanel, FarmManager.LayerUISubPanel);
            }

            protected abstract IFarmComponent GetEntityFarm(int index);

            public override void SetElementsForOpenUI(List<CuiElement> list)
            {
                if (countElements > 0)
                {
                    base.SetElementsForOpenUI(list);
                    currentIndex = 0;
                    SetScroll(list);
                    currentSubPanelUI = currentEntityFarm?.UI;
                }
                else
                {
                    list.Add(substrate);
                    instance.UI_OwnerPanel.ManagerWindow.PanelContent.TextPanelMenuEmpty.AddTextPanelElement(
                        list, Name, Name + ".Scroll.Storages",
