            private void SetScroll(List<CuiElement> container)
            {
                _styleScroll.AddScrollPanelElement(
                    container, Name + ".Scroll.Storages.Scroll.Panel",
                    Name + ".Scroll.Storages.Scroll.Element",
                    Name + ".Scroll.Storages.Scroll.Element",
                    countElements);

                _styleScroll.AddContents(
                    container, Name + ".Scroll.Storages.Scroll.Element", Name + ".Scroll.Storages.Content.Panel",
                    Name + ".Scroll.Storages.Content", countElements, AddElementContentScroll);
            }
            private void AddElementContentScroll(List<CuiElement> list, int index, string parent)
            {
                var entityFarm = GetEntityFarm(index);
                switchButton.AddSwitchButtonElement(
                    list, parent,
                    Name + ".Scroll.Storages.Content.Storage.layer" + index,
                    Name + ".Scroll.Storages.Content.Storage.activated.layer" + index,
                    Name + ".Scroll.Storages.Content.Storage.Button" + index,
                    Name + ".Scroll.Storages.Content.Storage.layer" + index,
                    commandButton + " " + "storage_use" + " " + index, null);

                #region Icon
                iconPanel.AddImageElement(
                    list, Name + ".Scroll.Storages.Content.Storage.Button" + index,
                    Name + ".Scroll.Storages.Content.IconPoint" + index,
                    Name + ".Scroll.Storages.Content.IconPoint" + index
                );
                if (entityFarm?.ItemDefinitionEntity != null)
                {
                    list.Add(new CuiElement
                    {
                        Parent = Name + ".Scroll.Storages.Content.IconPoint" + index,
                        Name = Name + ".Scroll.Storages.Content.IconPoint.Icon" + index,
                        Components =
                            {
                                FullScreenTransform,
                                new CuiImageComponent
                                {
                                    Color = "1 1 1 1", ItemId = entityFarm.ItemDefinitionEntity.itemid, SkinId = entityFarm.SkinID
                                }
                            }
                    });
                }
                #endregion

                #region NameContainer
                nameEntity.AddTextPanelElement(
                    list, Name + ".Scroll.Storages.Content.Storage.Button" + index,
                    Name + ".Scroll.Storages.Content.NameStorage" + index,
                    Name + ".Scroll.Storages.Content.NameStorage.text" + index,
                    Name + ".Scroll.Storages.Content.NameStorage" + index,
                    entityFarm?.GetNameUI(OwnerPlayer.UserIDString));
                #endregion

                #region ButtonToggleMarker
                markerElement.AddSwitchButtonElement(
                    list, Name + ".Scroll.Storages.Content.Storage.Button" + index,
                    Name + ".Scroll.Storages.Content.button_marker_storage" + index,
                    Name + ".Scroll.Storages.Content.button_marker_storage_activated_layer" + index,
                    Name + ".Scroll.Storages.Content.button_marker_storage_button" + index,
                    Name + ".Scroll.Storages.Content.button_marker_storage" + index,
                    commandButton + " " + "marker_toggle" + " " + index, null);
                markerElement.AddActivated(
                    list, Name + ".Scroll.Storages.Content.button_marker_storage_activated_layer" + index,
                    Name + ".Scroll.Storages.Content.button_marker_storage_activated" + index, entityFarm?.CanDrawStatus == true);
                markerElement.Title.AddTextPanelElement(
                    list, Name + ".Scroll.Storages.Content.button_marker_storage" + index,
                    Name + ".Scroll.Storages.Content.button_marker_storage_text_layer" + index,
                    Name + ".Scroll.Storages.Content.button_marker_storage_text" + index,
                    Name + ".Scroll.Storages.Content.button_marker_storage_text_layer" + index,
                    "Marker"
                );
                #endregion
                AddActivatedElement(list, index);
            }
            private void AddActivatedElement(List<CuiElement> list, int index)
            {
                switchButton.AddActivated(list,
                    Name + ".Scroll.Storages.Content.Storage.activated.layer" + index,
                    Name + ".Scroll.Storages.Content.Storage.activated" + index, currentIndex == index);
            }
            public override void ClickButton(params string[] args)
            {
                switch (args[0])
                {
                    case "update_name_entity":
                        {
                            if (args.Length != 2) break;
                            if (int.TryParse(args[1], out int index) && index >= 0 && index < countElements)
                            {
                                containerUpdate.Clear();
                                nameEntity.Text.AddTextElement(
                                    containerUpdate, Name + ".Scroll.Storages.Content.NameStorage" + index,
                                    Name + ".Scroll.Storages.Content.NameStorage.text" + index,
                                    Name + ".Scroll.Storages.Content.NameStorage.text" + index,
                                    GetEntityFarm(index).GetNameUI(OwnerPlayer.UserIDString)
                                );
                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                            }
                            return;
                        }
                    case "storage_use":
                        {
                            if (args.Length != 2) break;

                            if (int.TryParse(args[1], out int index) && index != currentIndex && index < countElements)
                            {
                                currentSubPanelUI?.CloseUI();
                                int lastIndex = currentIndex;
                                currentIndex = index;

                                containerUpdate.Clear();
                                AddActivatedElement(containerUpdate, lastIndex);
                                AddActivatedElement(containerUpdate, index);

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);

                                currentSubPanelUI = currentEntityFarm?.UI; //new UIStorageContainerSetup(OwnerPlayer, Farm.Navigation.Storages[currentIndexStorage], Farm, styleSetup, commandButton, Name + ".SetupStorage.Panel", Name + ".SetupStorage.Content", Name + ".SetupStorage.Content");
                                currentSubPanelUI?.OpenUI();
                            }

                            break;
                        }
                    case "marker_toggle":
                        {
                            if (args.Length != 2) break;

                            if (int.TryParse(args[1], out int index) && index >= 0 && index < countElements)
                            {
                                var entityFarm = GetEntityFarm(index);
                                entityFarm.CanDrawStatus = !entityFarm.CanDrawStatus;
                                containerUpdate.Clear();
                                markerElement.AddActivated(
                                    containerUpdate, Name + ".Scroll.Storages.Content.button_marker_storage_activated_layer" + index,
                                    Name + ".Scroll.Storages.Content.button_marker_storage_activated" + index, entityFarm.CanDrawStatus
                                );

                                CuiHelper.AddUi(OwnerPlayer, containerUpdate);
                            }

                            break;
                        }
                    default: break;
                }

                base.ClickButton(args);
            }

