    partial class PersonalFarmer//UI Config Helpers
    {
        public static CuiRectTransformComponent FullScreenTransform => new() { AnchorMin = "0 0", AnchorMax = "1 1", OffsetMin = "0 0", OffsetMax = "0 0" };
        public static CuiElement CreateEmptyLayer(string parent, string name, string destroy, CuiRectTransformComponent transform = null) => new()
        {
            Parent = parent,
            Name = name,
            DestroyUi = destroy,
            Components = { transform == null ? FullScreenTransform : transform }
        };

        #region MethodsSaveLoadConfigurationUI
        private const string FolderNameUIConfig = "ReservedUIConfig";
        private const string FolderNameReservedUIConfig = "UIConfig";
        public T LoadDataConfigUI<T>(string nameFile, Func<T> callbackGetDefaultConfig) where T : TransformUIConfig
        {
            T classConfigUI = null;
            bool isLastRu = RU;
            #if DefaultConfigUI
                classConfigUI = callbackGetDefaultConfig?.Invoke()?? null;
                if(classConfigUI == null) Debug.LogError(RU ? $"Не получен дефолтная конфигурация UI[{nameFile}]": $"Not obtained default configuration UI[{nameFile}]");
            #else
                try
                {
                    if(Interface.Oxide.DataFileSystem.ExistsDatafile($"{Name}/{FolderNameReservedUIConfig}/{FolderNameReserveConfig}/lastLangRU"))
                    {
                        isLastRu = Interface.Oxide.DataFileSystem.ReadObject<bool>($"{Name}/{FolderNameReservedUIConfig}/{FolderNameReserveConfig}/lastLangRU")?? RU;
                    }
                    if(Interface.Oxide.DataFileSystem.ExistsDatafile($"{Name}/{FolderNameReservedUIConfig}/{FolderNameReserveConfig}/{nameFile}"))
                    {
                        classConfig = Interface.Oxide.DataFileSystem.ReadObject<T>($"{Name}/{FolderNameReservedUIConfig}/{nameFile}")?? null;
                    }
                    else classConfig = callbackGetDefaultConfig?.Invoke()?? null;
                }
                catch (Exception ex)
                {
                    Debug.LogError($"{ex?.Message}");
                    classConfigUI = null;
                }
            #endif

            if (classConfigUI == null || isLastRu != RU)
            {
                classConfigUI = LoadReserveDataConfigUI(nameFile, callbackGetDefaultConfig);
            }
            if(classConfigUI != null) SaveDataConfigUI(classConfigUI, nameFile);
            return classConfigUI;
        }
        public T LoadReserveDataConfigUI<T>(string nameFile, Func<T> callbackGetDefaultConfig) where T : TransformUIConfig
        {
            T classConfigUI = null;
            try
            {
                if(Interface.Oxide.DataFileSystem.ExistsDatafile($"{Name}/{FolderNameReservedUIConfig}/{FolderNameUIConfig}/{nameFile}"))
                {
                    classConfigUI = JsonConvert.DeserializeObject<T>(Interface.Oxide.DataFileSystem.ReadObject<string>($"{Name}/{FolderNameReservedUIConfig}/{FolderNameUIConfig}/{nameFile}"), settingsSerializer);
                    if(classConfigUI != null)
                    {
                        Debug.LogWarning(RU ? "Данный конфигурации восстановлены из резервной копии" : "The configuration has been restored from the reserve copy");
                        return classConfigUI;
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.LogError($"{ex?.Message}");
            }
            classConfigUI = callbackGetDefaultConfig?.Invoke()?? null;
            if(classConfigUI == null) Debug.LogError(RU ? $"Не получен дефолтная конфигурация UI[{nameFile}]": $"Not obtained default configuration UI[{nameFile}]");
            return classConfigUI;
        }
        public void SaveDataConfigUI<T>(T classConfigUI, string nameFile) where T : TransformUIConfig
        {
            Interface.Oxide.DataFileSystem.WriteObject($"{Name}/{FolderNameReservedUIConfig}/{nameFile}", classConfigUI);
            SaveReserveDataConfigUI(classConfigUI, nameFile);
        }
        public void SaveReserveDataConfigUI<T>(T classConfigUI, string nameFile) where T : TransformUIConfig
        {
            Interface.Oxide.DataFileSystem.WriteObject($"{Name}/{FolderNameReservedUIConfig}/{FolderNameUIConfig}/{nameFile}", JsonConvert.SerializeObject(classConfigUI, Formatting.Indented, settingsSerializer));
            Interface.Oxide.DataFileSystem.WriteObject($"{Name}/{FolderNameReservedUIConfig}/{FolderNameUIConfig}/lastLangRU", RU);
        }
        #endregion

        #region ClassCreateUI
        public abstract class BasePanelUI : List<CuiElement>, ICommandsUIPanel
        {
            [JsonIgnore] public const string Sprite = "assets/content/ui/ui.background.tile.psd";
            [JsonIgnore] public const string Material = "assets/icons/greyout.mat";
            [JsonIgnore] public const string Font_RobotoCondensed_Bold_Default = "RobotoCondensed-Bold.ttf";
            [JsonIgnore] public const string Font_RobotoCondensed_Regular = "RobotoCondensed-Regular.ttf";
            [JsonIgnore] public const string Font_PermanentMarker = "PermanentMarker.ttf";
            [JsonIgnore] public const string Font_DroidSansMono = "DroidSansMono.ttf";
            [JsonIgnore] protected readonly List<CuiElement> containerUpdate = new();
            [JsonIgnore] public BasePlayer OwnerPlayer { get; set; }
            [JsonIgnore] public FarmManager Farm { get; set; }
            [JsonIgnore] protected ICommandsUIPanel currentSubPanelUI = null;
            [JsonIgnore] protected CuiElement substrate;

            public BasePanelUI()
            {

            }
            public BasePanelUI(BasePlayer owner, FarmManager farm, PanelUIConfig styleSubstrate, string command, string parentLayer, string nameLayer, string destroyLayer)
            {
                Farm = farm;
                this.OwnerPlayer = owner;
                commandButton = command;

                substrate = styleSubstrate.CreateImageElement();

                Parent = parentLayer;
                Name = nameLayer;
                DestroyUi = destroyLayer;

                if (styleSubstrate.needsCursor) Components.Add(new CuiNeedsCursorComponent());
                if (styleSubstrate.needsKeyboard) Components.Add(new CuiNeedsKeyboardComponent());
                Add(substrate);
            }

            [JsonIgnore]
            public string Parent
            {
                get => substrate.Parent;
                private set => substrate.Parent = value;
            }
            [JsonIgnore]
            public string Name
            {
                get => substrate.Name;
                set => substrate.Name = value;
            }
            [JsonIgnore]
            public string DestroyUi
            {
                get => substrate.DestroyUi;
                set => substrate.DestroyUi = value;
            }
            [JsonIgnore] protected List<ICuiComponent> Components => substrate.Components;
            [JsonIgnore] public virtual string commandButton { get; private set; }

            public bool OpenUI()
            {
                if(!OwnerPlayer) OwnerPlayer = Farm.GetOwnerPlayer();
                containerUpdate.Clear();

                SetElementsForOpenUI(containerUpdate);

                bool open = CuiHelper.AddUi(OwnerPlayer, containerUpdate);

                if (open) currentSubPanelUI?.OpenUI();
                return open;
            }

            public virtual void CloseUI()
            {
                currentSubPanelUI?.CloseUI();
                CuiHelper.DestroyUi(OwnerPlayer, Name);
            }

            public virtual void SetElementsForOpenUI(List<CuiElement> list)
            {
                containerUpdate.AddRange(this);
            }
            public virtual void AddMenu(string key, ICommandsUIPanel panel)
            {

            }
            public virtual void CreateMenu()
            {

            }
            public virtual void ClickButton(params string[] args)
            {
                currentSubPanelUI?.ClickButton(args);
            }
            public T Get<T>() where T : BasePanelUI
            {
                return this as T;
            }

        }
        public interface ICommandsUIPanel
        {
            bool OpenUI();
            void CloseUI();
            void ClickButton(params string[] args);
            string commandButton { get; }
            string Name { get; }
            BasePlayer OwnerPlayer { get; }
            void AddMenu(string key, ICommandsUIPanel panel);
            void CreateMenu();
            T Get<T>() where T : BasePanelUI;
        }

