        public class ScrollPanelUIConfig : ImageUIConfig
        {
            protected const int orderScrollPanel = orderImage + 100;

            [JsonProperty(RU ? "Элемент прокрутки" : "Scroll element", Order = orderScrollPanel + 1)]
            public ScrollUiConfig ScrollElement;

            [JsonProperty(RU ? "Размер панели прокрутки (укажите 0, для автоматического подбора)" : "Scroll panel size (specify 0 for automatic selection)", Order = orderScrollPanel + 2)]
            public UISize SizeScroll;

            [JsonProperty(RU ? "Фон наполнения прокрутки" : "Fill background", Order = orderScrollPanel + 3)]
            public StyleImageConfig BackgroundContent = new();

            [JsonProperty(RU ? "Размер элемента в прокрутке" : "Element size in the scroll", Order = orderScrollPanel + 4)]
            public UISize SizeElement;

            [JsonProperty(RU ? "Количество столбцов" : "Number of columns", Order = orderScrollPanel + 5)]
            public int CountColumns;

            [JsonProperty(RU ? "Отступы по горизонтали" : "Horizontal margins", Order = orderScrollPanel + 6)]
            public float MarginHorizontal;

            [JsonProperty(RU ? "Отступы по вертикали" : "Vertical margins", Order = orderScrollPanel + 7)]
            public float MarginVertical;

            public CuiRectTransformComponent GetTransformContent(int countElements)
            {
                int x = countElements < CountColumns ? countElements : CountColumns;
                int y = Mathf.CeilToInt((float)countElements / CountColumns);
                UISize sizeContent = new UISize(MarginHorizontal + x * SizeElement.x + MarginHorizontal * x, MarginVertical + y * SizeElement.y + MarginVertical * y);
                CuiRectTransformComponent transformComponent = new()
                {
                    AnchorMin = $"0 {(ScrollElement.Horizontal && !ScrollElement.Vertical ? 0 : 1)}",
                    AnchorMax = $"{(ScrollElement.Vertical && !ScrollElement.Horizontal ? 1 : 0)} 1",
                    OffsetMin = $"0, {(ScrollElement.Vertical ? -(sizeContent.y < SizeScroll.y ? SizeScroll.y : sizeContent.y) : 0)}",
                    OffsetMax = $"{(ScrollElement.Horizontal ? (sizeContent.x < SizeScroll.x ? SizeScroll.x : sizeContent.x) : 0)} 0"
                };
                return transformComponent;
            }
            /// <summary>
            /// Добавляет основную фоновую панель прокрутки
            /// </summary>
            /// <param name="container"></param>
            /// <param name="parent">родительский слой</param>
            /// <param name="name">слой основной панели прокрутки</param>
            /// <param name="destroy">удаляемый слой при добавлении этого элемента</param>
            public void AddScrollBackgroundElement(List<CuiElement> container, string parent, string name, string destroy)
            {
                AddImageElement(container, parent, name, destroy);
            }
            /// <summary>
            /// Добавляет панель прокрутки
            /// </summary>
            /// <param name="container"></param>
            /// <param name="parent">слой основной фоновой панели прокрутки</param>
            /// <param name="name">слой панели прокрутки</param>
            /// <param name="destroy">удаляемый слой при добавлении этого элемента</param>
            /// <param name="countElements">количество элементов в прокрутке</param>
            public void AddScrollPanelElement(List<CuiElement> container, string parent, string name, string destroy, int countElements)
            {
                ScrollElement.AddScrollElement(container, parent, name, destroy, GetTransformContent(countElements));
            }
            /// <summary>
            /// Добавляет элементы в панель прокрутки
            /// </summary>
            /// <param name="container"></param>
            /// <param name="parent">слой панели прокрутки</param>
            /// <param name="name">слой контента прокрутки</param>
            /// <param name="partialNameElementContent">слой элемента прокрутки к которому добавляется индекс элемента</param>
            /// <param name="countElements">количество элементов в прокрутке</param>
            /// <param name="addElement">обратный вызов метода добавляющий элемент</param>
            public void AddContents(List<CuiElement> container, string parent, string name, string partialNameElementContent, int countElements, UnityAction<List<CuiElement>, int, string> addElement)
            {
                container.Add(new CuiElement
                {
                    Parent = parent,
                    Name = name,
                    DestroyUi = name,
                    Components =
                    {
                        GetTransformContent(countElements),
                        BackgroundContent.CreateCuiImageComponent()
                    }
                });
                int x = 0, y = 0;
                int columns = countElements < CountColumns ? countElements : CountColumns;
                for (int i = 0; i < countElements; i++)
                {
                    if (x == columns)
                    {
                        y++;
                        x = 0;
                    }
                    container.Add(CreateEmptyLayer(name, partialNameElementContent + i, partialNameElementContent + i, new CuiRectTransformComponent
                    {
                        AnchorMin = "0 1",
                        AnchorMax = "0 1",
                        OffsetMin = $"{MarginHorizontal + x * MarginHorizontal + x * SizeElement.x} -{MarginVertical + SizeElement.y + y * MarginVertical + y * SizeElement.y}",
                        OffsetMax = $"{MarginHorizontal + SizeElement.x + x * MarginHorizontal + x * SizeElement.x} -{MarginVertical + y * MarginVertical + y * SizeElement.y}"
                    }));
                    addElement(container, i, partialNameElementContent + i);
                    x++;
                }
            }
        }
        
