            public void AddProgress(List<CuiElement> container, string nameLayer, string nameProgressLayer, float progress)
            {
                CuiRectTransformComponent transform = FullScreenTransform;
                container.Add(new CuiElement
                {
                    Parent = nameLayer, Name = nameProgressLayer, DestroyUi = nameProgressLayer, Components =
                    {
                        transform, ProgressPanel.CreateCuiImageComponent()
                    }
