            public void AddSwitchButtonItemElement(
                List<CuiElement> container, string parent, string nameButtonLayer, string nameActivatedLayer,
                string nameIconLayer, string destroy, string command, int itemId, ulong skin, string closeLayer)
            {
                AddButtonElement(container, parent, nameButtonLayer, destroy, command, closeLayer);
                Icon.AddImageElement(container, nameButtonLayer, nameIconLayer, nameIconLayer);
                container.Add(new CuiElement
                {
                    Parent = nameIconLayer,
                    Name = nameIconLayer + ".item",
                    DestroyUi = nameIconLayer + ".item",
                    Components =
                    {
                        FullScreenTransform, new CuiImageComponent { Color = "1 1 1 1", ItemId = itemId, SkinId = skin }
                    }
                });
                container.Add(CreateEmptyLayer(nameButtonLayer, nameActivatedLayer, null, null));
            }
            public void AddActivated(List<CuiElement> container, string nameActivatedLayer, string nameLayer, bool activated)
            {
                StyleImageConfig cfg = activated ? ActiveElement : NotActiveElement;
                CuiElement element = new CuiElement
                {
                    Parent = nameActivatedLayer,
                    Name = nameLayer,
                    DestroyUi = nameLayer,
                    Components =
                    {
                        FullScreenTransform,
                        cfg.CreateCuiImageComponent(),
                    }
                };
                if (cfg.Outline.CanOutline)
                {
                    element.Components.Add(cfg.Outline.CreateOutlineComponent());
                }
                container.Add(element);
            }
        }
