        public class ItemUIConfig : ImageUIConfig
        {
            protected const int order = orderImage + 100;

            [JsonProperty(RU ? "Позиция иконки" : "Icon position", Order = order + 10)]
            public TransformUIConfig IconPosition;

            [JsonProperty(RU ? "Количество" : "Amount", Order = order + 20)]
            public TextUIConfig Amount;

            [JsonProperty(RU ? "Состояние предмета" : "Item condition", Order = order + 30)]
            public ProgressBarUIConfig Condition;

            public void AddItemElement(List<CuiElement> list, string parent, string iconPanelLayer,
                                       string iconLayer, string conditionLayer, string currentConditionLayer,
                                       string amountLayer, Item item)
            {
                if (item == null) return;
                AddItemElement(list, parent, iconPanelLayer, iconLayer, conditionLayer, currentConditionLayer,
                               amountLayer, item.info.itemid, item.skin, item.amount, item.hasCondition,
                               item.condition, item.maxCondition);
            }
            public void AddItemElement(List<CuiElement> list, string parent, string iconPanelLayer,
                                       string iconLayer, string conditionLayer, string currentConditionLayer,
                                       string amountLayer, int idItem, ulong skin, int amount, bool hasCondition,
                                       float condition, float maxCondition)
            {
                list.Add(CreateEmptyLayer(parent, iconPanelLayer, iconPanelLayer, IconPosition.GetCuiTransform()));
                list.Add(new CuiElement
                {
                    Parent = iconPanelLayer,
                    Name = iconLayer,
                    DestroyUi = iconLayer,
                    Components =
                    {
                        FullScreenTransform,
                        new CuiImageComponent
                        {
                            Color = "1 1 1 1",
                            ImageType = Image.Type.Simple,
                            ItemId = idItem,
                            SkinId = skin,
                        }
                    }
                });
                if (amount > 1) Amount.AddTextElement(list, parent, amountLayer, amountLayer, amount.ToString());
                if (hasCondition) Condition.AddProgressBarElement(list, parent, conditionLayer, currentConditionLayer, conditionLayer, condition / maxCondition);
            }
            public void AddItemElement(List<CuiElement> list, string parent, string iconPanelLayer,
                                       string iconLayer, string conditionLayer, string currentConditionLayer,
                                       string amountLayer, CuiElement icon, string amount, bool hasCondition,
                                       float condition, float maxCondition)
            {
                list.Add(CreateEmptyLayer(parent, iconPanelLayer, iconPanelLayer, IconPosition.GetCuiTransform()));
                list.Add(icon);
                icon.Parent = iconPanelLayer;
                icon.Name = iconLayer;
                icon.DestroyUi = iconLayer;
                Amount.AddTextElement(list, parent, amountLayer, amountLayer, amount);
                if (hasCondition) Condition.AddProgressBarElement(list, parent, conditionLayer, currentConditionLayer, conditionLayer, condition / maxCondition);
            }
        }

