        public class TransformUIConfig
        {
            protected const int orderTransform = 0;
            private const string NameElement = "Panel";

            public virtual string TypeElement => NameElement;

            [JsonProperty(RU ? "Относительная позиция (UpperLeft, UpperCenter, UpperRight, MiddleLeft, MiddleCenter, MiddleRight, LowerLeft, LowerCenter, LowerRight, FullScreen)" : "Relative position (UpperLeft, UpperCenter, UpperRight, MiddleLeft, MiddleCenter, MiddleRight, LowerLeft, LowerCenter, LowerRight, FullScreen)", Order = orderTransform)]
            public AnchorMode Anchor = AnchorMode.FullPanel;

            [JsonProperty(RU ? "Размер (в пикселях X-горизонталь, Y-вертикаль)" : "Size (in pixels, X is horizontal, Y is vertical)", Order = orderTransform + 1)]
            public UISize Size = new();

            [JsonProperty(RU ? "Смещение (в пикселях X-горизонталь, Y-вертикаль)" : "Offset (in pixels, X is horizontal, Y is vertical)", Order = orderTransform + 2)]
            public UISize Offset = new();

            [JsonIgnore] private CuiRectTransformComponent _cuiTransform;

            public virtual string AddCuiPanel(List<CuiElement> container, string parentLayer, string nameLayer, ref ComponentUI componentUI)
            {
                container.Add(CreateEmptyLayer(parentLayer, nameLayer, nameLayer, CreateGuiTransform()));
                return nameLayer;
            }
            public string AddCuiEmptyElement(List<CuiElement> container, string parentLayer, string nameLayer, string destroyLayer)
            {
                container.Add(CreateEmptyLayer(parentLayer, nameLayer, destroyLayer, CreateGuiTransform()));
                return nameLayer;
            }
            protected string GetParentElement(string nameLayer)
            {
                string typeElement = TypeElement;
                if (TypeElement == NameElement) return nameLayer;
                else return nameLayer + "." + typeElement;
            }

            public CuiRectTransformComponent GetCuiTransform()
            {
                return CreateGuiTransform();
            }

            public CuiRectTransformComponent CreateGuiTransform()
            {
                var size = Size / 2f;
                UISize min = Anchor == AnchorMode.FullPanel ? new() : ToScreen(Anchor), max = Anchor == AnchorMode.FullPanel ? new(1, 1) : ToScreen(Anchor);
                return new()
                {
                    AnchorMin = min.ToString(),
                    AnchorMax = max.ToString(),
                    OffsetMin = $"{-size.x + Offset.x} {-size.y + Offset.y}",
                    OffsetMax = $"{size.x + Offset.x} {size.y + Offset.y}"
                };
            }

            private UISize ToScreen(AnchorMode anchor)
            {
                switch (anchor)
                {
                    case AnchorMode.LowerLeft: return new();
                    case AnchorMode.LowerCenter: return new(0.5f, 0);
                    case AnchorMode.LowerRight: return new(1, 0);
                    case AnchorMode.MiddleLeft: return new(0, 0.5f);
                    case AnchorMode.MiddleCenter: return new(0.5f, 0.5f);
                    case AnchorMode.MiddleRight: return new(1, 0.5f);
                    case AnchorMode.UpperLeft: return new(0, 1);
                    case AnchorMode.UpperCenter: return new(0.5f, 1);
                    case AnchorMode.UpperRight: return new(1, 1);
                }

                return new();
            }

            public static TransformUIConfig GetFullScreen() => new()
            {
                Anchor = AnchorMode.FullPanel,
                Offset = new(),
                Size = new()
            };
            [JsonConverter(typeof(StringEnumConverter))]
            public enum AnchorMode
            {
                UpperLeft, UpperCenter, UpperRight, MiddleLeft, MiddleCenter, MiddleRight, LowerLeft, LowerCenter, LowerRight, FullPanel
            }
        }
