        public struct UIColor
        {
            [JsonProperty(RU ? "Цвет (для HEX в начале поставьте #)" : "Color (for HEX, put # at the beginning)")]
            private string color;

            public UIColor(string color)
            {
                this.color = color;
            }
            public Color GetUnityColor()
            {
                string[] col = GetColor(Type.Background).Split(" ");
                return new(float.Parse(col[0]), float.Parse(col[1]), float.Parse(col[2]), float.Parse(col[3]));
            }
            public static UIColor green(float alfa) => new UIColor($"0 1 0 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor greenRust(float alfa) => new UIColor($"0.55 0.78 0.24 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor red(float alfa) => new UIColor($"1 0 0 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor redRust(float alfa) => new UIColor($"0.8 0.28 0.2 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor blue(float alfa) => new UIColor($"0 0 1 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor blueRust(float alfa) => new UIColor($"0.2 0.21 0.62 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor white(float alfa) => new UIColor($"1 1 1 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor gray(float alfa) => new UIColor($"0.42 0.41 0.4 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor gray2(float alfa) => new UIColor($"0.32 0.31 0.3 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor gray3(float alfa) => new UIColor($"0.22 0.21 0.2 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor gray4(float alfa) => new UIColor($"0.12 0.11 0.1 {Mathf.Clamp(alfa, 0f, 1f)}");
            public static UIColor black(float alfa) => new UIColor($"0 0 0 {Mathf.Clamp(alfa, 0f, 1f)}");
            public bool HasColor() => !string.IsNullOrEmpty(color);
            public override string ToString() => color;
            public string GetColor(Type colorType) => GetColor(color, colorType);
            public static string GetColor(string inputColor, Type colorType = Type.Background)
            {
                if(string.IsNullOrEmpty(inputColor)) return GetDefaultColor(colorType);
                if(inputColor.ToCharArray()[0] == '#' && (inputColor.Length == 7 || inputColor.Length == 9))
                {
                    string newColor = HexToRustFormat(inputColor);
                    return newColor == null ? GetDefaultColor(colorType) : newColor;
                }
                return inputColor;
            }
            static string GetDefaultColor(Type colorType)
            {
                switch(colorType)
                {
                    case Type.Text: return DefaultColorText;
                    case Type.Image: return DefaultColorImage;
                    case Type.Background: return DefaultColorBackground;
                    default: return "0 0 0 0";
                }
            }
            public static string HexToRustFormat(string hex)
            {
                if (string.IsNullOrEmpty(hex))
                {
                    hex = "#FFFFFFFF";
                }

                var str = hex.Trim('#');

                if (str.Length == 6)
                    str += "FF";

                if (str.Length != 8)
                {
                    return null;
                }

                var r = byte.Parse(str.Substring(0, 2), System.Globalization.NumberStyles.HexNumber);
                var g = byte.Parse(str.Substring(2, 2), System.Globalization.NumberStyles.HexNumber);
                var b = byte.Parse(str.Substring(4, 2), System.Globalization.NumberStyles.HexNumber);
                var a = byte.Parse(str.Substring(6, 2), System.Globalization.NumberStyles.HexNumber);

                UnityEngine.Color color = new Color32(r, g, b, a);

                return string.Format("{0:F2} {1:F2} {2:F2} {3:F2}", color.r, color.g, color.b, color.a);
            }
            public enum Type
            {
                Text = 0,
                Image = 1,
                Background = 2
            }
        }
        public struct UISize
        {
            public float x, y;

            public UISize(float x, float y)
            {
                this.x = x;
                this.y = y;
            }

            public override string ToString()
            {
                return $"{x} {y}";
            }
            public override int GetHashCode()
            {
                return x.GetHashCode() ^ (y.GetHashCode() << 2);
            }
            public override bool Equals(object other)
            {
                if (!(other is UISize))
                {
                    return false;
                }

                return Equals((UISize)other);
            }
            public bool Equals(UISize other)
            {
                return x == other.x && y == other.y;
            }

            public static UISize zero => new(0, 0);
            public static UISize one => new(1, 1);
            public static UISize center => new(0.5f, 0.5f);

            public static UISize operator +(UISize a, UISize b)
            {
                return new UISize(a.x + b.x, a.y + b.y);
            }
            
            public static UISize operator -(UISize a, UISize b)
            {
                return new UISize(a.x - b.x, a.y - b.y);
            }
            
            public static UISize operator *(UISize a, UISize b)
            {
                return new UISize(a.x * b.x, a.y * b.y);
            }
            
            public static UISize operator /(UISize a, UISize b)
            {
                return new UISize(a.x / b.x, a.y / b.y);
            }
            
            public static UISize operator -(UISize a)
            {
                return new UISize(0f - a.x, 0f - a.y);
            }
            
            public static UISize operator *(UISize a, float d)
            {
                return new UISize(a.x * d, a.y * d);
            }
            
            public static UISize operator *(float d, UISize a)
            {
                return new UISize(a.x * d, a.y * d);
            }
            
            public static UISize operator /(UISize a, float d)
            {
                return new UISize(a.x / d, a.y / d);
            }
            
            public static bool operator ==(UISize lhs, UISize rhs)
            {
                float num = lhs.x - rhs.x;
                float num2 = lhs.y - rhs.y;
                return num * num + num2 * num2 < 9.9999994E-11f;
            }
            
            public static bool operator !=(UISize lhs, UISize rhs)
            {
                return !(lhs == rhs);
            }
            
            public static implicit operator UISize(Vector3 v)
            {
                return new UISize(v.x, v.y);
            }
        }
