        #region ImageLibrary
        [PluginReference] Core.Plugins.Plugin ImageLibrary;
        internal bool AddImage(string url, string name, ulong id = 0)
        {
            if(ImageLibrary == null || string.IsNullOrEmpty(url) || string.IsNullOrEmpty(name)) return false;
            if ((bool)ImageLibrary?.Call("AddImage", url, name, id))
            {
                #if DebugLog
                    Debug.Log(RU ? $"({nameof(AddImage)}) Картинка ({url})] - добавлена в кеш" : $"({nameof(AddImage)}) Image ({url})] - added to cache");
                #endif
                return true;
            }
            else
            {
                Debug.LogError(RU ? $"({nameof(AddImage)}) Не удалось добавить Url в кеш:[{url}]" : $"({nameof(AddImage)}) Failed to add Url to cache");
                return false;
            }
        }
        internal string GetImage(string imageName, ulong imageId = 0, bool returnUrl = false) => ImageLibrary?.Call<string>("GetImage", imageName, imageId, returnUrl);
        internal bool HasImage(string imageName, ulong imageId = 0) => (bool)ImageLibrary?.Call("HasImage", imageName, imageId);
        internal string GetPng(string url) => HasImage(url) || AddImage(url, url) ? GetImage(url) : url;
        #endregion

        #region DefaultColors
        const string DefaultColorBackground = "0.22 0.21 0.2 0";
        const string DefaultColorImage = "1 1 1 1";
        const string DefaultColorText = "1 1 1 1";
        #endregion
    }
#endregion

