    partial class PersonalFarmer
    {
        partial class FarmManager
        {
            private BasePlayer drawPlayer;
            private float timerDraw => 1.5f;
            private bool canDrawPath => true;
            private bool canDrawFarmNodes => false;
            private bool canDrawInfoNode => true;
            private bool canDrawLinks => false;
            private float drawDistancce => 5f;
            private int layerObstacleDraw = LayerMask.GetMask("Construction");
            private void DrawFarm()
            {
                if (!drawPlayer) drawPlayer = Farmer.GetOwnerPlayer;
                if (drawPlayer?.IsConnected != true) return;

                bool isAdmin = drawPlayer.IsAdmin;
                if (!isAdmin) drawPlayer.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, true);

                drawPlayer?.SendConsoleCommand("ddraw.sphere", timerDraw, Color.blue, Navigation?.RiverPoint, 1f);

                DrawMap();
                if (canDrawPath) Farmer?.DrawPath(drawPlayer, timerDraw);

                if (!isAdmin) drawPlayer.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, false);
            }
            private string GetInfoNode(NavigationFarm.FarmPointNode node)
            {
                string text = node.Position.ToString() + "    ID=" + node.IdBlock;
                if(node.HasFlag(NavigationFarm.FarmPointNode.Flag.CanAddLinks)) text += "\n" + "CanAddLinks";
                if(node.HasFlag(NavigationFarm.FarmPointNode.Flag.IsExternal)) text += "\n" + "External";
                if(node.HasFlag(NavigationFarm.FarmPointNode.Flag.IsExitPoint)) text += "\n" + "ExitPoint";
                if(node.HasFlag(NavigationFarm.FarmPointNode.Flag.HasGround)) text += "\n" + "HasGround";
                if(node.HasFlag(NavigationFarm.FarmPointNode.Flag.IsGroundNode)) text += "\n" + "GroundNode";
                if(node.HasFlag(NavigationFarm.FarmPointNode.Flag.IsHighly)) text += "\n" + "Highly";
                if(node.HasFlag(NavigationFarm.FarmPointNode.Flag.IsVeryHighly)) text += "\n" + "VeryHighly";
                if(node.HasFlag(NavigationFarm.FarmPointNode.Flag.IsHatch)) text += "\n" + "Hatch";
                return text;
            }
            private void DrawMap()
            {
                if (!IsInitFarm || (!canDrawFarmNodes && !canDrawLinks)) return;
                Dictionary<NavigationFarm.FarmPointNode, NavigationFarm.FarmPointNode.Links> links = Pool.Get<Dictionary<NavigationFarm.FarmPointNode, NavigationFarm.FarmPointNode.Links>>();
                Sphere sphere = new(drawPlayer.ServerPosition, drawDistancce);
                foreach (var point in Navigation.GetNodes(sphere))
                {
                    if (links.TryAdd(point, point.GetLinks()) && canDrawFarmNodes)
                    {
                        Color color = point.IsGroundNode ? Color.black : point.IsConnected ? point.HasLinks() ? Color.green : Color.yellow : Color.red;
                        if(canDrawInfoNode) drawPlayer?.SendConsoleCommand("ddraw.sphere", timerDraw, color, point.Position, 0.1f);
                        if(!Physics.Linecast(drawPlayer.eyes.HeadRay().origin, point.Position - (point.Position - drawPlayer.eyes.HeadRay().origin).normalized * 0.2f, layerObstacleDraw)) drawPlayer?.SendConsoleCommand("ddraw.text", timerDraw, Color.blue, point.Position + Vector3.up * 0.2f, GetInfoNode(point));
                    }
                }

                if (canDrawLinks)
                {
                    List<(Vector3, Vector3)> points = Pool.Get<List<(Vector3, Vector3)>>();
                    foreach (var point in links)
                    {
                        foreach (var link in point.Value)
                        {
                            if(link.Node == point.Key) continue;
                            if (points.Exists(x => (x.Item1 == point.Key.Position && x.Item2 == link.Node.Position) || (x.Item1 == link.Node.Position && x.Item2 == point.Key.Position)))
                            {
                                // Debug.LogTest($"link: {point.Key} / {link.Node.Position}");
                                continue;
                            }
                            Navigation.TryGetFarmNode(link.Node.Position, out var node);
                            Color color = node?.HasLink(point.Key.Position) == true ? Color.blue : Color.yellow;
                            drawPlayer?.SendConsoleCommand("ddraw.line", timerDraw, color, point.Key.Position, link.Node.Position);
                            points.Add((link.Node.Position, point.Key.Position));
                        }
                    }
                    Pool.FreeUnmanaged(ref points);
                }
                Pool.FreeUnmanaged(ref links);

            }
            protected void DrawSphereCast(BasePlayer admin, float timer, Vector3 start, Vector3 end, float radius, Color colorDetect)
            {
                admin?.SendConsoleCommand("ddraw.sphere", timer, colorDetect, end, radius);
                admin?.SendConsoleCommand("ddraw.line", timer, Color.blue, start, end);
            }
        }
