            {
                if(pathController.HasPath)
                {
                    pathController.DrawPath(admin, Color.green, Color.yellow, Color.blue, 0.2f, timer);
                    pathController.DrawCurrentPointFarmer(admin, Color.white, 0.3f, timer);
                }
