            partial class PathController
            {
                public void DrawPath(BasePlayer player, Color colorPoint, Color colorCurrentPoint, Color colorLinks, float radius, float deltaTime)
                {
                    Vector3 startPos = _path[0];
                    for (int i = 0; i < _path.Length; i++)
                    {
                        Vector3 from = (i == 0) ? startPos : _path[i - 1];
                        Vector3 to = _path[i];
                        player?.SendConsoleCommand("ddraw.line", deltaTime, colorLinks, from, to);
                        if(Index == i) DrawCurrentPoint(player, colorCurrentPoint, radius, deltaTime);
                        else player?.SendConsoleCommand("ddraw.sphere", deltaTime, colorPoint, to, radius);
                    }
                }
