                {
                    player?.SendConsoleCommand("ddraw.sphere", deltaTime, colorPoint, Current, radius);
                }
                public void DrawCurrentPointFarmer(BasePlayer player, Color colorPoint, float radius, float deltaTime)
                {
                    player?.SendConsoleCommand("ddraw.sphere", deltaTime, colorPoint, CurrentFarmer, radius);
                }
                public void DrawLastPoint(BasePlayer player, Color colorPoint, float radius, float deltaTime)
                {
                    player?.SendConsoleCommand("ddraw.sphere", deltaTime, colorPoint, Current, radius);
                }
            }
        }
    }
#endregion
#endif
}
namespace Oxide.Plugins.PersonalFarmerEx
{
    public static class PersonalFarmerEx
    {
        public static Dictionary<TKey, TVal> GetPoolNodes<TKey, TVal>(this Dictionary<TKey, TVal> dictionary) where TVal : class, Pool.IPooled, new()
        {
            if (dictionary == null) return Pool.Get<Dictionary<TKey, TVal>>();
            foreach (var item in dictionary.Values)
            {
                if (item != null)
                {
                    TVal val = item;
                    Pool.Free(ref val);
                }
            }
            dictionary.Clear();
            return dictionary;
        }
        public static string ToStringTime(this TimeSince dateTime)
        {
            int d = (int)(dateTime / 86400);
            int h = (int)(dateTime % 86400 / 3600);
            int m = (int)(dateTime % 86400 % 3600 / 60);
            int s = (int)(dateTime % 86400 % 3600 % 60);
            return $"days: {d:0}   time: {h:00}:{m:00}:{s:00}";
        }
        public static string ToStringTime(this float dateTime)
        {
            int d = (int)(dateTime / 86400);
            int h = (int)(dateTime % 86400 / 3600);
            int m = (int)(dateTime % 86400 % 3600 / 60);
            int s = (int)(dateTime % 86400 % 3600 % 60);
            return $"days: {d:0}   time: {h:00}:{m:00}:{s:00}";
        }
        public static int IndexOff<T1, T2>(this Dictionary<T1, T2> dictionary, T1 item) where T1 : new() where T2 : new()
        {
            int index = 0;
            foreach (var i in dictionary.Keys)
            {
                if (i.Equals(item)) return index;
                index++;
            }
            throw new Exception("Index not found");
        }
        public static bool TryGetNearestSurfacePoint(this PathList water, Vector3 point, out Vector3 nearestPoint)
        {
            nearestPoint = Vector3.zero;

            foreach (Vector3 p in water.Path.Points)
            {
                if (Vector3.Distance(p, point) < Vector3.Distance(nearestPoint, point)) nearestPoint = p;
            }
            return nearestPoint != Vector3.zero;
        }
        public static Item FindItemByItemUI(this PlayerInventory inventory, PersonalFarmer.ItemUI itemDef)
        {
            if (itemDef?.GetItemDefinition() == null) return null;
            Item item = inventory?.containerMain.itemList.Find(x => x.info == itemDef.GetItemDefinition() && x.skin == itemDef.Item.SkinID);
            if (item == null) item = inventory?.containerBelt.itemList.Find(x => x.info == itemDef.GetItemDefinition() && x.skin == itemDef.Item.SkinID);
            if (item == null) item = inventory?.containerWear.itemList.Find(x => x.info == itemDef.GetItemDefinition() && x.skin == itemDef.Item.SkinID);
            return item;
        }
        public static Item FindItemByItemUI(this ItemContainer inventory, PersonalFarmer.ItemUI itemDef)
        {
            if (itemDef?.GetItemDefinition() == null) return null;
            return inventory?.itemList.Find(x => x.info == itemDef.GetItemDefinition() && x.skin == itemDef.Item.SkinID);
        }
        public static bool HasItemUI(this ItemContainer inventory, PersonalFarmer.ItemUI itemDef)
        {
            if (itemDef?.GetItemDefinition() == null) return false;
            for (int i = 0; i < inventory.itemList.Count; i++)
            {
                Item item = inventory.itemList[i];
                if (item.info == itemDef.GetItemDefinition() && item.skin == itemDef.Item.SkinID && item.amount > 0)
                {
                    return true;
                }
            }

            return false;
        }
        public static bool HasItem(this PlayerInventory inventory, ItemDefinition itemDef)
        {
            if (itemDef == null) return false;
            return inventory.containerMain.HasItem(itemDef) || inventory.containerBelt.HasItem(itemDef);
        }
        public static bool HasItemsToFoodChickens(this PlayerInventory inventory, PersonalFarmer.FarmManager farm)
        {
            if(farm == null) return false;
            return inventory.containerMain.itemList.Exists(x => farm.CanFoodToChickens(x)) || inventory.containerBelt.itemList.Exists(x => farm.CanFoodToChickens(x));
        }
        public static bool TryGetItemToFoodChickens(this PlayerInventory inventory, PersonalFarmer.FarmManager farm, out ItemDefinition item)
        {
            item = null;
            if (farm == null) return false;
            item = inventory.containerMain.itemList.Find(x => farm.CanFoodToChickens(x))?.info;
            if (item == null) item = inventory.containerBelt.itemList.Find(x => farm.CanFoodToChickens(x))?.info;
            return item != null;
        }
        public static bool TryGetItemToFoodChickens(this ItemContainer inventory, PersonalFarmer.FarmManager farm, out ItemDefinition item)
        {
            item = null;
            if (farm == null) return false;
            item = inventory.itemList.Find(x => farm.CanFoodToChickens(x))?.info;
            return item != null;
        }
        public static int GetAmount(this PlayerInventory inventory, PersonalFarmer.ItemUI itemDef)
        {
            if (itemDef?.GetItemDefinition() == null) return 0;

            int num = 0;
            if (inventory.containerMain != null)
            {
                num += inventory.containerMain.GetAmount(itemDef, onlyUsableAmounts: true);
            }

            if (inventory.containerBelt != null)
            {
                num += inventory.containerBelt.GetAmount(itemDef, onlyUsableAmounts: true);
            }

            if (inventory.containerWear != null)
            {
                num += inventory.containerWear.GetAmount(itemDef, onlyUsableAmounts: true);
            }

            return num;
        }
        public static int GetAmount(this ItemContainer inventory, PersonalFarmer.ItemUI itemDef, bool onlyUsableAmounts)
        {
            if (itemDef?.GetItemDefinition() == null) return 0;
            int num = 0;
            foreach (Item item in inventory.itemList)
            {
                if (item.info.itemid == itemDef.GetItemDefinition().itemid && item.skin == itemDef.Item.SkinID && (!onlyUsableAmounts || !item.IsBusy()))
                {
                    num += item.amount;
                }
            }

            return num;
        }
        public static void MoveAllItems(this ItemContainer owner,  ItemContainer target, Func<Item, bool> filter)
        {
            foreach (Item item in owner.itemList.ToArray())
            {
                if (filter == null || filter(item)) item.MoveToContainer(target);
            }
        }
        /// <summary>
        /// Сортирует коллекцию по свойству ShortName (строго типизировано).
        /// </summary>
        public static List<T> OrderBy<T>(this List<T> source, Func<T, string> keySelector)
            where T : class
        {
            source.Sort((a, b) => string.Compare(keySelector(a), keySelector(b), StringComparison.Ordinal));
            return source;
        }
        public static bool ContainsVector3(this Rect rect, Vector3 point)
        {
            return point.x >= rect.xMin && point.x < rect.xMax && point.z >= rect.yMin && point.z < rect.yMax;
        }
        public static string[] Skip(this string[] source, int count)
        {
            if (source.Length == 0) return Array.Empty<string>();
            string[] result = new string[source.Length - count];
            int n = 0;
            for (int i = 0; i < source.Length; i++)
            {
                if (i < count) continue;
                result[n] = source[i];
                n++;
            }
            return result;
        }
        public static float Distance(this List<Vector3> source)
        {
            if (source == null)
            {
                throw Error.ArgumentNull("source");
            }
            int count = source.Count;
            if (count <= 1) return 0f;
            float result = 0;
            for (int i = 1; i < count; i++)
            {
                result += (source[i] - source[i - 1]).magnitude;
            }
            return result;
        }
        public static float Distance(this Vector3[] source)
        {
            if (source == null)
            {
                throw Error.ArgumentNull("source");
            }
            int count = source.Length;
            if(count <= 1) return 0f;
            float result = 0;
            for(int i = 1; i < count; i++)
            {
                result += (source[i] - source[i - 1]).magnitude;
            }
            return result;
        }
        public static TSource ElementAt<TSource>(this IEnumerable<TSource> source, int index)
        {
            int movements = 0;
            using (var enumerator = source.GetEnumerator())
            {
                while (enumerator.MoveNext())
                {
                    if (movements == index) return enumerator.Current;
                    movements++;
                }
            }
            return default(TSource);
        }
        public static TSource Min<TSource>(this IEnumerable<TSource> source, Func<TSource, float> predicate)
        {
            TSource result = source.ElementAt(0);
            float resultValue = predicate(result);
            using (var enumerator = source.GetEnumerator())
            {
                while (enumerator.MoveNext())
                {
                    TSource element = enumerator.Current;
                    float elementValue = predicate(element);
                    if (elementValue < resultValue)
                    {
                        result = element;
                        resultValue = elementValue;
                    }
                }
            }
            return result;
        }
        public static TSource Max<TSource>(this IEnumerable<TSource> source, Func<TSource, float> predicate)
        {
            TSource result = source.ElementAt(0);
            float resultValue = predicate(result);
            using (var enumerator = source.GetEnumerator())
            {
                while (enumerator.MoveNext())
                {
                    TSource element = enumerator.Current;
                    float elementValue = predicate(element);
                    if (elementValue > resultValue)
                    {
                        result = element;
                        resultValue = elementValue;
                    }
                }
            }
            return result;
        }
        public static int GetAmount(this ItemContainer container, int itemid, ulong skin, bool onlyUsableAmounts)
        {
            int num = 0;
            foreach (Item item in container.itemList)
            {
                if (item.info.itemid == itemid && item.skin == skin && (!onlyUsableAmounts || !item.IsBusy()))
                {
                    num += item.amount;
                }
            }

            return num;
        }

        internal static class Error
        {
            internal static Exception ArgumentNull(string s)
            {
                return new ArgumentNullException(s);
            }
            internal static Exception NoElements()
            {
                return new InvalidOperationException("Sequence contains no elements");
            }
            internal static Exception OutOfRange()
            {
                return new InvalidOperationException("index out of range");
            }
        }
